#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct OrganicMosaicRelationObservation {
    /// Canonical receipts of the retained formations related by this one
    /// current physical frontier. Receipts identify observation evidence;
    /// they do not cause or persist the relationship.
    pub(crate) formation_receipts: Vec<[u8; 32]>,
    pub(crate) shared_lineages: Vec<[u8; 16]>,
    pub(crate) active_bonds: Vec<StablePhysicalBondReference>,
    /// Stable physical identity of the related retained member sets, shared
    /// lineages, and active bonds. Unlike formation receipts, this does not
    /// include the changing latest-recurrence witness.
    pub(crate) structural_relation_receipt: [u8; 32],
    /// Exact two-contact continuations completed across adjacent physical
    /// intervals and spanning at least two formations in this relation. These
    /// are transient observer evidence; they are neither retained formations
    /// nor transition authority.
    pub(crate) ordered_physical_paths: Vec<OrderedPhysicalPathObservation>,
    /// Exact earlier/current two-contact path recurrences spanning this
    /// recurrent relation. This is bounded immediate propagation evidence,
    /// never a retained thought or sequence object.
    pub(crate) ordered_path_relations: Vec<OrderedPathRelationObservation>,
}

/// The exact cause retained across one electrical propagation boundary.
/// Historical V19 bodies know only the receiver and therefore carry `None`;
/// such an entry may continue ordinary propagation but can never prove order.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct ActiveElectricalFrontierEntry {
    receiver: [u8; 16],
    cause: Option<DirectedElectricalFrontierCause>,
}

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct DirectedElectricalFrontierCause {
    bond: StablePhysicalBondReference,
    transferred_whole_carriers: u128,
    frontier_is_sender: bool,
    body_owned_acoustic_efference: bool,
    external_ingress_cause: bool,
}

impl ActiveElectricalFrontierEntry {
    fn legacy_receiver(receiver: [u8; 16]) -> Self {
        Self {
            receiver,
            cause: None,
        }
    }

    fn caused(
        sender: [u8; 16],
        receiver: [u8; 16],
        bond: StablePhysicalBondReference,
        transferred_whole_carriers: u128,
    ) -> Result<Self, FormationError> {
        let (left, right) = bond.endpoints();
        if transferred_whole_carriers == 0
            || !((sender == left && receiver == right) || (sender == right && receiver == left))
        {
            return Err(FormationError::NoncanonicalState);
        }
        Ok(Self {
            receiver,
            cause: Some(DirectedElectricalFrontierCause {
                bond,
                transferred_whole_carriers,
                frontier_is_sender: false,
                body_owned_acoustic_efference: false,
                external_ingress_cause: false,
            }),
        })
    }

    fn caused_with_frontier(
        sender: [u8; 16],
        receiver: [u8; 16],
        frontier: [u8; 16],
        bond: StablePhysicalBondReference,
        transferred_whole_carriers: u128,
        body_owned_acoustic_efference: bool,
    ) -> Result<Self, FormationError> {
        Self::caused_with_provenance(
            sender,
            receiver,
            frontier,
            bond,
            transferred_whole_carriers,
            body_owned_acoustic_efference,
            false,
        )
    }

    fn caused_with_provenance(
        sender: [u8; 16],
        receiver: [u8; 16],
        frontier: [u8; 16],
        bond: StablePhysicalBondReference,
        transferred_whole_carriers: u128,
        body_owned_acoustic_efference: bool,
        external_ingress_cause: bool,
    ) -> Result<Self, FormationError> {
        if body_owned_acoustic_efference && external_ingress_cause {
            return Err(FormationError::NoncanonicalState);
        }
        let mut entry = Self::caused(sender, receiver, bond, transferred_whole_carriers)?;
        let cause = entry
            .cause
            .as_mut()
            .ok_or(FormationError::NoncanonicalState)?;
        cause.frontier_is_sender = if frontier == sender {
            true
        } else if frontier == receiver {
            false
        } else {
            return Err(FormationError::NoncanonicalState);
        };
        cause.body_owned_acoustic_efference = body_owned_acoustic_efference;
        cause.external_ingress_cause = external_ingress_cause;
        Ok(entry)
    }

    fn in_flight(
        sender: [u8; 16],
        receiver: [u8; 16],
        bond: StablePhysicalBondReference,
    ) -> Result<Self, FormationError> {
        Self::causal_in_flight(sender, receiver, sender, bond)
    }

    fn causal_in_flight(
        sender: [u8; 16],
        receiver: [u8; 16],
        frontier: [u8; 16],
        bond: StablePhysicalBondReference,
    ) -> Result<Self, FormationError> {
        Self::causal_in_flight_with_provenance(sender, receiver, frontier, bond, false, false)
    }

    fn causal_in_flight_with_provenance(
        sender: [u8; 16],
        receiver: [u8; 16],
        frontier: [u8; 16],
        bond: StablePhysicalBondReference,
        body_owned_acoustic_efference: bool,
        external_ingress_cause: bool,
    ) -> Result<Self, FormationError> {
        if body_owned_acoustic_efference && external_ingress_cause {
            return Err(FormationError::NoncanonicalState);
        }
        let (left, right) = bond.endpoints();
        if !((sender == left && receiver == right) || (sender == right && receiver == left)) {
            return Err(FormationError::NoncanonicalState);
        }
        let frontier_is_sender = if frontier == sender {
            true
        } else if frontier == receiver {
            false
        } else {
            return Err(FormationError::NoncanonicalState);
        };
        Ok(Self {
            receiver,
            cause: Some(DirectedElectricalFrontierCause {
                bond,
                transferred_whole_carriers: 0,
                frontier_is_sender,
                body_owned_acoustic_efference,
                external_ingress_cause,
            }),
        })
    }

    fn receiver(self) -> [u8; 16] {
        self.receiver
    }

    fn sender(self) -> Option<[u8; 16]> {
        let cause = self.cause?;
        let (left, right) = cause.bond.endpoints();
        if self.receiver == left {
            Some(right)
        } else if self.receiver == right {
            Some(left)
        } else {
            None
        }
    }

    fn frontier_lineage(self) -> [u8; 16] {
        self.cause
            .filter(|cause| cause.frontier_is_sender)
            .and_then(|_| self.sender())
            .unwrap_or(self.receiver)
    }

    fn affected_lineages(self) -> [Option<[u8; 16]>; 2] {
        [Some(self.frontier_lineage()), None]
    }

    fn carries_body_owned_acoustic_efference(self) -> bool {
        self.cause
            .is_some_and(|cause| cause.body_owned_acoustic_efference)
    }

    fn carries_external_ingress_cause(self) -> bool {
        self.cause.is_some_and(|cause| cause.external_ingress_cause)
    }

    fn is_in_flight(self) -> bool {
        self.cause.is_some_and(|cause| {
            cause.transferred_whole_carriers == 0
                && cause.frontier_is_sender
                && !cause.body_owned_acoustic_efference
        })
    }

    fn is_zero_carrier_frontier(self) -> bool {
        self.cause.is_some_and(|cause| {
            cause.transferred_whole_carriers == 0 && !cause.body_owned_acoustic_efference
        })
    }

    fn directed_transfer(self) -> Option<DirectedPhysicalTransferObservation> {
        let cause = self.cause?;
        if cause.transferred_whole_carriers == 0 {
            return None;
        }
        Some(DirectedPhysicalTransferObservation {
            sender: self.sender()?,
            receiver: self.receiver,
            bond: cause.bond,
            transferred_whole_carriers: cause.transferred_whole_carriers,
        })
    }

    fn encoded_v20_len(self) -> usize {
        1 + 16
            + if self.cause.is_some() {
                16 + 16 + 4 + 16
            } else {
                0
            }
    }

    fn encode_v20(self, output: &mut Vec<u8>) {
        output.push(match self.cause {
            None => 0,
            Some(cause) => match (
                cause.frontier_is_sender,
                cause.body_owned_acoustic_efference,
                cause.external_ingress_cause,
            ) {
                (false, false, false) => 1,
                (true, false, false) => 2,
                (false, true, false) => 3,
                (true, true, false) => 4,
                (false, false, true) => 5,
                (true, false, true) => 6,
                (_, true, true) => unreachable!("frontier cause provenance is exclusive"),
            },
        });
        output.extend_from_slice(&self.receiver);
        if let Some(cause) = self.cause {
            let (left, right) = cause.bond.endpoints();
            output.extend_from_slice(&left);
            output.extend_from_slice(&right);
            output.extend_from_slice(&cause.bond.parallel_ordinal().to_le_bytes());
            output.extend_from_slice(&cause.transferred_whole_carriers.to_le_bytes());
        }
    }

    fn decode_v20(
        bytes: &[u8],
        cursor: &mut usize,
        allow_sender_frontier: bool,
        allow_in_flight_frontier: bool,
        allow_external_ingress_cause: bool,
    ) -> Result<Self, FormationError> {
        let tag = *bytes
            .get(*cursor)
            .ok_or(FormationError::NoncanonicalState)?;
        *cursor = cursor
            .checked_add(1)
            .ok_or(FormationError::ArithmeticOverflow)?;
        let receiver_end = cursor
            .checked_add(16)
            .ok_or(FormationError::ArithmeticOverflow)?;
        let receiver = bytes
            .get(*cursor..receiver_end)
            .ok_or(FormationError::NoncanonicalState)?
            .try_into()
            .map_err(|_| FormationError::NoncanonicalState)?;
        *cursor = receiver_end;
        match tag {
            0 => Ok(Self::legacy_receiver(receiver)),
            1 | 2 | 3 | 4 | 5 | 6
                if (matches!(tag, 1 | 3 | 5) || allow_sender_frontier)
                    && (!matches!(tag, 5 | 6) || allow_external_ingress_cause) =>
            {
                let left_end = cursor
                    .checked_add(16)
                    .ok_or(FormationError::ArithmeticOverflow)?;
                let left = bytes
                    .get(*cursor..left_end)
                    .ok_or(FormationError::NoncanonicalState)?
                    .try_into()
                    .map_err(|_| FormationError::NoncanonicalState)?;
                *cursor = left_end;
                let right_end = cursor
                    .checked_add(16)
                    .ok_or(FormationError::ArithmeticOverflow)?;
                let right = bytes
                    .get(*cursor..right_end)
                    .ok_or(FormationError::NoncanonicalState)?
                    .try_into()
                    .map_err(|_| FormationError::NoncanonicalState)?;
                *cursor = right_end;
                let ordinal_end = cursor
                    .checked_add(4)
                    .ok_or(FormationError::ArithmeticOverflow)?;
                let parallel_ordinal = u32::from_le_bytes(
                    bytes
                        .get(*cursor..ordinal_end)
                        .ok_or(FormationError::NoncanonicalState)?
                        .try_into()
                        .map_err(|_| FormationError::NoncanonicalState)?,
                );
                *cursor = ordinal_end;
                let carrier_end = cursor
                    .checked_add(16)
                    .ok_or(FormationError::ArithmeticOverflow)?;
                let transferred_whole_carriers = u128::from_le_bytes(
                    bytes
                        .get(*cursor..carrier_end)
                        .ok_or(FormationError::NoncanonicalState)?
                        .try_into()
                        .map_err(|_| FormationError::NoncanonicalState)?,
                );
                *cursor = carrier_end;
                let bond = StablePhysicalBondReference::new(left, right, parallel_ordinal)
                    .ok_or(FormationError::NoncanonicalState)?;
                let sender = if receiver == left {
                    right
                } else if receiver == right {
                    left
                } else {
                    return Err(FormationError::NoncanonicalState);
                };
                let mut entry = if transferred_whole_carriers == 0 {
                    if !allow_in_flight_frontier || !matches!(tag, 1 | 2 | 5 | 6) {
                        return Err(FormationError::NoncanonicalState);
                    }
                    Self::causal_in_flight(
                        sender,
                        receiver,
                        if matches!(tag, 2 | 6) {
                            sender
                        } else {
                            receiver
                        },
                        bond,
                    )?
                } else {
                    Self::caused(sender, receiver, bond, transferred_whole_carriers)?
                };
                entry
                    .cause
                    .as_mut()
                    .ok_or(FormationError::NoncanonicalState)?
                    .frontier_is_sender = matches!(tag, 2 | 4 | 6);
                entry
                    .cause
                    .as_mut()
                    .ok_or(FormationError::NoncanonicalState)?
                    .body_owned_acoustic_efference = matches!(tag, 3 | 4);
                entry
                    .cause
                    .as_mut()
                    .ok_or(FormationError::NoncanonicalState)?
                    .external_ingress_cause = matches!(tag, 5 | 6);
                Ok(entry)
            }
            _ => Err(FormationError::NoncanonicalState),
        }
    }
}

fn incoming_frontier_bonds(
    frontier: &[ActiveElectricalFrontierEntry],
) -> BTreeSet<([u8; 16], StablePhysicalBondReference)> {
    frontier
        .iter()
        .filter_map(|entry| {
            entry
                .cause
                .map(|cause| (entry.frontier_lineage(), cause.bond))
        })
        .collect()
}

fn frontier_crossing_advances(
    incoming: &BTreeSet<([u8; 16], StablePhysicalBondReference)>,
    seed_lineage: [u8; 16],
    bond: StablePhysicalBondReference,
    freshly_seeded: bool,
) -> bool {
    freshly_seeded || !incoming.contains(&(seed_lineage, bond))
}

/// Identify the one causal boundary crossed by a settled contact.
///
/// Electrical maintenance may settle a contact with zero, one, or two causal
/// endpoints. Only exactly one causal endpoint can advance the organism's
/// cognitive frontier. In particular, a scheduler-selected contact with no
/// causal endpoint remains physics and can never manufacture action authority.
fn causal_frontier_crossing(
    left_flat: usize,
    right_flat: usize,
    left_is_seed: bool,
    right_is_seed: bool,
) -> Option<(usize, usize)> {
    if left_is_seed == right_is_seed {
        None
    } else if left_is_seed {
        Some((left_flat, right_flat))
    } else {
        Some((right_flat, left_flat))
    }
}

fn encoded_directed_frontier_len(frontier: &[ActiveElectricalFrontierEntry]) -> Option<usize> {
    frontier.iter().try_fold(8usize, |total, entry| {
        total.checked_add(entry.encoded_v20_len())
    })
}

fn encode_directed_frontier(
    frontier: &[ActiveElectricalFrontierEntry],
    output: &mut Vec<u8>,
) -> Result<(), FormationError> {
    push_length(output, frontier.len())?;
    for entry in frontier {
        entry.encode_v20(output);
    }
    Ok(())
}

fn decode_directed_frontier(
    bytes: &[u8],
    cursor: &mut usize,
    allow_sender_frontier: bool,
    allow_in_flight_frontier: bool,
    allow_external_ingress_cause: bool,
) -> Result<Vec<ActiveElectricalFrontierEntry>, FormationError> {
    let count = read_length(bytes, cursor)?;
    if count > bytes.len().saturating_sub(*cursor) / 17 {
        return Err(FormationError::NoncanonicalState);
    }
    let mut frontier = Vec::new();
    frontier
        .try_reserve_exact(count)
        .map_err(|_| FormationError::ArithmeticOverflow)?;
    for _ in 0..count {
        frontier.push(ActiveElectricalFrontierEntry::decode_v20(
            bytes,
            cursor,
            allow_sender_frontier,
            allow_in_flight_frontier,
            allow_external_ingress_cause,
        )?);
    }
    Ok(frontier)
}

