#[derive(Clone)]
struct ReachedLayerTenGradientSettlement {
    neuron_lineage: [u8; 16],
    neuron_place: DeclaredNeuronPlace,
    predecessor_separated_elementary_charges: i128,
    post_gradient_separated_elementary_charges: i128,
    metabolic: ReachedCohortMetabolicObservation,
}

fn local_gradient_direction(
    settlements: &[ReachedLayerTenGradientSettlement],
    lineage: [u8; 16],
) -> LocalGradientDirection {
    settlements
        .iter()
        .find(|settlement| settlement.neuron_lineage == lineage)
        .map_or(LocalGradientDirection::Quiescent, |settlement| {
            match (
                settlement.metabolic.pumped_elementary_charges != 0,
                settlement.metabolic.returned_elementary_charges != 0,
            ) {
                (true, false) => LocalGradientDirection::ActivePump,
                (false, true) => LocalGradientDirection::PassiveReturn,
                (false, false) | (true, true) => LocalGradientDirection::Quiescent,
            }
        })
}

/// Return the exact physical transfers that can prepare one mounted motor.
///
/// Layer 11 carries an internally ordered action preparation. The explicitly
/// identified layer-8 lines carry only this motor's mounted terminal-paired
/// reflex: reacted load or directional root receptor -> local integration ->
/// body regulation -> motor.
/// Both are real contact-local causes only when carrier transfer arrives at
/// the motor. A retained layer-11 ordering cell is itself the resident cause:
/// requiring it to be relabelled as fresh external or frontier input in the
/// same interval would prevent an internally retained thought from acting.
/// Layer-8 reflex preparation remains tied to this occurrence's exact reached
/// regulation. Motor-to-neighbour flow is a consequence, never preparation.
/// Tonic position regulation and every other layer remain ineligible; no
/// observation, score, or action label can prepare a motor through this
/// boundary.
fn exact_motor_preparation_transfers(
    motor_lineage: [u8; 16],
    settled_directed_transfers: &[DirectedPhysicalTransferObservation],
    permitted_regulation_lineages: &[[u8; 16]],
    fresh_seed_lineages: &BTreeSet<[u8; 16]>,
    permitted_vocal_ordering_lineages: Option<&BTreeSet<[u8; 16]>>,
    permitted_vocal_motor_bonds: Option<&BTreeSet<StablePhysicalBondReference>>,
    layer_of: impl Fn([u8; 16]) -> Option<u32>,
) -> Vec<DirectedPhysicalTransferObservation> {
    let mut preparation_transfers = settled_directed_transfers
        .iter()
        .copied()
        .filter(|transfer| {
            if transfer.receiver != motor_lineage {
                return false;
            }
            let adjacent_layer = layer_of(transfer.sender);
            matches!(adjacent_layer, Some(11))
                && permitted_vocal_ordering_lineages
                    .is_none_or(|lineages| lineages.contains(&transfer.sender))
                && permitted_vocal_motor_bonds.is_none_or(|bonds| bonds.contains(&transfer.bond))
                || fresh_seed_lineages.contains(&transfer.sender)
                    && matches!(adjacent_layer, Some(8))
                    && permitted_regulation_lineages
                        .binary_search(&transfer.sender)
                        .is_ok()
        })
        .collect::<Vec<_>>();
    preparation_transfers.sort_unstable();
    preparation_transfers.dedup();
    preparation_transfers
}

/// Resolve the exact layer-8 reflex regulation for this motor terminal.
/// Reacted joint load prepares only its opposing motor. The current virtual
/// body's singular, unhanded palmar surface prepares both closing grip
/// terminals symmetrically only when that receptor carries an exact contact
/// onset. Continued occupancy remains touch but is not a new grasp command.
/// The gustatory intake surface prepares only the single closing glottal
/// terminal, and only when a gustatory receptor carries an exact material
/// onset — the born airway-protection reflex; continued tasting remains
/// taste and is not a new swallow. Tonic antagonist-length receptors and
/// every other receptor site remain excluded: unchanged pose, unrelated
/// touch, or lingering material cannot become motor drive.
fn exact_articulated_body_preparation_regulations(
    motor_terminal: BodyEffectorTerminal,
    paths: &[MotorBodyAfferentPath],
    palmar_contact_onset_receptor_lineages: &[[u8; 16]],
    gustatory_contact_onset_receptor_lineages: &[[u8; 16]],
) -> Vec<[u8; 16]> {
    let mut regulations = paths
        .iter()
        .filter_map(|path| {
            let receptor_site = &path.receptor_site;
            if is_palmar_contact_receptor_site(receptor_site)
                && is_closing_grip_terminal(motor_terminal)
                && palmar_contact_onset_receptor_lineages
                    .binary_search(&path.receptor_lineage)
                    .is_ok()
            {
                return Some(path.body_regulation_lineage);
            }
            if is_gustatory_contact_receptor_site(receptor_site)
                && is_closing_glottal_terminal(motor_terminal)
                && gustatory_contact_onset_receptor_lineages
                    .binary_search(&path.receptor_lineage)
                    .is_ok()
            {
                return Some(path.body_regulation_lineage);
            }
            let load_terminal = receptor_site.body_proprioceptor_terminal()?;
            (receptor_site.physical_quantity() == EFFECTOR_REACTIVE_LOAD_FRACTION_QUANTITY
                && load_terminal.opposing_effector() == motor_terminal)
                .then_some(path.body_regulation_lineage)
        })
        .collect::<Vec<_>>();
    regulations.sort_unstable();
    regulations.dedup();
    regulations
}

/// Return only whole-carrier transfers that physically arrive at one mounted
/// root-yaw motor. A learned layer-11 route is retained causal anatomy and its
/// exact arriving whole-carrier transfer prepares the terminal without an
/// external same-interval label. Paired layer-8 regulation remains tied to a
/// current causal body seed.
/// Current leaving the motor is a consequence and can
/// never be relabelled as preparation, regardless of the causal-frontier
/// direction that originally taught the contact.
fn exact_root_yaw_motor_preparation_transfers(
    motor_lineage: [u8; 16],
    settled_directed_transfers: &[DirectedPhysicalTransferObservation],
    permitted_regulations: &[[u8; 16]],
    causal_seed_lineages: &BTreeSet<[u8; 16]>,
    layer_of: impl Fn([u8; 16]) -> Option<u32>,
) -> Vec<DirectedPhysicalTransferObservation> {
    let mut preparation_transfers = settled_directed_transfers
        .iter()
        .copied()
        .filter(|transfer| {
            if transfer.receiver != motor_lineage {
                return false;
            }
            layer_of(transfer.sender) == Some(11)
                || causal_seed_lineages.contains(&transfer.sender)
                    && permitted_regulations
                        .binary_search(&transfer.sender)
                        .is_ok()
        })
        .collect::<Vec<_>>();
    preparation_transfers.sort_unstable();
    preparation_transfers.dedup();
    preparation_transfers
}

/// A root-translation consequence is body-position evidence, never another
/// command to translate. Only an already-authored layer-11 ordering route that
/// is a current causal seed may prepare the terminal. In particular, current arriving from the paired
/// layer-8 proprioceptive regulation is excluded even though that contact is
/// retained as the exact anatomical afferent path.
fn exact_root_translation_motor_preparation_transfers(
    motor_lineage: [u8; 16],
    settled_directed_transfers: &[DirectedPhysicalTransferObservation],
    layer_of: impl Fn([u8; 16]) -> Option<u32>,
) -> Vec<DirectedPhysicalTransferObservation> {
    let mut preparation_transfers = settled_directed_transfers
        .iter()
        .copied()
        .filter(|transfer| {
            transfer.receiver == motor_lineage && layer_of(transfer.sender) == Some(11)
        })
        .collect::<Vec<_>>();
    preparation_transfers.sort_unstable();
    preparation_transfers.dedup();
    preparation_transfers
}

/// Describe an already-settled contact transfer in the contact's physical
/// endpoint order.
///
/// `outward_elementary_charges_from_left` is defined by the electrical
/// anatomy's stored left/right endpoints. A stable bond canonicalizes those
/// lineages for identity, so its endpoint order must never be used to infer
/// current direction.
fn directed_physical_transfer(
    outward_elementary_charges_from_left: i128,
    physical_left: [u8; 16],
    physical_right: [u8; 16],
    bond: StablePhysicalBondReference,
) -> Option<DirectedPhysicalTransferObservation> {
    if outward_elementary_charges_from_left == 0 {
        return None;
    }
    let (sender, receiver) = if outward_elementary_charges_from_left > 0 {
        (physical_left, physical_right)
    } else {
        (physical_right, physical_left)
    };
    Some(DirectedPhysicalTransferObservation {
        sender,
        receiver,
        bond,
        transferred_whole_carriers: outward_elementary_charges_from_left.unsigned_abs(),
    })
}

/// A prepared effector emits only through the neuron's own positive local
/// membrane discharge. Inter-neuron contact transport remains causal
/// preparation evidence and is never relabelled as actuator output.
fn exact_prepared_efferent_carriers(
    local_outward_elementary_charges: i128,
    preparation_count: usize,
) -> Option<u128> {
    (local_outward_elementary_charges > 0 && preparation_count != 0)
        .then_some(local_outward_elementary_charges.unsigned_abs())
}

