#[derive(Clone)]
struct PendingLayerTenPlasticitySettlement {
    neuron_lineage: [u8; 16],
    cognitive_ordinal: u64,
    incident_catalyst_quanta: u128,
    reaction_extent: u128,
    delivered_energy_zeptojoules: ExactRational,
    predecessor_gate_work_residue_zeptojoules: BigRational,
    successor_gate_work_residue_zeptojoules: BigRational,
    predecessor_plastic_rest_length_nanometres: ExactRational,
    predecessor_reservoir: (ExactRational, ExactRational, ExactRational),
    successor_reservoir: (ExactRational, ExactRational, ExactRational),
}

fn stable_bond_for_next_edge(
    parallel_ordinals: &mut std::collections::BTreeMap<([u8; 16], [u8; 16]), u32>,
    first: [u8; 16],
    second: [u8; 16],
) -> Result<StablePhysicalBondReference, FormationError> {
    let canonical = if first < second {
        (first, second)
    } else {
        (second, first)
    };
    let parallel_ordinal = parallel_ordinals.get(&canonical).copied().unwrap_or(0);
    let bond = StablePhysicalBondReference::new(first, second, parallel_ordinal)
        .ok_or(FormationError::NoncanonicalState)?;
    let successor_ordinal = parallel_ordinal
        .checked_add(1)
        .ok_or(FormationError::ArithmeticOverflow)?;
    parallel_ordinals.insert(canonical, successor_ordinal);
    Ok(bond)
}

fn exact_motor_body_afferent_paths(
    motor_flat: usize,
    flat_locations: &[(usize, usize, [u8; 16])],
    cohorts: &[ResidentReachedCohort],
    neighbours_by_flat: &[Box<[usize]>],
) -> Result<Vec<MotorBodyAfferentPath>, FormationError> {
    let mount_at = |flat: usize| {
        let (cohort_index, neuron_index, _) = flat_locations
            .get(flat)
            .copied()
            .ok_or(FormationError::NeuronLineageAuthorityAbsent)?;
        cohorts
            .get(cohort_index)
            .and_then(|cohort| cohort.anatomy.mounts().get(neuron_index))
            .ok_or(FormationError::NeuronLineageAuthorityAbsent)
    };
    if mount_at(motor_flat)?.place().layer() != 12 {
        return Err(FormationError::NeuronLineageAuthorityChanged);
    }
    let mut paths = Vec::new();
    for regulation_flat in neighbours_by_flat
        .get(motor_flat)
        .ok_or(FormationError::NeuronLineageAuthorityAbsent)?
    {
        if mount_at(*regulation_flat)?.place().layer() != 8 {
            continue;
        }
        for integration_flat in neighbours_by_flat
            .get(*regulation_flat)
            .ok_or(FormationError::NeuronLineageAuthorityAbsent)?
        {
            if mount_at(*integration_flat)?.place().layer() != 6 {
                continue;
            }
            for receptor_flat in neighbours_by_flat
                .get(*integration_flat)
                .ok_or(FormationError::NeuronLineageAuthorityAbsent)?
            {
                let receptor_mount = mount_at(*receptor_flat)?;
                let Some(receptor_site) = receptor_mount.source_site() else {
                    continue;
                };
                if receptor_mount.place().layer() != 5
                    && !is_palmar_contact_receptor_site(receptor_site)
                    && !is_gustatory_contact_receptor_site(receptor_site)
                {
                    continue;
                }
                paths.push(MotorBodyAfferentPath {
                    body_regulation_lineage: flat_locations[*regulation_flat].2,
                    integration_lineage: flat_locations[*integration_flat].2,
                    receptor_lineage: flat_locations[*receptor_flat].2,
                    receptor_site: receptor_site.clone(),
                });
            }
        }
    }
    paths.sort_by(|left, right| {
        (
            left.body_regulation_lineage,
            left.integration_lineage,
            left.receptor_lineage,
            left.receptor_site.sensor_id(),
            left.receptor_site.substream_id(),
        )
            .cmp(&(
                right.body_regulation_lineage,
                right.integration_lineage,
                right.receptor_lineage,
                right.receptor_site.sensor_id(),
                right.receptor_site.substream_id(),
            ))
    });
    paths.dedup();
    Ok(paths)
}

/// Resolve only the layer-8 regulation line whose typed directional root-yaw
/// receptor is physically paired with this root motor.  The motor contact is
/// not enough by itself: a different layer-8 neighbour, including the opposite
/// antagonist, cannot prepare this terminal.
fn exact_root_yaw_preparation_regulations(
    motor_terminal: RootYawEffectorTerminal,
    paths: &[MotorBodyAfferentPath],
) -> Vec<[u8; 16]> {
    let mut regulations = paths
        .iter()
        .filter_map(|path| {
            (path
                .receptor_site
                .root_yaw_proprioceptor_terminal()
                .map(RootYawProprioceptorTerminal::paired_effector)
                == Some(motor_terminal))
            .then_some(path.body_regulation_lineage)
        })
        .collect::<Vec<_>>();
    regulations.sort_unstable();
    regulations.dedup();
    regulations
}

/// Borrow only the sorted, distinct reached cohorts without scanning or
/// aliasing the complete resident slice. The returned order is the exact input
/// order, which is canonical organism cohort order at every caller.
fn selected_cohorts_mut<'a>(
    cohorts: &'a mut [ResidentReachedCohort],
    selected_indices: &[usize],
) -> Result<Vec<(usize, &'a mut ResidentReachedCohort)>, FormationError> {
    let mut selected = Vec::with_capacity(selected_indices.len());
    let mut remainder = cohorts;
    let mut remainder_start = 0_usize;
    for cohort_index in selected_indices.iter().copied() {
        let relative = cohort_index
            .checked_sub(remainder_start)
            .ok_or(FormationError::NoncanonicalState)?;
        if relative >= remainder.len() {
            return Err(FormationError::NoncanonicalState);
        }
        let (_, at_selected) = remainder.split_at_mut(relative);
        let (cohort, after_selected) = at_selected
            .split_first_mut()
            .ok_or(FormationError::NoncanonicalState)?;
        selected.push((cohort_index, cohort));
        remainder = after_selected;
        remainder_start = cohort_index
            .checked_add(1)
            .ok_or(FormationError::ArithmeticOverflow)?;
    }
    Ok(selected)
}

#[cfg(test)]
#[allow(clippy::too_many_arguments)]
fn settle_internal_contact_interval(
    cohorts: &mut [ResidentReachedCohort],
    electrical_fabric: &mut ResidentElectricalFabric,
    topology_index: &ResidentTopologyIndex,
    vocal_articulatory_effector_lineage: Option<[u8; 16]>,
    predecessor_frontier: &[ActiveElectricalFrontierEntry],
    _preceding_frontier: &[ActiveElectricalFrontierEntry],
    locally_settled_lineages: &[[u8; 16]],
    causal_seed_lineages: &[[u8; 16]],
    fresh_seed_lineages: &[[u8; 16]],
    external_ingress_seed_lineages: &[[u8; 16]],
    physically_transitioned_neuron_lineages: &mut BTreeSet<[u8; 16]>,
    cognitive_ordinal: u64,
    unchanged_developmental_resting_neuron_count: usize,
    residency: &mut Option<crate::causal_event_scheduler::CausalEventResidency>,
    pre_source_membranes: &BTreeMap<
        [u8; 16],
        (
            crate::elementary_charge_membrane::ElementaryChargeMembraneState,
            u128,
            u128,
        ),
    >,
    palmar_contact_onset_receptor_lineages: &[[u8; 16]],
    gustatory_contact_onset_receptor_lineages: &[[u8; 16]],
    real_nutrition_intake_zeptojoules: ExactRational,
    admit_learned_motor_work: bool,
) -> Result<InternalContactSettlementObservation, FormationError> {
    settle_internal_contact_interval_with_body_act(
        cohorts,
        electrical_fabric,
        topology_index,
        vocal_articulatory_effector_lineage,
        predecessor_frontier,
        &[],
        locally_settled_lineages,
        causal_seed_lineages,
        fresh_seed_lineages,
        external_ingress_seed_lineages,
        physically_transitioned_neuron_lineages,
        cognitive_ordinal,
        unchanged_developmental_resting_neuron_count,
        residency,
        pre_source_membranes,
        palmar_contact_onset_receptor_lineages,
        gustatory_contact_onset_receptor_lineages,
        real_nutrition_intake_zeptojoules,
        admit_learned_motor_work,
    )
}

/// Settle the bounded contact-connected frontier reached by this external
/// occurrence, form one native membrane-potential occurrence from its exact
/// predecessor/successor states, evaluate unchanged full DSF once, and let
/// every reached complete neuron settle that shared field.  Local and
/// cross-cohort contact carrier motion is computed once in one synchronous
/// generation; cohort recovery fluids remain wholly separate.
#[allow(clippy::too_many_arguments)]
fn settle_internal_contact_interval_with_body_act(
    cohorts: &mut [ResidentReachedCohort],
    electrical_fabric: &mut ResidentElectricalFabric,
    topology_index: &ResidentTopologyIndex,
    vocal_articulatory_effector_lineage: Option<[u8; 16]>,
    predecessor_frontier: &[ActiveElectricalFrontierEntry],
    moved_body_effectors: &[BodyEffectorTerminal],
    locally_settled_lineages: &[[u8; 16]],
    causal_seed_lineages: &[[u8; 16]],
    fresh_seed_lineages: &[[u8; 16]],
    external_ingress_seed_lineages: &[[u8; 16]],
    physically_transitioned_neuron_lineages: &mut BTreeSet<[u8; 16]>,
    cognitive_ordinal: u64,
    unchanged_developmental_resting_neuron_count: usize,
    residency: &mut Option<crate::causal_event_scheduler::CausalEventResidency>,
    pre_source_membranes: &BTreeMap<
        [u8; 16],
        (
            crate::elementary_charge_membrane::ElementaryChargeMembraneState,
            u128,
            u128,
        ),
    >,
    palmar_contact_onset_receptor_lineages: &[[u8; 16]],
    gustatory_contact_onset_receptor_lineages: &[[u8; 16]],
    real_nutrition_intake_zeptojoules: ExactRational,
    admit_learned_motor_work: bool,
) -> Result<InternalContactSettlementObservation, FormationError> {
    let residency_holds_due_events = residency.as_ref().is_some_and(|events| {
        events.matches_shape(
            topology_index.flat_locations.len(),
            topology_index.contacts.len(),
        ) && (events
            .contact_schedule
            .scheduled_dues()
            .any(|(_, due)| due <= events.organism_clock + 1)
            || events
                .recovery_schedule
                .scheduled_dues()
                .any(|(_, due)| due <= events.organism_clock + 1))
    });
    if (locally_settled_lineages.is_empty() && !residency_holds_due_events)
        || electrical_fabric.contact_count() == 0
    {
        return Ok(InternalContactSettlementObservation {
            dsf_delivery_count: 0,
            active_bonds: Vec::new(),
            causal_active_bonds: Vec::new(),
            causally_transitioned_lineages: Vec::new(),
            changed_contact_channel_states: Vec::new(),
            frontier_routes: Vec::new(),
            next_active_frontier: Vec::new(),
            settled_directed_transfers: Vec::new(),
            metabolically_perturbed_body_receptor_lineages: Vec::new(),
            affective_balance_trajectories: Vec::new(),
            localized_fluid_chemistry: Vec::new(),
            deferred_vocal_work_offers: Vec::new(),
            learned_motor_work_preparations: Vec::new(),
            motor_unit_recruitments: Vec::new(),
            completed_vocal_orderings: Vec::new(),
            root_yaw_unit_recruitments: Vec::new(),
            root_translation_unit_recruitments: Vec::new(),
            articulatory_unit_recruitments: Vec::new(),
            emitted_neuron_fractals: Vec::new(),
            passive_membrane_returned_neuron_lineages: Vec::new(),
            transition_predecessors: BTreeMap::new(),
        });
    }

    if !topology_index.matches_shape(cohorts, electrical_fabric) {
        return Err(FormationError::NeuronLineageAuthorityChanged);
    }
    let flat_locations = topology_index.flat_locations.as_ref();
    let lineage_member = |lineage| topology_index.flat_for_lineage(lineage);
    let layer_of = |lineage| topology_index.layer_of(lineage);
    let vocal_articulatory_effector_flat = vocal_articulatory_effector_lineage
        .map(lineage_member)
        .transpose()?;
    if let Some(flat) = vocal_articulatory_effector_flat {
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        let mount = &cohorts[cohort_index].anatomy.mounts()[neuron_index];
        if mount.source_site().is_some() || mount.place().layer() != 13 {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        }
    }
    // One physical interval reaches only its explicitly carried causal
    // frontier and immediate electrical neighbours. Absolute nonzero
    // membrane charge is not activity: the phase-one pump gives a living
    // neuron a nonzero resting potential. Likewise a retained sub-carrier
    // contact phase is material, not proof that current moved in this
    // interval. The predecessor state carries the exact lineages whose
    // membrane/contact physics actually changed last interval, and the
    // caller combines those with this interval's external or metabolic cause.
    // This replaces the false rule that eventually made every reached neuron
    // and contact a permanent seed.
    // Causal event selection. Work is proportional to events: this clock
    // settles exactly (a) contacts whose scheduled whole-carrier crossing
    // is due, (b) contacts incident to a causally reached neuron (external
    // or metabolic seed, prior-clock arrival, or a due membrane-recovery
    // event), and nothing else. The former neighbour-closure sweep over
    // the whole fabric is deleted; the derived residency is rebuilt in one
    // walk at cold restore or after growth, never per clock.
    // The event clock counts SETTLED intervals, never generations: a
    // generation that performs no settlement advances no physics, so it
    // advances no clock and no due can ever lapse unseen.
    let needs_rebuild = residency.as_ref().is_none_or(|events| {
        !events.matches_shape(flat_locations.len(), topology_index.contacts.len())
    });
    if needs_rebuild {
        let base_clock = residency
            .as_ref()
            .map_or(cognitive_ordinal.saturating_sub(1), |events| {
                events.organism_clock
            });
        *residency = Some(rebuild_causal_event_residency_from_endpoint_holds(
            cohorts,
            electrical_fabric,
            topology_index,
            base_clock,
            Some(pre_source_membranes),
        )?);
    }
    let events = residency
        .as_mut()
        .ok_or(FormationError::NoncanonicalState)?;
    // Discrete event time: with no external ingress this clock, nothing
    // can change before the earliest scheduled event, so the clock skips
    // the silent span exactly — zero settlements spent on silence.
    if locally_settled_lineages.is_empty() {
        let earliest_due = events
            .contact_schedule
            .scheduled_dues()
            .map(|(_, due)| due)
            .chain(
                events
                    .recovery_schedule
                    .scheduled_dues()
                    .map(|(_, due)| due),
            )
            .min();
        if let Some(earliest) = earliest_due {
            if earliest > events.organism_clock + 1 {
                events.organism_clock = earliest
                    .checked_sub(1)
                    .ok_or(FormationError::ArithmeticOverflow)?;
            }
        }
    }
    events.organism_clock = events
        .organism_clock
        .checked_add(1)
        .ok_or(FormationError::ArithmeticOverflow)?;
    let clock = events.organism_clock;
    let mut seed_flats = locally_settled_lineages
        .iter()
        .copied()
        .map(lineage_member)
        .collect::<Result<Vec<_>, _>>()?;
    seed_flats.sort_unstable();
    seed_flats.dedup();
    // PASSIVE MEMBRANE RETURN events settle here directly: one whole
    // elementary charge toward zero per due neuron, carriers conserved on
    // the neuron's own compartments, released work deposited into its
    // cohort's reservoir thermal state. A return NEVER seeds the causal
    // frontier and NEVER runs the active pump — the pump cannot
    // masquerade as rest. The changed neuron's incident contacts are
    // reconsidered by the universal wake law at this interval's end.
    let mut due_return_flats = Vec::new();
    events
        .recovery_schedule
        .drain_due_at(clock, &mut due_return_flats);
    let mut due_terminal_flats = Vec::new();
    let mut passive_return_changed_flats = Vec::new();
    let mut passive_membrane_returned_neuron_lineages = Vec::new();
    let mut transition_predecessors = BTreeMap::new();
    for flat in due_return_flats.iter().copied() {
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        let mount = &cohorts[cohort_index].anatomy.mounts()[neuron_index];
        let neuron = &cohorts[cohort_index].state.neurons()[neuron_index];
        let lineage = flat_locations[flat].2;
        let coordinated_vocal_preparation = mount.place().layer() == 11
            && vocal_action_preparation_for_ordering(cohorts, topology_index, lineage)?.is_some();
        if terminal_retains_prepared_action_charge(mount, neuron, coordinated_vocal_preparation) {
            events.recovery_last_integrated[flat] = clock;
            due_terminal_flats.push(flat);
            continue;
        }
        let elapsed = clock
            .checked_sub(events.recovery_last_integrated[flat])
            .ok_or(FormationError::ArithmeticOverflow)?;
        if elapsed == 0 {
            continue;
        }
        let interval_u32 = u32::try_from(WORLD_MECHANICAL_TICK_MICROSECONDS)
            .map_err(|_| FormationError::ArithmeticOverflow)?;
        let settled_return = crate::complete_neuron::settle_passive_membrane_return(
            &cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index],
            &cohorts[cohort_index].state.neurons()[neuron_index],
            events.recovery_phase[flat],
            interval_u32,
            elapsed,
        )
        .map_err(|error| {
            FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                neuron_index,
                error,
            })
        })?;
        events.recovery_last_integrated[flat] = clock;
        let Some((successor_neuron, successor_phase, released)) = settled_return else {
            events.recovery_phase[flat] =
                crate::elementary_charge_transfer::ChargeCarrierPhase::zero();
            continue;
        };
        events.recovery_phase[flat] = successor_phase;
        if successor_neuron == cohorts[cohort_index].state.neurons()[neuron_index] {
            continue;
        }
        let released_exact = crate::exact_rational::ExactRational::new(
            i128::try_from(released.numer().clone())
                .map_err(|_| FormationError::ArithmeticOverflow)?,
            u128::try_from(released.denom().clone())
                .map_err(|_| FormationError::ArithmeticOverflow)?,
        )
        .map_err(|_| FormationError::ArithmeticOverflow)?;
        let reservoir_anatomy = cohorts[cohort_index]
            .anatomy
            .recovery_fluid_reservoir_anatomy();
        let Some(successor_reservoir) = crate::metabolic_feeding::deposit_passive_return_work(
            reservoir_anatomy,
            cohorts[cohort_index].state.recovery_fluid(),
            released_exact,
        )
        .map_err(|_| FormationError::ArithmeticOverflow)?
        else {
            // The thermal capacity refuses the deposit: the return does
            // not settle, and this neuron reschedules from its held state.
            continue;
        };
        let lineage = flat_locations[flat].2;
        let predecessor = TransitionNeuronPredecessor {
            lineage,
            anatomy: cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index].clone(),
            state: cohorts[cohort_index].state.neurons()[neuron_index].clone(),
        };
        Arc::make_mut(&mut cohorts[cohort_index].state)
            .apply_local_membrane_transport(neuron_index, successor_neuron, successor_reservoir)
            .map_err(FormationError::PhysicalSettlementUnavailable)?;
        physically_transitioned_neuron_lineages.insert(lineage);
        retain_first_transition_predecessor(&mut transition_predecessors, predecessor);
        passive_return_changed_flats.push(flat);
        passive_membrane_returned_neuron_lineages.push(lineage);
    }
    passive_return_changed_flats.sort_unstable();
    passive_return_changed_flats.dedup();
    passive_membrane_returned_neuron_lineages.sort_unstable();
    passive_membrane_returned_neuron_lineages.dedup();
    let mut compact_contact_indices = Vec::new();
    events
        .contact_schedule
        .drain_due_at(clock, &mut compact_contact_indices);
    for flat in seed_flats.iter().copied() {
        compact_contact_indices.extend(
            topology_index
                .incident_contacts_by_flat
                .get(flat)
                .ok_or(FormationError::NeuronLineageAuthorityAbsent)?
                .iter()
                .copied(),
        );
    }
    compact_contact_indices.sort_unstable();
    compact_contact_indices.dedup();
    // Candidate 47G's learned motor junction is one parallel electrical load:
    // an active L7/L11 source contact and that ordering cell's exact learned
    // L11/L12 motor branches must therefore be present in the same sparse
    // settlement. Reached-frontier selection ordinarily admits only the
    // seed's incident contact (one hop), which silently split this circuit at
    // the L11 boundary. Extend only from a currently seeded L7 across its
    // exact coordinated L11; scheduled maintenance contacts and unseeded L11s
    // gain no action authority from this circuit completion.
    let mut learned_parallel_branch_indices = Vec::new();
    for source_contact_index in compact_contact_indices.iter().copied() {
        let source_contact = topology_index.contacts[source_contact_index];
        let (association_flat, ordering_flat) = match (
            layer_of(flat_locations[source_contact.left].2),
            layer_of(flat_locations[source_contact.right].2),
        ) {
            (Some(7), Some(11)) => (source_contact.left, source_contact.right),
            (Some(11), Some(7)) => (source_contact.right, source_contact.left),
            _ => continue,
        };
        let ordering_lineage = flat_locations[ordering_flat].2;
        if !causal_seed_lineages.contains(&flat_locations[association_flat].2)
            || causal_seed_lineages.contains(&ordering_lineage)
        {
            continue;
        }
        let Some(preparation) =
            vocal_action_preparation_for_ordering(cohorts, topology_index, ordering_lineage)?
        else {
            continue;
        };
        for branch_contact_index in topology_index
            .incident_contacts_by_flat
            .get(ordering_flat)
            .ok_or(FormationError::NeuronLineageAuthorityAbsent)?
            .iter()
            .copied()
        {
            let branch = topology_index.contacts[branch_contact_index];
            let motor_flat = if branch.left == ordering_flat {
                branch.right
            } else if branch.right == ordering_flat {
                branch.left
            } else {
                return Err(FormationError::NoncanonicalState);
            };
            let motor_lineage = flat_locations[motor_flat].2;
            if preparation
                .motors
                .iter()
                .any(|motor| motor.lineage == motor_lineage && motor.bond == branch.stable_bond)
            {
                learned_parallel_branch_indices.push(branch_contact_index);
            }
        }
    }
    compact_contact_indices.extend(learned_parallel_branch_indices);
    compact_contact_indices.sort_unstable();
    compact_contact_indices.dedup();
    let mut selected = seed_flats.clone();
    for contact_index in compact_contact_indices.iter().copied() {
        let entry = topology_index.contacts[contact_index];
        selected.push(entry.left);
        selected.push(entry.right);
    }
    selected.extend(due_terminal_flats.iter().copied());
    selected.sort_unstable();
    selected.dedup();
    let mut permitted_vocal_ordering_work = BTreeSet::new();
    let mut permitted_vocal_motor_bonds = BTreeSet::new();
    let mut externally_permitted_vocal_motor_bonds = BTreeSet::new();
    for entry in predecessor_frontier.iter().copied() {
        if let Some(ordering) =
            frontier_founds_vocal_action_preparation(cohorts, topology_index, entry)?
        {
            permitted_vocal_ordering_work.insert(ordering);
            let preparation =
                vocal_action_preparation_for_ordering(cohorts, topology_index, ordering)?
                    .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
            for motor in preparation.motors {
                permitted_vocal_motor_bonds.insert(motor.bond);
                externally_permitted_vocal_motor_bonds.insert(motor.bond);
            }
        }
        if entry.is_in_flight()
            && entry.carries_external_ingress_cause()
            && !entry.carries_body_owned_acoustic_efference()
        {
            let cause = entry.cause.ok_or(FormationError::NoncanonicalState)?;
            let ordering = entry.sender().ok_or(FormationError::NoncanonicalState)?;
            let motor = entry.receiver();
            if vocal_action_preparation_from_motor_branch(
                cohorts,
                topology_index,
                ordering,
                motor,
                cause.bond,
            )?
            .is_some()
            {
                permitted_vocal_ordering_work.insert(ordering);
                permitted_vocal_motor_bonds.insert(cause.bond);
                externally_permitted_vocal_motor_bonds.insert(cause.bond);
            }
        }
        let Some(transfer) = entry.directed_transfer() else {
            continue;
        };
        for continuation in vocal_cognitive_action_continuation_routes_from_source(
            cohorts,
            topology_index,
            transfer.sender,
        )? {
            if transfer.receiver == continuation.destination_ordering_lineage
                && transfer.bond == continuation.continuation_bond
            {
                let ordering = continuation.destination_ordering_lineage;
                permitted_vocal_ordering_work.insert(ordering);
                let preparation =
                    vocal_action_preparation_for_ordering(cohorts, topology_index, ordering)?
                        .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
                permitted_vocal_motor_bonds
                    .extend(preparation.motors.into_iter().map(|motor| motor.bond));
            }
        }
    }
    // A completed vocal act may transfer its already-released contact work
    // through one learned L11/L11 predecessor bond. The work is retained in
    // the younger ordering neuron's existing receptor-energy lattice; it is
    // neither membrane charge nor a permission bit. While that exact residue
    // or the gate it physically opened remains active, the younger ordering's
    // real motor contacts are the only eligible continuation branches.
    for entry in predecessor_frontier.iter().copied() {
        let Some(cause) = entry.cause else {
            continue;
        };
        let Some(sender) = entry.sender() else {
            return Err(FormationError::NoncanonicalState);
        };
        let receiver = entry.receiver();
        let mut candidate = None;
        let mut continuation_motor_bond = None;
        if cause.transferred_whole_carriers == 0
            && entry.frontier_lineage() == receiver
            && layer_of(sender) == Some(11)
            && layer_of(receiver) == Some(11)
        {
            let matching = vocal_cognitive_action_continuation_routes_from_source(
                cohorts,
                topology_index,
                sender,
            )?
            .into_iter()
            .filter(|route| {
                route.destination_ordering_lineage == receiver
                    && route.continuation_bond == cause.bond
            })
            .count();
            match matching {
                0 => {}
                1 => candidate = Some(receiver),
                _ => return Err(FormationError::NeuronLineageAuthorityChanged),
            }
        } else if entry.is_in_flight()
            && layer_of(sender) == Some(11)
            && layer_of(receiver) == Some(12)
        {
            if vocal_action_preparation_from_motor_branch(
                cohorts,
                topology_index,
                sender,
                receiver,
                cause.bond,
            )?
            .is_some()
            {
                candidate = Some(sender);
                continuation_motor_bond = Some(cause.bond);
            }
        }
        let Some(ordering) = candidate else {
            continue;
        };
        let preparation = vocal_action_preparation_for_ordering(cohorts, topology_index, ordering)?
            .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
        let flat = lineage_member(ordering)?;
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        let neuron = &cohorts[cohort_index].state.neurons()[neuron_index];
        if neuron.receptor_quantum_residue.energy().is_zero() && neuron.gate.open_population() == 0
        {
            continue;
        }
        let predecessors = preparation_predecessors(cohorts, topology_index, &preparation)?;
        match predecessors.as_slice() {
            [] => continue,
            [_] => {}
            _ => return Err(FormationError::NeuronLineageAuthorityChanged),
        }
        permitted_vocal_ordering_work.insert(ordering);
        if let Some(bond) = continuation_motor_bond {
            permitted_vocal_motor_bonds.insert(bond);
        } else {
            permitted_vocal_motor_bonds
                .extend(preparation.motors.into_iter().map(|motor| motor.bond));
        }
    }
    if permitted_vocal_ordering_work.len() > 1 {
        return Err(FormationError::NeuronLineageAuthorityChanged);
    }
    let mut causal_seed_flats = causal_seed_lineages
        .iter()
        .copied()
        .map(lineage_member)
        .collect::<Result<Vec<_>, _>>()?;
    causal_seed_flats.sort_unstable();
    causal_seed_flats.dedup();
    let is_causal_seed = |flat: usize| causal_seed_flats.binary_search(&flat).is_ok();
    let mut fresh_seed_flats = fresh_seed_lineages
        .iter()
        .copied()
        .map(lineage_member)
        .collect::<Result<Vec<_>, _>>()?;
    fresh_seed_flats.sort_unstable();
    fresh_seed_flats.dedup();
    let mut external_ingress_seed_flats = external_ingress_seed_lineages
        .iter()
        .copied()
        .map(lineage_member)
        .chain(
            predecessor_frontier
                .iter()
                .copied()
                .filter(|entry| entry.carries_external_ingress_cause())
                .map(ActiveElectricalFrontierEntry::frontier_lineage)
                .map(lineage_member),
        )
        .collect::<Result<Vec<_>, _>>()?;
    external_ingress_seed_flats.sort_unstable();
    external_ingress_seed_flats.dedup();
    let is_external_ingress_seed =
        |flat: usize| external_ingress_seed_flats.binary_search(&flat).is_ok();
    let mut body_owned_acoustic_efference_seed_flats = predecessor_frontier
        .iter()
        .copied()
        .filter(|entry| entry.carries_body_owned_acoustic_efference())
        .map(ActiveElectricalFrontierEntry::frontier_lineage)
        .map(lineage_member)
        .collect::<Result<Vec<_>, _>>()?;
    body_owned_acoustic_efference_seed_flats.sort_unstable();
    body_owned_acoustic_efference_seed_flats.dedup();
    let is_body_owned_acoustic_efference_seed = |flat: usize| {
        body_owned_acoustic_efference_seed_flats
            .binary_search(&flat)
            .is_ok()
    };
    let incoming_frontier_bonds = incoming_frontier_bonds(predecessor_frontier);
    let crosses_new_frontier_bond = |seed_flat: usize, bond| {
        frontier_crossing_advances(
            &incoming_frontier_bonds,
            flat_locations[seed_flat].2,
            bond,
            fresh_seed_flats.binary_search(&seed_flat).is_ok(),
        )
    };

    if selected.is_empty() {
        return Ok(InternalContactSettlementObservation {
            dsf_delivery_count: 0,
            active_bonds: Vec::new(),
            causal_active_bonds: Vec::new(),
            causally_transitioned_lineages: Vec::new(),
            changed_contact_channel_states: Vec::new(),
            frontier_routes: Vec::new(),
            next_active_frontier: Vec::new(),
            settled_directed_transfers: Vec::new(),
            metabolically_perturbed_body_receptor_lineages: Vec::new(),
            affective_balance_trajectories: Vec::new(),
            localized_fluid_chemistry: Vec::new(),
            deferred_vocal_work_offers: Vec::new(),
            learned_motor_work_preparations: Vec::new(),
            motor_unit_recruitments: Vec::new(),
            completed_vocal_orderings: Vec::new(),
            root_yaw_unit_recruitments: Vec::new(),
            root_translation_unit_recruitments: Vec::new(),
            articulatory_unit_recruitments: Vec::new(),
            emitted_neuron_fractals: Vec::new(),
            passive_membrane_returned_neuron_lineages: Vec::new(),
            transition_predecessors: BTreeMap::new(),
        });
    }
    let mut selected_cohort_indices = selected
        .iter()
        .map(|flat| flat_locations[*flat].0)
        .collect::<Vec<_>>();
    selected_cohort_indices.sort_unstable();
    selected_cohort_indices.dedup();

    // Membrane pumping is local cell metabolism, not a darkness detector. Run
    // the existing exact pump only for this interval's already-derived causal
    // frontier before contact current is evaluated. This lets an intrinsic
    // neuron replenish its finite carrier gradient without polling or
    // recovering any unrelated neuron or dissipation lane.
    // The causal frontier is sparse. Keep predecessor custody only for the
    // cohorts that this interval actually reaches. The former population-
    // width containers reserved one slot or empty vector per resident cohort;
    // selected predecessor state itself was already cloned only when reached.
    let mut selected_predecessor_neurons =
        BTreeMap::<usize, Vec<(usize, NeuronPhysicalState)>>::new();
    let mut selected_members_by_cohort = BTreeMap::<usize, Vec<(usize, usize)>>::new();
    for (coordinate, flat) in selected.iter().copied().enumerate() {
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        selected_members_by_cohort
            .entry(cohort_index)
            .or_default()
            .push((coordinate, neuron_index));
        selected_predecessor_neurons
            .entry(cohort_index)
            .or_default()
            .push((
                neuron_index,
                cohorts[cohort_index].state.neurons()[neuron_index].clone(),
            ));
    }
    // The active pump serves the CAUSAL FRONTIER — this clock's seeds —
    // never every endpoint the settlement sweeps in. Pumping the whole
    // selection kept every sleeping neuron awake through its neighbours;
    // an unseeded endpoint's metabolism waits for its own reach, and its
    // excess charge drains through the passive return instead.
    let mut pump_members_by_cohort = BTreeMap::<usize, Vec<usize>>::new();
    for flat in seed_flats.iter().copied() {
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        pump_members_by_cohort
            .entry(cohort_index)
            .or_default()
            .push(neuron_index);
    }
    for members in pump_members_by_cohort.values_mut() {
        members.sort_unstable();
        members.dedup();
    }
    // The layer-13 respiratory effector is electrically isolated but remains
    // living body tissue. Its local powered-environment exchange must continue
    // during every physical interval, not only when a learned motor happens to
    // request breath. The old just-before-discharge-only ordering left its
    // reservoir thermal state parked between acts and progressively reduced a
    // valid discharge to the tiny prefix that still fit. This adds one fixed
    // cell to the already-existing pump settlement; it scans no population and
    // creates no capacity, work, carrier, clock, or second chemistry law.
    if let Some(flat) = vocal_articulatory_effector_flat {
        if selected.binary_search(&flat).is_ok() {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        }
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        let members = pump_members_by_cohort.entry(cohort_index).or_default();
        members.push(neuron_index);
        members.sort_unstable();
        members.dedup();
    }
    let interval_microseconds = WORLD_MECHANICAL_TICK_MICROSECONDS;
    // THE DOORWAY'S ALLOCATION (R1 eating): the bite entered at the mouth,
    // but digestion feeds the body — the intake is allocated across the
    // cohorts genuinely settling this lived interval, in mounted order,
    // each taking no more than its own spent energy and capacity headroom
    // (the same bounds the per-cohort nutrition law re-enforces). Whatever
    // no settling cohort can absorb is waste; nothing is stored, nothing
    // is typed, and the sum of shares never exceeds the real transfer.
    let mut cohort_intake_shares = BTreeMap::<usize, ExactRational>::new();
    if {
        let (n, _) = real_nutrition_intake_zeptojoules.parts();
        n > 0
    } {
        let wide = |v: ExactRational| {
            let (n, d) = v.parts();
            num_rational::BigRational::new(n.into(), d.into())
        };
        let zero = num_rational::BigRational::from_integer(0.into());
        let mut remaining = wide(real_nutrition_intake_zeptojoules);
        for cohort_index in selected_cohort_indices.iter().copied() {
            if remaining <= zero {
                break;
            }
            let anatomy = cohorts[cohort_index]
                .anatomy
                .recovery_fluid_reservoir_anatomy();
            let (available_capacity, _, _) = anatomy.capacities();
            let (available, spent, _) = cohorts[cohort_index]
                .state
                .recovery_fluid()
                .physical_parts();
            let headroom = wide(available_capacity) - wide(available);
            let share = remaining.clone().min(wide(spent)).min(headroom);
            if share <= zero {
                continue;
            }
            let (n, d) = (share.numer(), share.denom());
            let Ok(numerator) = i128::try_from(n.clone()) else {
                continue;
            };
            let Ok(denominator) = u128::try_from(d.clone()) else {
                continue;
            };
            let Ok(exact_share) = ExactRational::new(numerator, denominator) else {
                continue;
            };
            cohort_intake_shares.insert(cohort_index, exact_share);
            remaining -= share;
        }
    }
    // Cohort reservoirs are physically independent. Prepare their exact pump
    // successors concurrently, but retain canonical cohort order for the
    // deterministic resident commit and observation stream.
    let mut pump_cohort_indices = selected_cohort_indices.clone();
    if let Some(flat) = vocal_articulatory_effector_flat {
        pump_cohort_indices.push(flat_locations[flat].0);
        pump_cohort_indices.sort_unstable();
        pump_cohort_indices.dedup();
    }
    let prepared_cohort_pumps = pump_cohort_indices
        .par_iter()
        .copied()
        .map(|cohort_index| {
            let reached_indices = pump_members_by_cohort
                .get(&cohort_index)
                .cloned()
                .unwrap_or_default();
            let prepared = prepare_reached_cohort_membrane_pumps(
                &cohorts[cohort_index].anatomy,
                cohorts[cohort_index].state.as_ref(),
                &reached_indices,
                interval_microseconds,
                cohort_intake_shares
                    .get(&cohort_index)
                    .copied()
                    .unwrap_or_else(|| ExactRational::integer(0)),
            )
            .map_err(FormationError::PhysicalSettlementUnavailable)?;
            Ok((cohort_index, reached_indices, prepared))
        })
        .collect::<Result<Vec<_>, FormationError>>()?;

    let mut metabolically_perturbed_body_receptor_lineages = Vec::new();
    let mut reached_layer_ten_gradient_settlements = Vec::new();
    let mut localized_fluid_chemistry = Vec::new();
    for (cohort_index, reached_indices, prepared) in prepared_cohort_pumps {
        let reached_predecessors = selected_predecessor_neurons
            .get(&cohort_index)
            .map(Vec::as_slice)
            .unwrap_or_default();
        let metabolic = apply_prepared_reached_cohort_membrane_pumps(
            Arc::make_mut(&mut cohorts[cohort_index].state),
            prepared,
        );
        if let Some(flat) = vocal_articulatory_effector_flat {
            let (articulatory_cohort, articulatory_neuron, articulatory_lineage) =
                flat_locations[flat];
            if articulatory_cohort == cohort_index
                && metabolic
                    .localized_fluid_chemistry
                    .iter()
                    .any(|settlement| settlement.neuron_index == articulatory_neuron)
            {
                physically_transitioned_neuron_lineages.insert(articulatory_lineage);
            }
        }
        let successor = cohorts[cohort_index].state.clone();
        if cohorts[cohort_index].anatomy.neuron_count() == 1
            && reached_indices.as_slice() == [0]
            && cohorts[cohort_index].anatomy.mounts()[0].place().layer() == 10
        {
            reached_layer_ten_gradient_settlements.push(ReachedLayerTenGradientSettlement {
                neuron_lineage: cohorts[cohort_index].anatomy.neuron_lineages()[0],
                neuron_place: cohorts[cohort_index].anatomy.mounts()[0].place(),
                predecessor_separated_elementary_charges: cohorts[cohort_index].state.neurons()[0]
                    .separated_elementary_charges(),
                post_gradient_separated_elementary_charges: successor.neurons()[0]
                    .separated_elementary_charges(),
                metabolic: metabolic.clone(),
            });
        }
        for settlement in metabolic.localized_fluid_chemistry.iter().copied() {
            let LocalizedFluidChemistrySettlement {
                neuron_index,
                interval_microseconds,
                pump_contact_power_zeptojoules_per_microsecond,
                predecessor_separated_elementary_charges,
                successor_separated_elementary_charges,
                predecessor_intracellular_carriers,
                predecessor_extracellular_carriers,
                successor_intracellular_carriers,
                successor_extracellular_carriers,
                predecessor_reservoir,
                successor_reservoir,
                returned_elementary_charges,
                pumped_elementary_charges,
                membrane_gradient_work_zeptojoules,
            } = settlement;
            localized_fluid_chemistry.push(LocalizedFluidChemistryObservation {
                cognitive_ordinal,
                neuron_lineage: cohorts[cohort_index].anatomy.neuron_lineages()[neuron_index],
                neuron_place: cohorts[cohort_index].anatomy.mounts()[neuron_index].place(),
                interval_microseconds,
                pump_contact_power_zeptojoules_per_microsecond,
                reached_neuron_count: metabolic.reached_neuron_count,
                changed_reached_neuron_count: metabolic.changed_reached_neuron_count,
                unchanged_unreached_neuron_count: metabolic.unchanged_unreached_neuron_count,
                unchanged_developmental_resting_neuron_count,
                changed_unreached_neuron_count: metabolic.changed_unreached_neuron_count,
                predecessor_separated_elementary_charges,
                successor_separated_elementary_charges,
                predecessor_intracellular_carriers,
                predecessor_extracellular_carriers,
                successor_intracellular_carriers,
                successor_extracellular_carriers,
                predecessor_reservoir,
                successor_reservoir,
                returned_elementary_charges,
                pumped_elementary_charges,
                membrane_gradient_work_zeptojoules,
            });
        }
        for (neuron_index, predecessor) in reached_predecessors {
            let mount = &cohorts[cohort_index].anatomy.mounts()[*neuron_index];
            if mount.source_site().is_some()
                && mount.place().layer() == 5
                && predecessor.separated_elementary_charges()
                    != successor.neurons()[*neuron_index].separated_elementary_charges()
            {
                let lineage = cohorts[cohort_index].anatomy.neuron_lineages()[*neuron_index];
                if !metabolically_perturbed_body_receptor_lineages.contains(&lineage) {
                    metabolically_perturbed_body_receptor_lineages.push(lineage);
                }
            }
        }
        cohorts[cohort_index].state = successor.into();
    }

    // Settlement receives only the sorted reached indices and writes only
    // those indices.  Derive the untouched active count from that sparse
    // write boundary; do not rescan the organism after every interval.
    let reached_organism_neuron_count = selected
        .len()
        .checked_add(usize::from(vocal_articulatory_effector_flat.is_some()))
        .ok_or(FormationError::ArithmeticOverflow)?;
    let unchanged_unreached_organism_neuron_count = flat_locations
        .len()
        .checked_sub(reached_organism_neuron_count)
        .ok_or(FormationError::ArithmeticOverflow)?;
    for settlement in &mut localized_fluid_chemistry {
        settlement.unchanged_unreached_neuron_count = unchanged_unreached_organism_neuron_count;
        settlement.changed_unreached_neuron_count = 0;
    }

    let mut capacitances = Vec::with_capacity(selected.len());
    let mut membranes = Vec::with_capacity(selected.len());
    let mut available_carriers = Vec::with_capacity(selected.len());
    let mut total_carriers = Vec::with_capacity(selected.len());
    for flat in selected.iter().copied() {
        let (cohort_index, neuron_index, _) = flat_locations[flat];
        let anatomy = &cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index];
        let state = &cohorts[cohort_index].state.neurons()[neuron_index];
        capacitances.push(anatomy.capacitance());
        membranes.push(state.membrane_state());
        available_carriers.push(state.carrier_reservoirs().intracellular());
        total_carriers.push(
            state
                .carrier_reservoirs()
                .total()
                .ok_or(FormationError::ArithmeticOverflow)?,
        );
    }
    // The sleeping span ended before this clock began, so catch-up reads
    // the endpoints exactly as they stood before this clock's pump ran:
    // the predecessor clones captured ahead of pump application.
    let mut pre_pump_membranes = vec![None; selected.len()];
    let mut pre_pump_available = vec![0_u128; selected.len()];
    for (cohort_index, members) in &selected_members_by_cohort {
        let predecessors = selected_predecessor_neurons
            .get(cohort_index)
            .ok_or(FormationError::NoncanonicalState)?;
        for ((coordinate, neuron_index), (predecessor_index, predecessor)) in
            members.iter().zip(predecessors.iter())
        {
            if neuron_index != predecessor_index {
                return Err(FormationError::NoncanonicalState);
            }
            pre_pump_membranes[*coordinate] = Some(predecessor.membrane_state());
            pre_pump_available[*coordinate] = predecessor.carrier_reservoirs().intracellular();
        }
    }
    let mut compact_contacts = Vec::new();
    let mut compact_states = Vec::new();
    let mut compact_origins = Vec::new();
    let mut compact_bonds = Vec::new();
    let mut compact_edge_flat_endpoints = Vec::new();
    let mut compact_original_indices = Vec::new();
    let mut caught_up_heat = Vec::new();
    for contact_index in compact_contact_indices.iter().copied() {
        let entry = topology_index.contacts[contact_index];
        let edge = materialize_resident_contact_edge(entry, cohorts, electrical_fabric)?;
        let left = selected
            .binary_search(&edge.left)
            .map_err(|_| FormationError::NeuronLineageAuthorityAbsent)?;
        let right = selected
            .binary_search(&edge.right)
            .map_err(|_| FormationError::NeuronLineageAuthorityAbsent)?;
        // Exact sleeping-span catch-up: a contact untouched since its last
        // integration slept under frozen endpoints, so its standing drive
        // is derivable now. Its carrier phase advances across the whole
        // span in one exact step; a sleeping span moving a whole carrier
        // would violate the wake law (its crossing was scheduled), so the
        // catch-up asserts zero outward charges. The span's conduction
        // heat is deposited on this clock's settled transition.
        let mut contact_state = edge.state;
        let last = events.contact_last_integrated[contact_index];
        let mut span_heat: Option<num_rational::BigRational> = None;
        if last
            .checked_add(1)
            .ok_or(FormationError::ArithmeticOverflow)?
            < clock
        {
            let sleeping_view = |flat: usize,
                                 coordinate: usize|
             -> Result<
                (
                    crate::elementary_charge_membrane::ElementaryChargeMembraneState,
                    u128,
                ),
                FormationError,
            > {
                let lineage = flat_locations[flat].2;
                if let Some((held_membrane, held_intracellular, _)) =
                    pre_source_membranes.get(&lineage)
                {
                    return Ok((*held_membrane, *held_intracellular));
                }
                Ok((
                    pre_pump_membranes[coordinate].ok_or(FormationError::NoncanonicalState)?,
                    pre_pump_available[coordinate],
                ))
            };
            let (left_membrane, left_held_available) = sleeping_view(edge.left, left)?;
            let (right_membrane, right_held_available) = sleeping_view(edge.right, right)?;
            let left_potential = left_membrane
                .potential_millivolts(capacitances[left])
                .map_err(FormationError::InternalMembraneUnavailable)?;
            let right_potential = right_membrane
                .potential_millivolts(capacitances[right])
                .map_err(FormationError::InternalMembraneUnavailable)?;
            let standing = crate::sparse_electrical_contact::standing_contact_current(
                edge.anatomy,
                &contact_state,
                left_potential,
                left_membrane.separated_elementary_charges(),
                capacitances[left],
                left_held_available,
                right_potential,
                right_membrane.separated_elementary_charges(),
                capacitances[right],
                right_held_available,
            )
            .map_err(FormationError::ResidentElectricalUnavailable)?;
            if let Some(standing_current) = standing {
                let potential_difference = left_potential
                    .checked_sub(right_potential)
                    .map_err(|_| FormationError::ArithmeticOverflow)?;
                let caught = crate::causal_event_scheduler::catch_up_sleeping_contact(
                    crate::causal_event_scheduler::ContactIntegrationClock {
                        last_integrated_clock: last,
                    },
                    clock
                        .checked_sub(1)
                        .ok_or(FormationError::ArithmeticOverflow)?,
                    contact_state.carrier_phase(),
                    contact_state.transition_work_phase(),
                    standing_current,
                    potential_difference,
                    u32::try_from(interval_microseconds)
                        .map_err(|_| FormationError::ArithmeticOverflow)?,
                )
                .map_err(|_| FormationError::ArithmeticOverflow)?;
                assert_eq!(
                    caught.outward_elementary_charges,
                    0,
                    "a sleeping span crossed a whole carrier without its \
                     scheduled wake — the causal event schedule is unsound; \
                     contact={contact_index} last={last} clock={clock} \
                     rebuilt={needs_rebuild} endpoints=({}, {}) \
                     lineages=({:?}, {:?}) layers=({:?}, {:?}) origin={:?} \
                     predecessor_phase={:?} current={:?} left_charges={} \
                     right_charges={} left_available={} right_available={}",
                    edge.left,
                    edge.right,
                    flat_locations[edge.left].2,
                    flat_locations[edge.right].2,
                    topology_index.layer_of(flat_locations[edge.left].2),
                    topology_index.layer_of(flat_locations[edge.right].2),
                    edge.origin,
                    contact_state.carrier_phase().parts(),
                    standing_current.parts(),
                    left_membrane.separated_elementary_charges(),
                    right_membrane.separated_elementary_charges(),
                    left_held_available,
                    right_held_available,
                );
                span_heat = Some(caught.exported_heat_zeptojoules);
                contact_state = contact_state.with_caught_up_carrier_phase(caught.successor_phase);
            }
        }
        compact_contacts.push(
            edge.anatomy
                .rebind_endpoints(left, right, selected.len())
                .map_err(FormationError::ResidentElectricalUnavailable)?,
        );
        compact_states.push(contact_state);
        compact_origins.push(edge.origin);
        compact_bonds.push(edge.stable_bond);
        compact_edge_flat_endpoints.push((edge.left, edge.right));
        compact_original_indices.push(contact_index);
        caught_up_heat.push(span_heat);
    }
    if compact_contacts.is_empty() {
        return Ok(InternalContactSettlementObservation {
            dsf_delivery_count: 0,
            active_bonds: Vec::new(),
            causal_active_bonds: Vec::new(),
            causally_transitioned_lineages: Vec::new(),
            changed_contact_channel_states: Vec::new(),
            frontier_routes: Vec::new(),
            next_active_frontier: Vec::new(),
            settled_directed_transfers: Vec::new(),
            metabolically_perturbed_body_receptor_lineages: Vec::new(),
            affective_balance_trajectories: Vec::new(),
            localized_fluid_chemistry: Vec::new(),
            deferred_vocal_work_offers: Vec::new(),
            learned_motor_work_preparations: Vec::new(),
            motor_unit_recruitments: Vec::new(),
            completed_vocal_orderings: Vec::new(),
            root_yaw_unit_recruitments: Vec::new(),
            root_translation_unit_recruitments: Vec::new(),
            articulatory_unit_recruitments: Vec::new(),
            emitted_neuron_fractals: Vec::new(),
            passive_membrane_returned_neuron_lineages,
            transition_predecessors,
        });
    }
    let compact_anatomy = SparseElectricalAnatomy::new(selected.len(), compact_contacts)
        .map_err(FormationError::ResidentElectricalUnavailable)?;
    let compact_predecessor =
        SparseElectricalState::from_contact_states(&compact_anatomy, compact_states)
            .map_err(FormationError::ResidentElectricalUnavailable)?;
    let mut settled = settle_sparse_electrical_transfers(
        &compact_anatomy,
        &compact_predecessor,
        &capacitances,
        &membranes,
        &available_carriers,
        interval_microseconds,
    )
    .map_err(FormationError::ResidentElectricalUnavailable)?;
    let exact_to_wide = |value: ExactRational| {
        let (numerator, denominator) = value.parts();
        BigRational::new(BigInt::from(numerator), BigInt::from(denominator))
    };
    let mut coordinated_vocal_bridges = Vec::new();
    for position in 0..settled.transitions.len() {
        let (left_flat, right_flat) = compact_edge_flat_endpoints[position];
        let (ordering_flat, motor_flat) = match (
            layer_of(flat_locations[left_flat].2),
            layer_of(flat_locations[right_flat].2),
        ) {
            (Some(11), Some(12)) => (left_flat, right_flat),
            (Some(12), Some(11)) => (right_flat, left_flat),
            _ => continue,
        };
        let (motor_cohort, motor_neuron, motor_lineage) = flat_locations[motor_flat];
        if !cohorts[motor_cohort].anatomy.mounts()[motor_neuron]
            .body_effector_terminal()
            .is_some_and(|terminal| terminal.axis().is_vocal_articulator())
        {
            continue;
        }
        let ordering = flat_locations[ordering_flat].2;
        let bond = compact_bonds[position];
        let mut routes =
            vocal_cognitive_action_route_for_motor(cohorts, topology_index, motor_lineage)?
                .into_iter()
                .filter(|route| {
                    route.preparation.ordering_lineage == ordering && route.learned_bond == bond
                })
                .collect::<Vec<_>>();
        routes.sort_unstable();
        routes.dedup();
        let [route] = routes.as_slice() else {
            if routes.is_empty() {
                continue;
            }
            return Err(FormationError::NeuronLineageAuthorityChanged);
        };
        coordinated_vocal_bridges.push((
            ordering_flat,
            motor_flat,
            bond,
            compact_anatomy.contact_anatomies()[position]
                .effective_conductance(&compact_predecessor.contact_states()[position])
                .map_err(FormationError::ResidentElectricalUnavailable)?,
            route.clone(),
        ));
        #[cfg(test)]
        VOCAL_WORK_ROUTE_MATCHES.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    }
    coordinated_vocal_bridges.sort_by(|left, right| {
        left.0
            .cmp(&right.0)
            .then(left.1.cmp(&right.1))
            .then(left.2.cmp(&right.2))
            .then(left.4.cmp(&right.4))
    });
    coordinated_vocal_bridges.dedup_by(|left, right| {
        left.0 == right.0
            && left.1 == right.1
            && left.2 == right.2
            && left.3 == right.3
            && left.4 == right.4
    });
    let mut candidate_orderings = coordinated_vocal_bridges
        .iter()
        .map(|(_, _, _, _, route)| route.preparation.ordering_lineage)
        .collect::<Vec<_>>();
    candidate_orderings.sort_unstable();
    candidate_orderings.dedup();
    let mut founded_preparations = Vec::new();
    for ordering in candidate_orderings {
        let preparation = vocal_action_preparation_for_ordering(cohorts, topology_index, ordering)?
            .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
        // Environmental association work may found only a root vocal
        // preparation. A preparation with a learned predecessor is an
        // internal word posture and receives authority only through that
        // predecessor's conserved continuation work.
        if !preparation_predecessors(cohorts, topology_index, &preparation)?.is_empty() {
            continue;
        }
        let mut exact_sources = Vec::new();
        for association in &preparation.associations {
            let mut matches = compact_bonds
                .iter()
                .copied()
                .zip(compact_edge_flat_endpoints.iter().copied())
                .enumerate()
                .filter_map(|(position, (bond, (left, right)))| {
                    if bond != association.bond
                        || canonical_lineage_pair(flat_locations[left].2, flat_locations[right].2)
                            != canonical_lineage_pair(association.lineage, ordering)
                    {
                        return None;
                    }
                    Some((position, left, right, bond))
                })
                .collect::<Vec<_>>();
            matches.sort_unstable();
            matches.dedup();
            let [source] = matches.as_slice() else {
                exact_sources.clear();
                break;
            };
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(1, std::sync::atomic::Ordering::SeqCst);
            let Some((seed, reached)) = causal_frontier_crossing(
                source.1,
                source.2,
                is_causal_seed(source.1),
                is_causal_seed(source.2),
            ) else {
                exact_sources.clear();
                break;
            };
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(2, std::sync::atomic::Ordering::SeqCst);
            if flat_locations[seed].2 != association.lineage {
                exact_sources.clear();
                break;
            }
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(3, std::sync::atomic::Ordering::SeqCst);
            if flat_locations[reached].2 != ordering {
                exact_sources.clear();
                break;
            }
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(4, std::sync::atomic::Ordering::SeqCst);
            if !crosses_new_frontier_bond(seed, source.3) {
                exact_sources.clear();
                break;
            }
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(5, std::sync::atomic::Ordering::SeqCst);
            if is_body_owned_acoustic_efference_seed(seed) {
                exact_sources.clear();
                break;
            }
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(6, std::sync::atomic::Ordering::SeqCst);
            if settled.transitions[source.0].released_work_zeptojoules <= BigRational::zero() {
                exact_sources.clear();
                break;
            }
            #[cfg(test)]
            VOCAL_WORK_SOUND_MATCHES.fetch_max(7, std::sync::atomic::Ordering::SeqCst);
            exact_sources.push((source.0, association.lineage));
        }
        exact_sources.sort_unstable();
        exact_sources.dedup();
        if exact_sources.len() == preparation.associations.len() {
            #[cfg(test)]
            VOCAL_WORK_SOURCE_TRANSITIONS.fetch_add(
                u64::try_from(exact_sources.len())
                    .map_err(|_| FormationError::ArithmeticOverflow)?,
                std::sync::atomic::Ordering::SeqCst,
            );
            founded_preparations.push((ordering, exact_sources));
        }
    }
    let founded_preparation = match founded_preparations.as_slice() {
        [] => None,
        [founded] => Some(founded),
        _ => {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        }
    };
    let mut preplastic_vocal_work_offers = BTreeMap::<[u8; 16], Vec<LearnedMotorWorkOffer>>::new();
    let mut reserved_by_source = BTreeMap::<usize, BigRational>::new();
    if admit_learned_motor_work {
        if let Some((ordering, sources)) = founded_preparation {
            let branches = coordinated_vocal_bridges
                .iter()
                .filter(|(_, _, _, _, route)| route.preparation.ordering_lineage == *ordering)
                .collect::<Vec<_>>();
            let total_branch_conductance = branches
                .iter()
                .fold(BigRational::zero(), |sum, (_, _, _, conductance, _)| {
                    sum + exact_to_wide(*conductance)
                });
            for (source_position, association_lineage) in sources.iter().copied() {
                let source_conductance = exact_to_wide(
                    compact_anatomy.contact_anatomies()[source_position]
                        .effective_conductance(
                            &compact_predecessor.contact_states()[source_position],
                        )
                        .map_err(FormationError::ResidentElectricalUnavailable)?,
                );
                let denominator = &source_conductance + &total_branch_conductance;
                if denominator <= BigRational::zero() {
                    return Err(FormationError::ArithmeticOverflow);
                }
                let raw_work = settled.transitions[source_position]
                    .released_work_zeptojoules
                    .clone();
                for (_, motor_flat, learned_bond, learned_conductance, route) in &branches {
                    let offered_work =
                        &raw_work * exact_to_wide(*learned_conductance) / &denominator;
                    if offered_work <= BigRational::zero() {
                        continue;
                    }
                    let motor_lineage = flat_locations[*motor_flat].2;
                    preplastic_vocal_work_offers
                        .entry(motor_lineage)
                        .or_default()
                        .push(LearnedMotorWorkOffer {
                            ordering_lineage: *ordering,
                            founding_receiver_lineage: association_lineage,
                            motor_lineage,
                            founding_bond: compact_bonds[source_position],
                            learned_bond: *learned_bond,
                            source_transition_position: source_position,
                            offered_work_zeptojoules: offered_work.clone(),
                            reserved_before_source_plasticity: true,
                        });
                    #[cfg(test)]
                    VOCAL_WORK_OFFERS.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    *reserved_by_source
                        .entry(source_position)
                        .or_insert_with(BigRational::zero) += offered_work;
                    if route.preparation.ordering_lineage != *ordering {
                        return Err(FormationError::NeuronLineageAuthorityChanged);
                    }
                }
            }
        }
    }
    let mut contact_successors = Vec::with_capacity(settled.transitions.len());
    let mut contact_transitions = Vec::with_capacity(settled.transitions.len());
    for ((contact, transition), (left_flat, right_flat)) in compact_anatomy
        .contact_anatomies()
        .iter()
        .copied()
        .zip(settled.transitions.iter().cloned())
        .zip(compact_edge_flat_endpoints.iter().copied())
    {
        let left_direction = local_gradient_direction(
            &reached_layer_ten_gradient_settlements,
            flat_locations[left_flat].2,
        );
        let right_direction = local_gradient_direction(
            &reached_layer_ten_gradient_settlements,
            flat_locations[right_flat].2,
        );
        let transition =
            settle_contact_local_conductance(contact, transition, left_direction, right_direction)
                .map_err(FormationError::ResidentElectricalUnavailable)?;
        contact_successors.push(transition.successor.clone());
        contact_transitions.push(transition);
    }
    settled.successor_contacts =
        SparseElectricalState::from_contact_states(&compact_anatomy, contact_successors)
            .map_err(FormationError::ResidentElectricalUnavailable)?;
    settled.transitions = contact_transitions.into_boxed_slice();
    // Conservation across sleeping spans: the caught-up conduction heat of
    // each span joins this clock's settled transition for that contact —
    // released as work and exported as heat, exactly as the per-clock law
    // would have accumulated it.
    for (position, span_heat) in caught_up_heat.iter().enumerate() {
        if let Some(heat) = span_heat {
            settled.transitions[position].released_work_zeptojoules += heat;
            settled.transitions[position].exported_heat_zeptojoules += heat;
        }
    }

    // Non-vocal L11/L12 learned contacts retain the established work-transducer
    // law. A coordinated vocal L11 is instead the one physical action
    // preparation: its exact L7/L11 donor work is held only after distributed
    // reassembly selects it, and its ordinary later L11/L12 carriers drive the
    // typed motors. Candidate offers remain transient until that selection.
    let mut learned_motor_work_offers = BTreeMap::<[u8; 16], Vec<LearnedMotorWorkOffer>>::new();
    let mut deferred_vocal_work_offers = Vec::<LearnedMotorWorkOffer>::new();
    {
        let mut ordering_motor_bridges = Vec::new();
        for position in 0..settled.transitions.len() {
            let (left_flat, right_flat) = compact_edge_flat_endpoints[position];
            let left_layer = layer_of(flat_locations[left_flat].2);
            let right_layer = layer_of(flat_locations[right_flat].2);
            if !matches!((left_layer, right_layer), (Some(11), Some(12)))
                && !matches!((left_layer, right_layer), (Some(12), Some(11)))
            {
                continue;
            }
            let (ordering_flat, motor_flat) = if left_layer == Some(11) {
                (left_flat, right_flat)
            } else {
                (right_flat, left_flat)
            };
            let (motor_cohort, motor_neuron, motor_lineage) = flat_locations[motor_flat];
            let ordering_lineage = flat_locations[ordering_flat].2;
            let motor_is_vocal = cohorts[motor_cohort].anatomy.mounts()[motor_neuron]
                .body_effector_terminal()
                .is_some_and(|terminal| terminal.axis().is_vocal_articulator());
            let coordinated_vocal_bridge = if motor_is_vocal {
                let motor_bond = compact_bonds[position];
                let mut matching_routes =
                    vocal_cognitive_action_route_for_motor(cohorts, topology_index, motor_lineage)?
                        .into_iter()
                        .filter(|route| {
                            route.preparation.ordering_lineage == ordering_lineage
                                && route.learned_bond == motor_bond
                        })
                        .collect::<Vec<_>>();
                matching_routes.sort_unstable();
                matching_routes.dedup();
                match matching_routes.as_slice() {
                    [_] => true,
                    [] => false,
                    _ => return Err(FormationError::NeuronLineageAuthorityChanged),
                }
            } else {
                false
            };
            if !coordinated_vocal_bridge
                || !permitted_vocal_ordering_work.contains(&ordering_lineage)
                || !permitted_vocal_motor_bonds.contains(&compact_bonds[position])
            {
                let signed = settled.transitions[position].outward_elementary_charges_from_left;
                let left_coordinate = selected
                    .binary_search(&left_flat)
                    .map_err(|_| FormationError::NoncanonicalState)?;
                let right_coordinate = selected
                    .binary_search(&right_flat)
                    .map_err(|_| FormationError::NoncanonicalState)?;
                settled.outward_elementary_charges_by_neuron[left_coordinate] = settled
                    .outward_elementary_charges_by_neuron[left_coordinate]
                    .checked_sub(signed)
                    .ok_or(FormationError::ArithmeticOverflow)?;
                settled.outward_elementary_charges_by_neuron[right_coordinate] = settled
                    .outward_elementary_charges_by_neuron[right_coordinate]
                    .checked_add(signed)
                    .ok_or(FormationError::ArithmeticOverflow)?;
                settled.transitions[position] = ElectricalContactTransition {
                    successor: compact_predecessor.contact_states()[position].clone(),
                    outward_current_from_left_picoamperes: ExactRational::integer(0),
                    outward_elementary_charges_from_left: 0,
                    released_work_zeptojoules: BigRational::zero(),
                    exported_heat_zeptojoules: BigRational::zero(),
                    conductance_changed: false,
                };
            }
            let learned_conductance = compact_anatomy.contact_anatomies()[position]
                .effective_conductance(&compact_predecessor.contact_states()[position])
                .map_err(FormationError::ResidentElectricalUnavailable)?;
            ordering_motor_bridges.push((
                ordering_flat,
                motor_flat,
                compact_bonds[position],
                learned_conductance,
            ));
        }
        settled.successor_contacts = SparseElectricalState::from_contact_states(
            &compact_anatomy,
            settled
                .transitions
                .iter()
                .map(|transition| transition.successor.clone())
                .collect::<Vec<_>>(),
        )
        .map_err(FormationError::ResidentElectricalUnavailable)?;
        ordering_motor_bridges.sort_by(|left, right| {
            left.0
                .cmp(&right.0)
                .then(left.1.cmp(&right.1))
                .then(left.2.cmp(&right.2))
        });
        ordering_motor_bridges.dedup_by(|left, right| {
            left.0 == right.0 && left.1 == right.1 && left.2 == right.2 && left.3 == right.3
        });
        let exact_to_wide = |value: ExactRational| {
            let (numerator, denominator) = value.parts();
            BigRational::new(BigInt::from(numerator), BigInt::from(denominator))
        };
        for (ordering_flat, motor_flat, motor_bond, learned_conductance) in
            ordering_motor_bridges.iter().copied()
        {
            // An in-flight body-owned acoustic consequence still reaches and
            // settles the auditory/cognitive fabric.  Its returning pressure
            // is efference from the act already being discharged, however, so
            // it cannot author fresh learned motor work for that same act.
            // This provenance lives only on the already-bounded causal
            // frontier and expires with that frontier; it creates no separate
            // owner, timer, or lifetime.
            if !admit_learned_motor_work {
                continue;
            }
            let motor_lineage = flat_locations[motor_flat].2;
            let (motor_cohort, motor_neuron, _) = flat_locations[motor_flat];
            let motor_is_vocal = cohorts[motor_cohort].anatomy.mounts()[motor_neuron]
                .body_effector_terminal()
                .is_some_and(|terminal| terminal.axis().is_vocal_articulator());
            let total_learned_conductance = ordering_motor_bridges
                .iter()
                .filter(|(candidate_ordering, _, _, _)| *candidate_ordering == ordering_flat)
                .fold(BigRational::zero(), |sum, (_, _, _, conductance)| {
                    sum + exact_to_wide(*conductance)
                });
            if motor_is_vocal {
                // Coordinated vocal branches were already funded from the raw
                // source work before source-contact plasticity. Re-authoring
                // them from post-plastic heat would double spend the donor.
                continue;
            }
            let source_candidates = settled
                .transitions
                .iter()
                .zip(compact_edge_flat_endpoints.iter().copied())
                .enumerate()
                .filter_map(|(position, (transition, (left_flat, right_flat)))| {
                    let signed = transition.outward_elementary_charges_from_left;
                    if signed == 0 {
                        return None;
                    }
                    let founding_flat = if left_flat == ordering_flat {
                        right_flat
                    } else if right_flat == ordering_flat {
                        left_flat
                    } else {
                        return None;
                    };
                    if layer_of(flat_locations[founding_flat].2) != Some(7) {
                        return None;
                    }
                    let ordering_is_seed = is_causal_seed(ordering_flat);
                    let founding_is_seed = is_causal_seed(founding_flat);
                    if ordering_is_seed == founding_is_seed {
                        return None;
                    }
                    let causal_seed = if ordering_is_seed {
                        ordering_flat
                    } else {
                        founding_flat
                    };
                    if is_body_owned_acoustic_efference_seed(causal_seed) {
                        return None;
                    }
                    crosses_new_frontier_bond(causal_seed, compact_bonds[position])
                        .then_some((position, founding_flat))
                })
                .collect::<Vec<_>>();
            for (source_position, founding_flat) in source_candidates {
                let source_conductance = compact_anatomy.contact_anatomies()[source_position]
                    .effective_conductance(&compact_predecessor.contact_states()[source_position])
                    .map_err(FormationError::ResidentElectricalUnavailable)?;
                let denominator = exact_to_wide(source_conductance) + &total_learned_conductance;
                if denominator <= BigRational::zero()
                    || learned_conductance.parts().0 <= 0
                    || settled.transitions[source_position]
                        .exported_heat_zeptojoules
                        .is_zero()
                {
                    continue;
                }
                let offered_work = &settled.transitions[source_position].exported_heat_zeptojoules
                    * exact_to_wide(learned_conductance)
                    / denominator;
                #[cfg(test)]
                let offered_work =
                    offered_work * BigInt::from(artificial_learned_motor_source_population_scale());
                if offered_work <= BigRational::zero() {
                    continue;
                }
                learned_motor_work_offers
                    .entry(motor_lineage)
                    .or_default()
                    .push(LearnedMotorWorkOffer {
                        ordering_lineage: flat_locations[ordering_flat].2,
                        founding_receiver_lineage: flat_locations[founding_flat].2,
                        motor_lineage,
                        founding_bond: compact_bonds[source_position],
                        learned_bond: motor_bond,
                        source_transition_position: source_position,
                        offered_work_zeptojoules: offered_work,
                        reserved_before_source_plasticity: false,
                    });
            }
        }
        for offers in learned_motor_work_offers.values_mut() {
            offers.sort_by(|left, right| {
                left.source_transition_position
                    .cmp(&right.source_transition_position)
                    .then(left.learned_bond.cmp(&right.learned_bond))
            });
            offers.dedup();
        }
        deferred_vocal_work_offers.sort_by(|left, right| {
            left.ordering_lineage
                .cmp(&right.ordering_lineage)
                .then(left.motor_lineage.cmp(&right.motor_lineage))
                .then(
                    left.source_transition_position
                        .cmp(&right.source_transition_position),
                )
                .then(left.learned_bond.cmp(&right.learned_bond))
        });
        deferred_vocal_work_offers.dedup();
        #[cfg(test)]
        {
            let population_scale = artificial_learned_motor_source_population_scale();
            if population_scale > 1 {
                let source_positions = learned_motor_work_offers
                    .values()
                    .flat_map(|offers| offers.iter().map(|offer| offer.source_transition_position))
                    .collect::<BTreeSet<_>>();
                let population_scale = BigInt::from(population_scale);
                for source_position in source_positions {
                    let transition = settled
                        .transitions
                        .get_mut(source_position)
                        .expect("test population source transition exists");
                    transition.released_work_zeptojoules *= &population_scale;
                    transition.exported_heat_zeptojoules *= &population_scale;
                }
            }
        }
    }

    // The compact predecessor, compact anatomy, stable bond, and settled
    // successor share one construction order. Project only the sparse reached
    // contacts whose retained channel population or transition-work phase
    // changed; do not rescan the resident organism after settlement.
    let mut changed_contact_channel_states = Vec::new();
    for (((anatomy, predecessor), transition), bond) in compact_anatomy
        .contact_anatomies()
        .iter()
        .copied()
        .zip(compact_predecessor.contact_states())
        .zip(settled.transitions.iter())
        .zip(compact_bonds.iter().copied())
    {
        let successor = &transition.successor;
        if predecessor.conducting_channel_population() == successor.conducting_channel_population()
            && predecessor.transition_work_phase() == successor.transition_work_phase()
        {
            continue;
        }
        changed_contact_channel_states.push(ChangedContactChannelStateObservation {
            cognitive_ordinal,
            bond,
            predecessor_conducting_channel_population: predecessor.conducting_channel_population(),
            predecessor_transition_work_phase: predecessor.transition_work_phase(),
            predecessor_effective_conductance_picosiemens: anatomy
                .effective_conductance(predecessor)
                .map_err(FormationError::ResidentElectricalUnavailable)?,
            successor_conducting_channel_population: successor.conducting_channel_population(),
            successor_transition_work_phase: successor.transition_work_phase(),
            successor_effective_conductance_picosiemens: anatomy
                .effective_conductance(successor)
                .map_err(
                FormationError::ResidentElectricalUnavailable,
            )?,
        });
    }

    // Preserve exact pathway-local contact activity before the endpoint
    // consequences are applied. A layer-10 cell qualifies for local fluid
    // modulation only when this same interval physically reaches it from
    // both its association (layer 7) and body-regulation (layer 8) contacts.
    // Magnitudes are catalyst quanta; direction is preserved separately by
    // the settled transfer evidence and is not converted into valence.
    let mut layer_ten_contact_activity = BTreeMap::<[u8; 16], (u128, u128)>::new();
    for (transition, (left_flat, right_flat)) in settled
        .transitions
        .iter()
        .zip(compact_edge_flat_endpoints.iter().copied())
    {
        let magnitude = transition
            .outward_elementary_charges_from_left
            .unsigned_abs();
        if magnitude == 0 {
            continue;
        }
        for (candidate_flat, adjacent_flat) in [(left_flat, right_flat), (right_flat, left_flat)] {
            let candidate = flat_locations[candidate_flat].2;
            if layer_of(candidate) != Some(10) {
                continue;
            }
            let adjacent_layer = layer_of(flat_locations[adjacent_flat].2);
            if !matches!(adjacent_layer, Some(7 | 8)) {
                continue;
            }
            let activity = layer_ten_contact_activity
                .entry(candidate)
                .or_insert((0, 0));
            let target = if adjacent_layer == Some(7) {
                &mut activity.0
            } else {
                &mut activity.1
            };
            *target = target
                .checked_add(magnitude)
                .ok_or(FormationError::ArithmeticOverflow)?;
        }
    }
    let mut pre_field = Vec::with_capacity(selected.len());
    let mut post_field = Vec::with_capacity(selected.len());
    let mut coordinate_bounds = Vec::with_capacity(selected.len());
    let mut post_membranes = Vec::with_capacity(selected.len());
    for coordinate in 0..selected.len() {
        let transition = settle_membrane_elementary_charges(
            capacitances[coordinate],
            membranes[coordinate],
            settled.outward_elementary_charges_by_neuron[coordinate],
            interval_microseconds,
        )
        .map_err(FormationError::InternalMembraneUnavailable)?;
        let pre = exact_rational_binary64(transition.predecessor_potential_millivolts)?;
        let post = exact_rational_binary64(transition.successor_potential_millivolts)?;
        // The live membrane may already hold separated charge established by
        // its own gate paths in addition to the presently mobile contact
        // reservoir.  The internal occurrence's closed physical span must
        // therefore contain exact predecessor separation, exact successor
        // separation, and all finite carrier material that could move through
        // the reached contact.  These are the transition's own conserved
        // physical endpoints/material, not a statistical or tuned range.
        let carrier_bound = i128::try_from(total_carriers[coordinate])
            .map_err(|_| FormationError::ArithmeticOverflow)?
            .max(
                membranes[coordinate]
                    .separated_elementary_charges()
                    .unsigned_abs()
                    .try_into()
                    .map_err(|_| FormationError::ArithmeticOverflow)?,
            )
            .max(
                transition
                    .successor
                    .separated_elementary_charges()
                    .unsigned_abs()
                    .try_into()
                    .map_err(|_| FormationError::ArithmeticOverflow)?,
            );
        let positive_bound = settle_membrane_elementary_charges(
            capacitances[coordinate],
            crate::elementary_charge_membrane::ElementaryChargeMembraneState::genesis(
                carrier_bound,
            ),
            0,
            interval_microseconds,
        )
        .map_err(FormationError::InternalMembraneUnavailable)?
        .predecessor_potential_millivolts;
        let bound = exact_rational_binary64(positive_bound)?.abs();
        pre_field.push(pre);
        post_field.push(post);
        coordinate_bounds.push(
            JointUfCoordinateBounds::new(-bound, bound).map_err(|error| {
                FormationError::JointFieldUnavailable(JointNeuronBoundaryError::Source(
                    JointUfSourceError::Physics(error),
                ))
            })?,
        );
        post_membranes.push(transition.successor);
    }

    let duration = BigRational::from_integer(BigInt::from(interval_microseconds));
    let input = JointUfInput {
        times: vec![BigRational::zero(), duration.clone()],
        fields: vec![pre_field, post_field],
        relevance: vec![1.0, 1.0],
        intersample_law: JointIntersampleLaw::SampledVolumeAndRelevancePiecewiseLinear,
    };
    let bounds = JointUfPhysicalBounds::new(coordinate_bounds, duration).map_err(|error| {
        FormationError::JointFieldUnavailable(JointNeuronBoundaryError::Source(
            JointUfSourceError::Physics(error),
        ))
    })?;
    let field = joint_uf_v1_4::evaluate_with_physical_bounds(input, bounds).map_err(|error| {
        FormationError::JointFieldUnavailable(JointNeuronBoundaryError::Source(
            JointUfSourceError::Physics(error),
        ))
    })?;
    let groups = contact_components(selected.len(), &compact_anatomy);
    let source_body = Arc::<[u8]>::from(encode_internal_contact_source(
        &selected,
        &flat_locations,
        &membranes,
        &post_membranes,
        &capacitances,
        interval_microseconds,
        &compact_anatomy,
        &compact_predecessor,
    )?);
    let source_authority = sha256(&source_body);
    let shared = prepare_complete_joint_field_from_evaluated(
        source_body,
        source_authority,
        0,
        EvaluatedJointSourceOccurrence {
            port_indices: (0..selected.len()).collect(),
            groups,
            field,
        },
    )
    .map_err(FormationError::JointFieldUnavailable)?;
    if shared.result().gates.len() != 1 {
        return Err(FormationError::NoncanonicalState);
    }

    // Local contact successors are prepared only for reached cohorts.  The
    // former population-width construction copied every local contact state
    // and allocated one neuron-width outward array for every unrelated cohort.
    let mut local_contact_results = BTreeMap::<
        usize,
        (
            Vec<ElectricalContactState>,
            Vec<ElectricalContactTransition>,
        ),
    >::new();
    for cohort_index in selected_cohort_indices.iter().copied() {
        let cohort = &cohorts[cohort_index];
        local_contact_results.insert(
            cohort_index,
            (
                cohort.state.electrical().contact_states().to_vec(),
                cohort
                    .state
                    .electrical()
                    .contact_states()
                    .iter()
                    .cloned()
                    .map(|successor| ElectricalContactTransition {
                        successor,
                        outward_current_from_left_picoamperes: ExactRational::integer(0),
                        outward_elementary_charges_from_left: 0,
                        released_work_zeptojoules: BigRational::zero(),
                        exported_heat_zeptojoules: BigRational::zero(),
                        conductance_changed: false,
                    })
                    .collect::<Vec<_>>(),
            ),
        );
    }
    let mut fabric_successors = Vec::new();
    for (origin, transition) in compact_origins
        .iter()
        .copied()
        .zip(settled.transitions.iter().cloned())
    {
        match origin {
            ResidentContactOrigin::Local {
                cohort_index,
                contact_index,
                left_member,
                right_member,
            } => {
                let (successors, transitions) = local_contact_results
                    .get_mut(&cohort_index)
                    .ok_or(FormationError::NoncanonicalState)?;
                successors[contact_index] = transition.successor.clone();
                transitions[contact_index] = transition.clone();
                let _ = (left_member, right_member);
            }
            ResidentContactOrigin::Fabric { contact_index } => {
                fabric_successors.push((contact_index, transition.successor));
            }
        }
    }
    fabric_successors.sort_unstable_by_key(|(contact_index, _)| *contact_index);
    electrical_fabric
        .replace_contact_states(fabric_successors)
        .map_err(FormationError::ResidentElectricalUnavailable)?;

    // Preserve the exact directed whole-carrier transfers from this settled
    // interval before the disjoint cohort consequences are applied. A motor
    // recruitment may use only the exact current settled across its direct
    // contact with a mounted layer-11 neighbour or its own exact reacted-load
    // layer-8 regulator. The two endpoint potentials jointly cause that
    // transfer; its observed direction is never rewritten.
    let mut settled_directed_transfers = Vec::new();
    for ((transition, bond), (left_flat, right_flat)) in settled
        .transitions
        .iter()
        .zip(&compact_bonds)
        .zip(compact_edge_flat_endpoints.iter().copied())
    {
        if let Some(transfer) = directed_physical_transfer(
            transition.outward_elementary_charges_from_left,
            flat_locations[left_flat].2,
            flat_locations[right_flat].2,
            *bond,
        ) {
            settled_directed_transfers.push(transfer);
        }
    }
    settled_directed_transfers.sort_unstable();
    settled_directed_transfers.dedup();

    // Retain the sparse active set for reached-frontier learning and the next
    // physical settlement. It is scheduling state, not effector authority:
    // motor and articulatory emission are governed below by their mounted
    // preparation transfers and their own outward carrier discharge.
    let causal_seed_lineages = causal_seed_flats
        .iter()
        .map(|flat| flat_locations[*flat].2)
        .collect::<BTreeSet<_>>();
    let mut causally_active_lineages = causal_seed_lineages.clone();
    let fresh_seed_lineages = fresh_seed_flats
        .iter()
        .map(|flat| flat_locations[*flat].2)
        .collect::<BTreeSet<_>>();
    for (transition, (left_flat, right_flat)) in settled
        .transitions
        .iter()
        .zip(compact_edge_flat_endpoints.iter().copied())
    {
        let signed_transfer = transition.outward_elementary_charges_from_left;
        let reached_flat = if signed_transfer > 0 && is_causal_seed(left_flat) {
            Some(right_flat)
        } else if signed_transfer < 0 && is_causal_seed(right_flat) {
            Some(left_flat)
        } else {
            None
        };
        if let Some(reached_flat) = reached_flat {
            let lineage = flat_locations[reached_flat].2;
            causally_active_lineages.insert(lineage);
        }
    }

    // Resolve only the mounted reacted-load branch before the disjoint cohort
    // mutation begins. Tonic antagonist-length receptors share layer 8, but
    // they are position sense—not a stop/load reflex—and must not recruit the
    // whole motor population merely because the body is present.
    let mut body_regulations_by_motor = BTreeMap::<[u8; 16], Vec<[u8; 16]>>::new();
    let mut root_yaw_regulations_by_motor = BTreeMap::<[u8; 16], Vec<[u8; 16]>>::new();
    for (motor_flat, (_, _, motor_lineage)) in flat_locations.iter().copied().enumerate() {
        if layer_of(motor_lineage) != Some(12) {
            continue;
        }
        let paths = exact_motor_body_afferent_paths(
            motor_flat,
            flat_locations,
            cohorts,
            &topology_index.neighbours_by_flat,
        )?;
        let (cohort_index, neuron_index, _) = flat_locations[motor_flat];
        let motor_mount = &cohorts[cohort_index].anatomy.mounts()[neuron_index];
        if let Some(motor_terminal) = motor_mount.body_effector_terminal() {
            let regulations = exact_articulated_body_preparation_regulations(
                motor_terminal,
                &paths,
                palmar_contact_onset_receptor_lineages,
                gustatory_contact_onset_receptor_lineages,
            );
            if !regulations.is_empty() {
                body_regulations_by_motor.insert(motor_lineage, regulations);
            }
        }
        if let Some(motor_terminal) = motor_mount.root_yaw_effector_terminal() {
            if motor_mount.source_site().is_some() {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            }
            let root_yaw_regulations =
                exact_root_yaw_preparation_regulations(motor_terminal, &paths);
            if !root_yaw_regulations.is_empty() {
                root_yaw_regulations_by_motor.insert(motor_lineage, root_yaw_regulations);
            }
        }
        if motor_mount.root_translation_effector_terminal().is_some() {
            if motor_mount.source_site().is_some() {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            }
        }
    }
    // The shared contact field and carrier transfers above are settled once.
    // Each cohort then owns a disjoint anatomy, state and recovery reservoir,
    // so those local consequences can settle concurrently without changing
    // causal order or allowing one cohort to observe another's mutation.
    // Indexed collection preserves cohort order for the evidence merge below.
    // Every selected neuron below is settling gate zero of this one completed
    // field. Its seven DSF values therefore have one exact balanced-ternary
    // conversion per mounted width, not one conversion per neuron. Psi remains
    // neuron-local; only the immutable gate-owned delivery is shared.
    let canonical_perspective =
        bind_neuron_perspective(&shared, 0, 0).map_err(FormationError::JointFieldUnavailable)?;
    let shared_required_positions = required_mathloom_positions(canonical_perspective)
        .map_err(FormationError::JointFieldUnavailable)?;
    let mut reached_mathloom_widths = std::collections::BTreeSet::new();
    for (cohort_index, selected_members) in &selected_members_by_cohort {
        let cohort = cohorts
            .get(*cohort_index)
            .ok_or(FormationError::NoncanonicalState)?;
        for (_, neuron_index) in selected_members {
            reached_mathloom_widths.insert(
                cohort.anatomy.neuron_anatomies()[*neuron_index]
                    .mathloom_positions()
                    .max(shared_required_positions),
            );
        }
    }
    let mut reached_mathloom_deliveries = BTreeMap::<usize, BorrowedMathLoomDelivery<'_>>::new();
    for positions in reached_mathloom_widths {
        let anatomy =
            MathLoomAnatomy::new(positions).map_err(FormationError::JointFieldUnavailable)?;
        reached_mathloom_deliveries.insert(
            positions,
            crate::joint_uf_neuron_boundary::settle_shared_dsf_mathloom(
                canonical_perspective,
                anatomy,
            )
            .map_err(FormationError::JointFieldUnavailable)?,
        );
    }
    let mut reached_psi_deliveries = BTreeMap::<usize, PreparedPsiKrimelackDelivery>::new();
    for (cohort_index, selected_members) in &selected_members_by_cohort {
        let cohort = cohorts
            .get(*cohort_index)
            .ok_or(FormationError::NoncanonicalState)?;
        for (_, neuron_index) in selected_members {
            let anatomy = &cohort.anatomy.neuron_anatomies()[*neuron_index];
            if shared_required_positions > anatomy.mathloom_positions() {
                continue;
            }
            let identity = anatomy.heavy_anatomy_identity();
            if reached_psi_deliveries.contains_key(&identity) {
                continue;
            }
            let delivery = reached_mathloom_deliveries
                .get(&anatomy.mathloom_positions())
                .ok_or(FormationError::NoncanonicalState)?;
            reached_psi_deliveries.insert(
                identity,
                anatomy
                    .prepare_shared_psi_delivery(delivery)
                    .map_err(|error| {
                        FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                            neuron_index: *neuron_index,
                            error,
                        })
                    })?,
            );
        }
    }
    let mut selected_cohort_work = Vec::with_capacity(selected_cohort_indices.len());
    for cohort_index in selected_cohort_indices.iter().copied() {
        let selected_members = selected_members_by_cohort
            .remove(&cohort_index)
            .ok_or(FormationError::NoncanonicalState)?;
        let local_contact_result = local_contact_results
            .remove(&cohort_index)
            .ok_or(FormationError::NoncanonicalState)?;
        selected_cohort_work.push((cohort_index, selected_members, local_contact_result));
    }
    if !selected_members_by_cohort.is_empty() || !local_contact_results.is_empty() {
        return Err(FormationError::NoncanonicalState);
    }
    let cohort_results = selected_cohorts_mut(cohorts, &selected_cohort_indices)?
        .into_par_iter()
        .zip(selected_cohort_work.into_par_iter())
        .map(
            |(
                (cohort_index, cohort),
                (work_cohort_index, selected_members, local_contact_result),
            )|
             -> Result<
                Option<(
                    Vec<TransitionNeuronPredecessor>,
                    Vec<MotorUnitRecruitment>,
                    Vec<RootYawUnitRecruitment>,
                    Vec<RootTranslationUnitRecruitment>,
                    Vec<ArticulatoryUnitRecruitment>,
                    Vec<EmittedNeuronFractal>,
                    Vec<PendingLayerTenPlasticitySettlement>,
                    Vec<LearnedMotorWorkPreparation>,
                    Vec<LearnedSourceWorkDebit>,
                )>,
                FormationError,
            > {
                if cohort_index != work_cohort_index || selected_members.is_empty() {
                    return Err(FormationError::NoncanonicalState);
                }
                let mut required_positions = cohort
                    .anatomy
                    .neuron_anatomies()
                    .iter()
                    .map(|anatomy| anatomy.mathloom_positions())
                    .collect::<Vec<_>>();
                for (coordinate, neuron_index) in selected_members.iter().copied() {
                    let perspective = bind_neuron_perspective(&shared, coordinate, 0)
                        .map_err(FormationError::JointFieldUnavailable)?;
                    required_positions[neuron_index] = required_positions[neuron_index].max(
                        required_mathloom_positions(perspective)
                            .map_err(FormationError::JointFieldUnavailable)?,
                    );
                }
                let positional_growth = cohort
                    .anatomy
                    .neuron_anatomies()
                    .iter()
                    .zip(&required_positions)
                    .any(|(anatomy, required)| *required > anatomy.mathloom_positions());
                let held_predecessors = selected_predecessor_neurons
                    .get(&cohort_index)
                    .ok_or(FormationError::NoncanonicalState)?;
                let comparison_predecessors = if positional_growth {
                    held_predecessors
                        .iter()
                        .map(|(neuron_index, predecessor)| {
                            let (extended_anatomy, extended_predecessor) =
                                extend_neuron_positional_fabric(
                                    &cohort.anatomy.neuron_anatomies()[*neuron_index],
                                    predecessor,
                                    required_positions[*neuron_index],
                                )
                                .map_err(|error| {
                                    FormationError::PhysicalSettlementUnavailable(
                                        ReachedCohortError::Neuron {
                                            neuron_index: *neuron_index,
                                            error,
                                        },
                                    )
                                })?;
                            Ok(SettlementComparisonPredecessor::Extended {
                                neuron_index: *neuron_index,
                                anatomy: extended_anatomy,
                                state: extended_predecessor,
                            })
                        })
                        .collect::<Result<Vec<_>, FormationError>>()?
                } else {
                    held_predecessors
                        .iter()
                        .map(|(neuron_index, predecessor)| {
                            SettlementComparisonPredecessor::Borrowed {
                                neuron_index: *neuron_index,
                                state: predecessor,
                            }
                        })
                        .collect::<Vec<_>>()
                };
                if positional_growth {
                    extend_resident_cohort_positional_fabrics(cohort, &required_positions)?;
                }
                for predecessor in &comparison_predecessors {
                    let SettlementComparisonPredecessor::Extended {
                        neuron_index,
                        anatomy,
                        ..
                    } = predecessor
                    else {
                        continue;
                    };
                    if anatomy != &cohort.anatomy.neuron_anatomies()[*neuron_index] {
                        return Err(FormationError::NoncanonicalState);
                    }
                }
                let catalysts = selected_members
                    .iter()
                    .map(|(_, neuron_index)| {
                        vec![
                            0;
                            cohort.anatomy.neuron_anatomies()[*neuron_index]
                                .recovery_anatomy()
                                .psi_lane_count()
                        ]
                        .into_boxed_slice()
                    })
                    .collect::<Vec<Box<[u128]>>>();
                let resident_indices = selected_members
                    .iter()
                    .map(|(_, neuron_index)| *neuron_index)
                    .collect::<Vec<_>>();
                let combined_outward = selected_members
                    .iter()
                    .map(|(coordinate, _)| {
                        settled.outward_elementary_charges_by_neuron[*coordinate]
                    })
                    .collect::<Vec<_>>();
                let mut inputs = Vec::with_capacity(selected_members.len());
                let mut pending_layer_ten_plasticity = Vec::new();
                let mut cohort_learned_work_preparations = Vec::new();
                let mut cohort_learned_source_debits = Vec::new();
                for (reached_input_index, (coordinate, neuron_index)) in
                    selected_members.iter().copied().enumerate()
                {
                    let perspective = bind_neuron_perspective(&shared, coordinate, 0)
                        .map_err(FormationError::JointFieldUnavailable)?;
                    let neuron_anatomy = &cohort.anatomy.neuron_anatomies()[neuron_index];
                    let prepared_psi = if let Some(prepared_delivery) =
                        reached_psi_deliveries.get(&neuron_anatomy.heavy_anatomy_identity())
                    {
                        neuron_anatomy.settle_prepared_psi_delivery(
                            &cohort.state.neurons()[neuron_index],
                            prepared_delivery,
                        )
                    } else {
                        let delivery = reached_mathloom_deliveries
                            .get(&neuron_anatomy.mathloom_positions())
                            .ok_or(FormationError::NoncanonicalState)?
                            .for_perspective(perspective)
                            .map_err(FormationError::JointFieldUnavailable)?;
                        neuron_anatomy.prepare_psi_settlement_from_delivery(
                            &cohort.state.neurons()[neuron_index],
                            &delivery,
                        )
                    }
                    .map_err(|error| {
                        FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                            neuron_index,
                            error,
                        })
                    })?;
                    let lineage = cohort.anatomy.neuron_lineages()[neuron_index];
                    let convergent_activity = match layer_ten_contact_activity.get(&lineage) {
                        Some(&(association, body)) => {
                            if association != 0 && body != 0 {
                                Some(
                                    association
                                        .checked_add(body)
                                        .ok_or(FormationError::ArithmeticOverflow)?,
                                )
                            } else {
                                None
                            }
                        }
                        None => None,
                    };
                    let gradient_changed =
                        reached_layer_ten_gradient_settlements
                            .iter()
                            .any(|gradient| {
                                gradient.neuron_lineage == lineage && gradient.metabolic.changed()
                            });
                    let retained_continuation_work =
                        cohort.anatomy.mounts()[neuron_index].place().layer() == 11
                            && permitted_vocal_ordering_work.contains(&lineage)
                            && !cohort.state.neurons()[neuron_index]
                                .receptor_quantum_residue
                                .energy()
                                .is_zero();
                    let (gate_work, receptor_successor_residue) = if retained_continuation_work {
                        let prepared =
                            crate::complete_neuron::prepare_intrinsic_transduced_gate_work(
                                neuron_anatomy,
                                &cohort.state.neurons()[neuron_index],
                                &prepared_psi,
                                BigRational::zero(),
                            )
                            .map_err(|error| {
                                FormationError::PhysicalSettlementUnavailable(
                                    ReachedCohortError::Neuron {
                                        neuron_index,
                                        error,
                                    },
                                )
                            })?;
                        if !prepared.accepted_source_work_zeptojoules.is_zero()
                            || !prepared.retained_source_heat_zeptojoules.is_zero()
                            || prepared.residue_narrowing_heat_zeptojoules < BigRational::zero()
                        {
                            return Err(FormationError::ArithmeticOverflow);
                        }
                        (prepared.gate_work, prepared.successor_residue_zeptojoules)
                    } else if let Some(offers) = learned_motor_work_offers.get(&lineage) {
                        let predecessor_neuron = cohort.state.neurons()[neuron_index].clone();
                        let predecessor_residue =
                            predecessor_neuron.receptor_quantum_residue.energy().clone();
                        let total_offered =
                            offers.iter().fold(BigRational::zero(), |sum, offer| {
                                sum + &offer.offered_work_zeptojoules
                            });
                        let mut prepared =
                            crate::complete_neuron::prepare_intrinsic_transduced_gate_work(
                                neuron_anatomy,
                                &predecessor_neuron,
                                &prepared_psi,
                                total_offered.clone(),
                            )
                            .map_err(|error| {
                                FormationError::PhysicalSettlementUnavailable(
                                    ReachedCohortError::Neuron {
                                        neuron_index,
                                        error,
                                    },
                                )
                            })?;
                        // A full closed gate must settle its already-existing recovery
                        // demand before this same bounded source occurrence is
                        // evaluated.  The prior ordering calculated refusal first,
                        // recovered the neuron second, and then retained the obsolete
                        // refusal without ever evaluating the recovered gate.
                        if predecessor_neuron.gate.open_population() == 0
                            && predecessor_neuron.gate.dissipated_quanta()
                                >= neuron_anatomy.gate_dissipation_capacity_quanta()
                        {
                            let recovery_gate_work = GateWorkOccurrence::new(
                                -(predecessor_residue.clone() + &total_offered),
                            );
                            let recovery_preparation = neuron_anatomy
                                .prepare_gate_interval_settlement(
                                    &predecessor_neuron,
                                    &recovery_gate_work,
                                    &prepared_psi,
                                )
                                .map_err(|error| {
                                    FormationError::PhysicalSettlementUnavailable(
                                        ReachedCohortError::Neuron {
                                            neuron_index,
                                            error,
                                        },
                                    )
                                })?;
                            let recovered_extent = settle_reached_gate_recovery_demand_in_place(
                                &cohort.anatomy,
                                Arc::make_mut(&mut cohort.state),
                                neuron_index,
                                &recovery_preparation,
                                &catalysts[reached_input_index],
                            )
                            .map_err(FormationError::PhysicalSettlementUnavailable)?;
                            if recovered_extent != 0 {
                                prepared =
                                    crate::complete_neuron::prepare_intrinsic_transduced_gate_work(
                                        neuron_anatomy,
                                        &cohort.state.neurons()[neuron_index],
                                        &prepared_psi,
                                        total_offered.clone(),
                                    )
                                    .map_err(|error| {
                                        FormationError::PhysicalSettlementUnavailable(
                                            ReachedCohortError::Neuron {
                                                neuron_index,
                                                error,
                                            },
                                        )
                                    })?;
                            }
                        }
                        let consumed_source_work = &prepared.accepted_source_work_zeptojoules
                            - &prepared.residue_narrowing_heat_zeptojoules;
                        if consumed_source_work < BigRational::zero()
                            || total_offered <= BigRational::zero()
                        {
                            return Err(FormationError::ArithmeticOverflow);
                        }
                        #[cfg(test)]
                        if prepared.accepted_source_work_zeptojoules > BigRational::zero()
                            && cohort.anatomy.mounts()[neuron_index]
                                .body_effector_terminal()
                                .is_some_and(|terminal| terminal.axis().is_vocal_articulator())
                        {
                            VOCAL_WORK_ACCEPTANCES
                                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                        }
                        if !consumed_source_work.is_zero() {
                            for offer in offers {
                                cohort_learned_source_debits.push(LearnedSourceWorkDebit {
                                    source_transition_position: offer.source_transition_position,
                                    consumed_work_zeptojoules: &consumed_source_work
                                        * &offer.offered_work_zeptojoules
                                        / &total_offered,
                                    offered_work_zeptojoules: offer
                                        .offered_work_zeptojoules
                                        .clone(),
                                    reserved_before_source_plasticity: offer
                                        .reserved_before_source_plasticity,
                                });
                            }
                        }
                        let successor_residue = prepared
                            .successor_residue_zeptojoules
                            .clone()
                            .unwrap_or_else(|| predecessor_residue.clone());
                        cohort_learned_work_preparations.push(LearnedMotorWorkPreparation {
                            motor_lineage: lineage,
                            routes: offers
                                .iter()
                                .map(|offer| LearnedMotorWorkRoute {
                                    ordering_lineage: offer.ordering_lineage,
                                    founding_receiver_lineage: offer.founding_receiver_lineage,
                                    founding_bond: offer.founding_bond,
                                    learned_bond: offer.learned_bond,
                                    offered_work_zeptojoules: offer
                                        .offered_work_zeptojoules
                                        .clone(),
                                })
                                .collect(),
                            total_offered_work_zeptojoules: total_offered,
                            accepted_work_zeptojoules: prepared
                                .accepted_source_work_zeptojoules
                                .clone(),
                            predecessor_residue_zeptojoules: predecessor_residue,
                            successor_residue_zeptojoules: successor_residue,
                            delivered_gate_work_zeptojoules: prepared
                                .delivered_gate_work_zeptojoules
                                .clone(),
                            retained_source_heat_zeptojoules: prepared
                                .retained_source_heat_zeptojoules
                                .clone(),
                            residue_narrowing_heat_zeptojoules: prepared
                                .residue_narrowing_heat_zeptojoules
                                .clone(),
                        });
                        (prepared.gate_work, prepared.successor_residue_zeptojoules)
                    } else if cohort.anatomy.mounts()[neuron_index].place().layer() == 10
                        && gradient_changed
                        && convergent_activity.is_some()
                    {
                        let predecessor_neuron = &cohort.state.neurons()[neuron_index];
                        let incident_catalyst_quanta =
                            convergent_activity.ok_or(FormationError::ArithmeticOverflow)?;
                        let energetic = settle_contact_modulated_gate_energy(
                            &cohort.anatomy,
                            &cohort.state,
                            neuron_index,
                            incident_catalyst_quanta,
                        )
                        .map_err(FormationError::PhysicalSettlementUnavailable)?;
                        let window = gate_opening_quantum_window_with_psi(
                            &cohort.anatomy.neuron_anatomies()[neuron_index],
                            predecessor_neuron,
                            &prepared_psi,
                        )
                        .map_err(|error| {
                            FormationError::PhysicalSettlementUnavailable(
                                ReachedCohortError::Neuron {
                                    neuron_index,
                                    error,
                                },
                            )
                        })?;
                        let delivery = quantize_receptor_delivery(
                            &exact_rational_to_big(energetic.delivered_energy_zeptojoules),
                            &predecessor_neuron.receptor_quantum_residue,
                            cohort.anatomy.neuron_anatomies()[neuron_index]
                                .gate_dissipation_quantum_zeptojoules(),
                            window.opening_threshold_quanta,
                            window.window_cap_quanta,
                        )
                        .map_err(FormationError::LocalGateWorkUnavailable)?;
                        pending_layer_ten_plasticity.push(PendingLayerTenPlasticitySettlement {
                            neuron_lineage: lineage,
                            cognitive_ordinal,
                            incident_catalyst_quanta: energetic.incident_catalyst_quanta,
                            reaction_extent: energetic.reaction_extent,
                            delivered_energy_zeptojoules: energetic.delivered_energy_zeptojoules,
                            predecessor_gate_work_residue_zeptojoules: predecessor_neuron
                                .receptor_quantum_residue
                                .energy()
                                .clone(),
                            successor_gate_work_residue_zeptojoules: delivery
                                .successor_residue
                                .clone(),
                            predecessor_plastic_rest_length_nanometres: predecessor_neuron
                                .plastic
                                .rest_length_nanometres(),
                            predecessor_reservoir: energetic.predecessor_reservoir,
                            successor_reservoir: energetic.successor_reservoir,
                        });
                        cohort.state = energetic.successor.into();
                        (delivery.gate_work, Some(delivery.successor_residue))
                    } else {
                        (GateWorkOccurrence::new(BigRational::zero()), None)
                    };
                    inputs.push(NeuronIntervalInput {
                        perspective,
                        gate_work,
                        interval_microseconds,
                        recovery: RecoveryContact::new(&catalysts[reached_input_index], 0, 0),
                        dna_expression: DnaExpressionContact::new(0),
                        receptor_successor_residue,
                        prepared_psi: Some(prepared_psi),
                    });
                }
                let (local_successors, local_transitions) = local_contact_result;
                let local_successor = SparseElectricalState::from_contact_states(
                    cohort.anatomy.electrical_anatomy(),
                    local_successors,
                )
                .map_err(FormationError::ResidentElectricalUnavailable)?;
                let precomputed_local = SparseElectricalTransferSettlement {
                    successor_contacts: local_successor,
                    transitions: local_transitions.into_boxed_slice(),
                    // The one coupled fabric solve already supplied the reached-only
                    // `combined_outward` values below.  A second cohort-width outward
                    // vector was redundant and is deliberately absent.
                    outward_elementary_charges_by_neuron: Box::new([]),
                };
                let input =
                    ReachedCohortIntervalInput::from_resident_indices_with_precomputed_contacts(
                        inputs,
                        resident_indices,
                        combined_outward,
                        precomputed_local,
                    )
                    .map_err(FormationError::PhysicalSettlementUnavailable)?;
                // This interval is a native cross-cohort electrical consequence, not
                // a second externally admitted experience. Its retained changes join
                // the same pending local physical experience and may emit only after
                // a later exact neuron-local quiescent interval. Cross-cohort current
                // therefore cannot bypass the post-quiescence fractal law.
                let settlement = settle_reached_cohort_interval_precomputed_in_place(
                    &cohort.anatomy,
                    Arc::make_mut(&mut cohort.state),
                    input,
                )
                .map_err(FormationError::PhysicalSettlementUnavailable)?;
                // A mounted motor terminal is a second, neuron-local physical path.
                // Incoming contact carriers only prepare it by leaving retained
                // membrane displacement; they are never relabelled as the action.
                // When the ordinary gate path did not already discharge, the terminal
                // moves at most the exact preparing carriers back toward zero and
                // deposits the released local work into this cohort's thermal store.
                let mut prepared_terminal_discharges = BTreeMap::<usize, i128>::new();
                for (_, neuron_index) in selected_members.iter().copied() {
                    let mount = &cohort.anatomy.mounts()[neuron_index];
                    if mount.source_site().is_some() || mount.place().layer() != 12 {
                        continue;
                    }
                    let motor_lineage = cohort.anatomy.neuron_lineages()[neuron_index];
                    let preparation_transfers = if mount.root_yaw_effector_terminal().is_some() {
                        exact_root_yaw_motor_preparation_transfers(
                            motor_lineage,
                            &settled_directed_transfers,
                            root_yaw_regulations_by_motor
                                .get(&motor_lineage)
                                .map(Vec::as_slice)
                                .unwrap_or(&[]),
                            &causal_seed_lineages,
                            &layer_of,
                        )
                    } else if mount.root_translation_effector_terminal().is_some() {
                        exact_root_translation_motor_preparation_transfers(
                            motor_lineage,
                            &settled_directed_transfers,
                            &layer_of,
                        )
                    } else if mount.body_effector_terminal().is_some() {
                        let permitted_vocal_orderings = mount
                            .body_effector_terminal()
                            .is_some_and(|terminal| terminal.axis().is_vocal_articulator())
                            .then_some(&permitted_vocal_ordering_work);
                        let permitted_vocal_bonds = mount
                            .body_effector_terminal()
                            .is_some_and(|terminal| terminal.axis().is_vocal_articulator())
                            .then_some(&permitted_vocal_motor_bonds);
                        exact_motor_preparation_transfers(
                            motor_lineage,
                            &settled_directed_transfers,
                            body_regulations_by_motor
                                .get(&motor_lineage)
                                .map(Vec::as_slice)
                                .unwrap_or(&[]),
                            &fresh_seed_lineages,
                            permitted_vocal_orderings,
                            permitted_vocal_bonds,
                            &layer_of,
                        )
                    } else {
                        continue;
                    };
                    let prepared_carriers =
                        preparation_transfers
                            .iter()
                            .try_fold(0_u128, |total, transfer| {
                                total
                                    .checked_add(transfer.transferred_whole_carriers)
                                    .ok_or(FormationError::ArithmeticOverflow)
                            })?;
                    let retained_positive_displacement = cohort.state.neurons()[neuron_index]
                        .separated_elementary_charges()
                        .max(0)
                        .unsigned_abs();
                    // A root-yaw motor may integrate its causal preparation over
                    // earlier intervals. Its retained positive displacement is that
                    // physical memory and may discharge without demanding that the
                    // incoming contact cross again in this same interval. Translation
                    // deliberately does not: returned position feedback must never
                    // repeat the movement without a fresh layer-11 preparation.
                    let discharge_limit = if mount.root_yaw_effector_terminal().is_some() {
                        prepared_carriers.max(retained_positive_displacement)
                    } else {
                        prepared_carriers
                    };
                    if settlement
                        .local_outward_elementary_charges
                        .binary_search_by_key(&neuron_index, |(resident_index, _)| *resident_index)
                        .ok()
                        .is_some_and(|index| {
                            settlement.local_outward_elementary_charges[index].1 > 0
                        })
                    {
                        continue;
                    }
                    let terminal_transport =
                        crate::complete_neuron::settle_efferent_terminal_transport(
                            &cohort.anatomy.neuron_anatomies()[neuron_index],
                            &cohort.state.neurons()[neuron_index],
                            discharge_limit,
                            interval_microseconds,
                        )
                        .map_err(|error| {
                            FormationError::PhysicalSettlementUnavailable(
                                ReachedCohortError::Neuron {
                                    neuron_index,
                                    error,
                                },
                            )
                        })?;
                    let Some((successor_neuron, outward_carriers, released_work)) =
                        terminal_transport
                    else {
                        continue;
                    };
                    let released_exact = ExactRational::new(
                        i128::try_from(released_work.numer().clone())
                            .map_err(|_| FormationError::ArithmeticOverflow)?,
                        u128::try_from(released_work.denom().clone())
                            .map_err(|_| FormationError::ArithmeticOverflow)?,
                    )
                    .map_err(|_| FormationError::ArithmeticOverflow)?;
                    let Some(successor_reservoir) =
                        crate::metabolic_feeding::deposit_passive_return_work(
                            cohort.anatomy.recovery_fluid_reservoir_anatomy(),
                            cohort.state.recovery_fluid(),
                            released_exact,
                        )
                        .map_err(|_| FormationError::ArithmeticOverflow)?
                    else {
                        continue;
                    };
                    Arc::make_mut(&mut cohort.state)
                        .apply_local_membrane_transport(
                            neuron_index,
                            successor_neuron,
                            successor_reservoir,
                        )
                        .map_err(FormationError::PhysicalSettlementUnavailable)?;
                    prepared_terminal_discharges.insert(
                        neuron_index,
                        i128::try_from(outward_carriers)
                            .map_err(|_| FormationError::ArithmeticOverflow)?,
                    );
                }
                // Preparation arrived through an inter-neuron contact before this
                // neuron-local interval.  The efferent event is the exact positive
                // whole-carrier discharge through the neuron's own membrane path,
                // which the reached settlement now carries separately.  This avoids
                // the former contradiction where an incoming preparation had to be
                // simultaneously counted as outward contact flow from the motor.
                let local_outward_for = |neuron_index: usize| {
                    if let Some(outward) = prepared_terminal_discharges.get(&neuron_index) {
                        return *outward;
                    }
                    settlement
                        .local_outward_elementary_charges
                        .binary_search_by_key(&neuron_index, |(resident_index, _)| *resident_index)
                        .ok()
                        .map(|index| settlement.local_outward_elementary_charges[index].1)
                        .unwrap_or(0)
                };
                let motor_unit_recruitments = selected_members
                    .iter()
                    .filter_map(|(_, neuron_index)| {
                        let mount = &cohort.anatomy.mounts()[*neuron_index];
                        let body_effector_terminal = mount.body_effector_terminal()?;
                        let motor_lineage = cohort.anatomy.neuron_lineages()[*neuron_index];
                        let permitted_vocal_orderings = body_effector_terminal
                            .axis()
                            .is_vocal_articulator()
                            .then_some(&permitted_vocal_ordering_work);
                        let permitted_vocal_bonds = body_effector_terminal
                            .axis()
                            .is_vocal_articulator()
                            .then_some(&permitted_vocal_motor_bonds);
                        let preparation_transfers = exact_motor_preparation_transfers(
                            motor_lineage,
                            &settled_directed_transfers,
                            body_regulations_by_motor
                                .get(&motor_lineage)
                                .map(Vec::as_slice)
                                .unwrap_or(&[]),
                            &fresh_seed_lineages,
                            permitted_vocal_orderings,
                            permitted_vocal_bonds,
                            &layer_of,
                        )
                        .into_iter()
                        .map(|transfer| {
                            Some(MotorPreparationTransfer {
                                sender_layer: layer_of(transfer.sender)?,
                                transfer,
                            })
                        })
                        .collect::<Option<Vec<_>>>()?;
                        let learned_work_preparations = cohort_learned_work_preparations
                            .iter()
                            .filter(|preparation| {
                                preparation.motor_lineage == motor_lineage
                                    && preparation.accepted_work_zeptojoules > BigRational::zero()
                            })
                            .cloned()
                            .collect::<Vec<_>>();
                        let outward_elementary_carriers = exact_prepared_efferent_carriers(
                            local_outward_for(*neuron_index),
                            preparation_transfers
                                .len()
                                .checked_add(learned_work_preparations.len())?,
                        )?;
                        (mount.source_site().is_none() && mount.place().layer() == 12).then_some(
                            MotorUnitRecruitment {
                                neuron_lineage: motor_lineage,
                                topology_index: mount.place().topology_index(),
                                outward_elementary_carriers,
                                body_effector_terminal,
                                body_afferent_paths: Vec::new(),
                                preparation_transfers,
                                learned_work_preparations,
                            },
                        )
                    })
                    .collect::<Vec<_>>();
                let root_yaw_unit_recruitments = selected_members
                    .iter()
                    .filter_map(|(_, neuron_index)| {
                        let mount = &cohort.anatomy.mounts()[*neuron_index];
                        let terminal = mount.root_yaw_effector_terminal()?;
                        let motor_lineage = cohort.anatomy.neuron_lineages()[*neuron_index];
                        let preparation_transfers = exact_root_yaw_motor_preparation_transfers(
                            motor_lineage,
                            &settled_directed_transfers,
                            root_yaw_regulations_by_motor
                                .get(&motor_lineage)
                                .map(Vec::as_slice)
                                .unwrap_or(&[]),
                            &causal_seed_lineages,
                            &layer_of,
                        );
                        let outward_elementary_carriers = prepared_terminal_discharges
                            .get(neuron_index)
                            .map(|outward| outward.unsigned_abs())
                            .or_else(|| {
                                exact_prepared_efferent_carriers(
                                    local_outward_for(*neuron_index),
                                    preparation_transfers.len(),
                                )
                            })?;
                        (mount.source_site().is_none() && mount.place().layer() == 12).then_some(
                            RootYawUnitRecruitment {
                                neuron_lineage: motor_lineage,
                                topology_index: mount.place().topology_index(),
                                outward_elementary_carriers,
                                terminal,
                                preparation_transfers,
                            },
                        )
                    })
                    .collect::<Vec<_>>();
                let root_translation_unit_recruitments = selected_members
                    .iter()
                    .filter_map(|(_, neuron_index)| {
                        let mount = &cohort.anatomy.mounts()[*neuron_index];
                        let terminal = mount.root_translation_effector_terminal()?;
                        let motor_lineage = cohort.anatomy.neuron_lineages()[*neuron_index];
                        let preparation_transfers =
                            exact_root_translation_motor_preparation_transfers(
                                motor_lineage,
                                &settled_directed_transfers,
                                &layer_of,
                            );
                        let outward_elementary_carriers = prepared_terminal_discharges
                            .get(neuron_index)
                            .map(|outward| outward.unsigned_abs())
                            .or_else(|| {
                                exact_prepared_efferent_carriers(
                                    local_outward_for(*neuron_index),
                                    preparation_transfers.len(),
                                )
                            })?;
                        (mount.source_site().is_none() && mount.place().layer() == 12).then_some(
                            RootTranslationUnitRecruitment {
                                neuron_lineage: motor_lineage,
                                topology_index: mount.place().topology_index(),
                                outward_elementary_carriers,
                                terminal,
                                preparation_transfers,
                            },
                        )
                    })
                    .collect::<Vec<_>>();
                let articulatory_unit_recruitments = Vec::<ArticulatoryUnitRecruitment>::new();
                let mut retained_interval_deltas = Vec::new();
                for predecessor in &comparison_predecessors {
                    let neuron_index = predecessor.neuron_index();
                    if let Some(delta) = sparse_retained_physical_state_delta(
                        predecessor.state(),
                        &cohort.state.neurons()[neuron_index],
                    )
                    .map_err(|error| {
                        FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                            neuron_index,
                            error,
                        })
                    })? {
                        retained_interval_deltas.push((neuron_index, delta));
                    }
                }
                let retained_change_this_interval = SparseResidentNeuronMask::from_indices(
                    retained_interval_deltas
                        .iter()
                        .map(|(neuron_index, _)| *neuron_index)
                        .collect(),
                    cohort.anatomy.neuron_count(),
                )?;
                let active_electrical_contacts =
                    active_contact_bits(&settlement.contact_transitions);
                let mut cohort_fractals = Vec::new();
                if cohort.retained_experience.is_none() {
                    let experience_preceded_interval = cohort.pending_experience.is_some();
                    let mut experience = cohort.pending_experience.take();
                    if experience.is_none() && !retained_change_this_interval.is_empty() {
                        experience = Some(ResidentExperienceEvidence {
                            codec: ExperienceEvidenceCodec::V8,
                            physical: ResidentExperiencePhysicalEvidence::Pending(Box::new([])),
                            gate_work_perturbed_neurons: SparseResidentNeuronMask::empty(),
                            receptor_excitation_zeptojoules: SparseResidentExcitations::empty(),
                            active_electrical_contacts: SparseResidentNeuronMask::empty(),
                            local_relaxation_observed: false,
                        });
                    }
                    if let Some(evidence) = experience.as_mut() {
                        evidence.codec = ExperienceEvidenceCodec::V8;
                        merge_pending_experience_members(evidence, &retained_interval_deltas)?;
                        evidence.active_electrical_contacts.union_sparse(
                            &active_electrical_contacts,
                            cohort.anatomy.contact_count(),
                        )?;
                        if experience_preceded_interval {
                            cohort_fractals.extend(emit_newly_quiescent_neuron_fractals(
                                &cohort.anatomy,
                                evidence,
                                &retained_change_this_interval,
                            )?);
                        }
                    }
                    cohort.pending_experience = experience;
                } else {
                    let no_gate_work = SparseResidentNeuronMask::empty();
                    let no_receptor_excitation = SparseResidentExcitations::empty();
                    cohort_fractals.extend(advance_recurrent_neuronal_experience(
                        &cohort.anatomy,
                        &mut cohort.pending_experience,
                        &retained_interval_deltas,
                        &retained_change_this_interval,
                        &no_gate_work,
                        &no_receptor_excitation,
                        &active_electrical_contacts,
                    )?);
                }
                let mut changed_predecessors = Vec::new();
                for predecessor in comparison_predecessors {
                    let neuron_index = predecessor.neuron_index();
                    let successor = &cohort.state.neurons()[neuron_index];
                    if predecessor.state() != successor {
                        changed_predecessors.push(predecessor.retained(
                            cohort.anatomy.neuron_lineages()[neuron_index],
                            &cohort.anatomy.neuron_anatomies()[neuron_index],
                        ));
                    }
                }
                Ok(Some((
                    changed_predecessors,
                    motor_unit_recruitments,
                    root_yaw_unit_recruitments,
                    root_translation_unit_recruitments,
                    articulatory_unit_recruitments,
                    cohort_fractals,
                    pending_layer_ten_plasticity,
                    cohort_learned_work_preparations,
                    cohort_learned_source_debits,
                )))
            },
        )
        .collect::<Vec<_>>();
    let mut motor_unit_recruitments = Vec::new();
    let mut root_yaw_unit_recruitments = Vec::new();
    let mut root_translation_unit_recruitments = Vec::new();
    let mut articulatory_unit_recruitments = Vec::new();
    let mut emitted_neuron_fractals = Vec::new();
    let mut layer_ten_plasticity_settlements = Vec::new();
    let mut learned_motor_work_preparations = Vec::new();
    let mut learned_source_work_debits = Vec::new();
    for result in cohort_results {
        if let Some((
            changed_predecessors,
            cohort_motor_recruitments,
            cohort_root_yaw_recruitments,
            cohort_root_translation_recruitments,
            cohort_articulatory_recruitments,
            cohort_fractals,
            cohort_layer_ten_plasticity,
            cohort_learned_work_preparations,
            cohort_learned_source_debits,
        )) = result?
        {
            for predecessor in changed_predecessors {
                let lineage = predecessor.lineage;
                physically_transitioned_neuron_lineages.insert(lineage);
                retain_first_transition_predecessor(&mut transition_predecessors, predecessor);
            }
            motor_unit_recruitments.extend(cohort_motor_recruitments);
            root_yaw_unit_recruitments.extend(cohort_root_yaw_recruitments);
            root_translation_unit_recruitments.extend(cohort_root_translation_recruitments);
            articulatory_unit_recruitments.extend(cohort_articulatory_recruitments);
            emitted_neuron_fractals.extend(cohort_fractals);
            layer_ten_plasticity_settlements.extend(cohort_layer_ten_plasticity);
            learned_motor_work_preparations.extend(cohort_learned_work_preparations);
            learned_source_work_debits.extend(cohort_learned_source_debits);
        }
    }
    learned_source_work_debits.sort_by_key(|debit| debit.source_transition_position);
    for debit in learned_source_work_debits {
        let transition = settled
            .transitions
            .get_mut(debit.source_transition_position)
            .ok_or(FormationError::NoncanonicalState)?;
        if debit.consumed_work_zeptojoules < BigRational::zero()
            || debit.consumed_work_zeptojoules > debit.offered_work_zeptojoules
        {
            return Err(FormationError::ArithmeticOverflow);
        }
        if debit.reserved_before_source_plasticity {
            transition.exported_heat_zeptojoules +=
                debit.offered_work_zeptojoules - debit.consumed_work_zeptojoules;
        } else {
            if debit.consumed_work_zeptojoules > transition.exported_heat_zeptojoules {
                return Err(FormationError::ArithmeticOverflow);
            }
            transition.exported_heat_zeptojoules -= debit.consumed_work_zeptojoules;
        }
    }
    // Learned work is prepared on the compact contact cohort that owns its
    // source route, while the resulting efferent event is emitted by the
    // cohort that owns the motor. Join those already-settled facts only after
    // all cohort results are aggregated. Matching by the unique motor lineage
    // preserves the exact same-interval causal identity and creates no work,
    // carrier transfer, contact, or action.
    for recruitment in &mut motor_unit_recruitments {
        let mut exact_learned_preparations = learned_motor_work_preparations
            .iter()
            .filter(|preparation| {
                preparation.motor_lineage == recruitment.neuron_lineage
                    && preparation.accepted_work_zeptojoules > BigRational::zero()
            })
            .cloned()
            .collect::<Vec<_>>();
        exact_learned_preparations.sort_by_key(|preparation| preparation.motor_lineage);
        exact_learned_preparations.dedup();
        recruitment.learned_work_preparations = exact_learned_preparations;
    }
    if !motor_unit_recruitments.is_empty() {
        for recruitment in &mut motor_unit_recruitments {
            let motor_flat = lineage_member(recruitment.neuron_lineage)?;
            let paths = exact_motor_body_afferent_paths(
                motor_flat,
                flat_locations,
                cohorts,
                &topology_index.neighbours_by_flat,
            )?;
            if paths.is_empty() {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            }
            recruitment.body_afferent_paths = paths;
        }
    }
    // A complete coordinated vocal motor discharge co-recruits the one resident
    // respiratory effector. The respiratory cell remains electrically
    // isolated: the rejected layer-12/layer-13 convergence hub and passive
    // layer-11/layer-13 bridge do not return. Authority is the exact physical
    // sequence already settled in this interval: current external cause (or
    // one exact preceding L11/L11 continuation) reaches the coordinated
    // ordering, every exact L11/L12 learned branch transfers positive whole
    // carriers, and every typed vocal L12 motor emits its own positive
    // whole-carrier discharge. A
    // partial posture and a layer-8 reflex—including the born swallowing
    // closure—cannot satisfy this boundary.
    //
    // The control occurrence does not become respiratory energy. It limits
    // how much of the layer-13 cell's own retained membrane-gradient work may
    // leave through its efferent terminal. Thus cognition selects the act,
    // while the respiratory body supplies and pays for the work.
    let mut co_recruited_articulatory_flats = Vec::new();
    let mut candidate_vocal_orderings = motor_unit_recruitments
        .iter()
        .filter(|recruitment| {
            recruitment
                .body_effector_terminal
                .axis()
                .is_vocal_articulator()
        })
        .flat_map(|recruitment| recruitment.preparation_transfers.iter())
        .filter(|arrival| arrival.sender_layer == 11)
        .map(|arrival| arrival.transfer.sender)
        .collect::<Vec<_>>();
    candidate_vocal_orderings.sort_unstable();
    candidate_vocal_orderings.dedup();
    let mut completed_vocal_orderings = Vec::new();
    let mut completed_vocal_motors = BTreeSet::new();
    let mut completed_vocal_preparation_transfers = Vec::new();
    for ordering in candidate_vocal_orderings {
        let Some(preparation) =
            vocal_action_preparation_for_ordering(cohorts, topology_index, ordering)?
        else {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        };
        if let Some((exact_motors, exact_transfers)) = exact_completed_vocal_preparation_body_act(
            cohorts,
            topology_index,
            &preparation,
            &motor_unit_recruitments,
            predecessor_frontier,
            moved_body_effectors,
        )? {
            completed_vocal_orderings.push(ordering);
            completed_vocal_motors.extend(exact_motors);
            completed_vocal_preparation_transfers.extend(exact_transfers);
        }
    }
    completed_vocal_orderings.sort_unstable();
    completed_vocal_orderings.dedup();
    if completed_vocal_orderings.len() > 1 {
        // More than one complete preparation would make sequence authorship
        // ambiguous. Refuse the physical tie; never select by iteration order
        // or merge distinct preparations into one vocal act.
        return Err(FormationError::NeuronLineageAuthorityChanged);
    }
    let mut directed_continuation_work_frontiers = Vec::new();
    // Returning body-owned pressure must never found a fresh learned act, but
    // it can arrive on the same clock that the already externally caused act
    // completes. Completion is independently proved above by that act's exact
    // learned motor transfers and returned typed body motion. Do not let the
    // acoustic-efference authorship guard erase the completed act's own
    // conserved work transfer into its unique learned successor.
    for source in completed_vocal_orderings.iter().copied() {
        let continuation_routes = vocal_cognitive_action_continuation_routes_from_source(
            cohorts,
            topology_index,
            source,
        )?;
        let continuation = match continuation_routes.as_slice() {
            [] => continue,
            [route] => route,
            _ => {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            }
        };
        let destination_preparation = vocal_action_preparation_for_ordering(
            cohorts,
            topology_index,
            continuation.destination_ordering_lineage,
        )?
        .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
        if preparation_predecessors(cohorts, topology_index, &destination_preparation)? != [source]
        {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        }
        let source_preparation =
            vocal_action_preparation_for_ordering(cohorts, topology_index, source)?
                .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
        let continuation_position = compact_bonds
            .iter()
            .position(|bond| *bond == continuation.continuation_bond);
        let continuation_conductance = if let Some(position) = continuation_position {
            compact_anatomy.contact_anatomies()[position]
                .effective_conductance(&compact_predecessor.contact_states()[position])
                .map_err(FormationError::ResidentElectricalUnavailable)?
        } else {
            let entry = topology_index
                .contacts
                .iter()
                .find(|entry| entry.stable_bond == continuation.continuation_bond)
                .ok_or(FormationError::NeuronLineageAuthorityAbsent)?;
            let edge = materialize_resident_contact_edge(*entry, cohorts, electrical_fabric)?;
            edge.anatomy
                .effective_conductance(&edge.state)
                .map_err(FormationError::ResidentElectricalUnavailable)?
        };
        if continuation_conductance.parts().0 <= 0 {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        }
        let continuation_conductance = exact_to_wide(continuation_conductance);
        let mut offers = Vec::<(usize, BigRational)>::new();
        for motor in &source_preparation.motors {
            let Some(position) = compact_bonds.iter().position(|bond| *bond == motor.bond) else {
                continue;
            };
            let (left_flat, right_flat) = compact_edge_flat_endpoints[position];
            let Some(transfer) = directed_physical_transfer(
                settled.transitions[position].outward_elementary_charges_from_left,
                flat_locations[left_flat].2,
                flat_locations[right_flat].2,
                motor.bond,
            ) else {
                continue;
            };
            if transfer.sender != source || transfer.receiver != motor.lineage {
                continue;
            }
            let available_work = settled.transitions[position]
                .exported_heat_zeptojoules
                .clone();
            if available_work <= BigRational::zero() {
                continue;
            }
            let source_conductance = exact_to_wide(
                compact_anatomy.contact_anatomies()[position]
                    .effective_conductance(&compact_predecessor.contact_states()[position])
                    .map_err(FormationError::ResidentElectricalUnavailable)?,
            );
            let denominator = &source_conductance + &continuation_conductance;
            if source_conductance <= BigRational::zero() || denominator <= BigRational::zero() {
                return Err(FormationError::ArithmeticOverflow);
            }
            let offered = available_work * &continuation_conductance / denominator;
            if offered > BigRational::zero() {
                offers.push((position, offered));
            }
        }
        let total_offered = offers
            .iter()
            .fold(BigRational::zero(), |sum, (_, work)| sum + work);
        if total_offered <= BigRational::zero() {
            continue;
        }
        let destination_flat = lineage_member(continuation.destination_ordering_lineage)?;
        let (cohort_index, neuron_index, lineage) = flat_locations[destination_flat];
        let predecessor = cohorts[cohort_index].state.neurons()[neuron_index].clone();
        let retained = crate::complete_neuron::retain_deferred_receptor_work(
            &predecessor,
            total_offered.clone(),
        )
        .map_err(|error| {
            FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                neuron_index,
                error,
            })
        })?;
        let accepted = retained.accepted_source_work_zeptojoules.clone();
        if accepted <= BigRational::zero() {
            continue;
        }
        if retained.retained_source_heat_zeptojoules != BigRational::zero()
            || retained.residue_narrowing_heat_zeptojoules < BigRational::zero()
            || accepted > total_offered
        {
            return Err(FormationError::ArithmeticOverflow);
        }
        for (position, offered) in offers {
            let debit = &accepted * offered / &total_offered;
            if debit < BigRational::zero()
                || debit > settled.transitions[position].exported_heat_zeptojoules
            {
                return Err(FormationError::ArithmeticOverflow);
            }
            settled.transitions[position].exported_heat_zeptojoules -= debit;
        }
        Arc::make_mut(&mut cohorts[cohort_index].state)
            .replace_neuron_state(neuron_index, retained.successor)
            .map_err(FormationError::PhysicalSettlementUnavailable)?;
        retain_first_transition_predecessor(
            &mut transition_predecessors,
            TransitionNeuronPredecessor {
                lineage,
                anatomy: cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index].clone(),
                state: predecessor,
            },
        );
        physically_transitioned_neuron_lineages.insert(lineage);
        causally_active_lineages.insert(lineage);
        directed_continuation_work_frontiers.push(ActiveElectricalFrontierEntry::causal_in_flight(
            source,
            continuation.destination_ordering_lineage,
            continuation.destination_ordering_lineage,
            continuation.continuation_bond,
        )?);
    }
    completed_vocal_preparation_transfers.sort_unstable();
    completed_vocal_preparation_transfers.dedup();
    if !completed_vocal_preparation_transfers.is_empty() {
        let discharge_limit = motor_unit_recruitments
            .iter()
            .filter(|event| {
                event.body_effector_terminal.axis().is_vocal_articulator()
                    && completed_vocal_motors.contains(&event.neuron_lineage)
            })
            .try_fold(0_u128, |total, event| {
                total
                    .checked_add(event.outward_elementary_carriers)
                    .ok_or(FormationError::ArithmeticOverflow)
            })?;
        let Some(articulatory_flat) = vocal_articulatory_effector_flat else {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        };
        let (cohort_index, neuron_index, articulatory_lineage) = flat_locations[articulatory_flat];
        let predecessor = TransitionNeuronPredecessor {
            lineage: articulatory_lineage,
            anatomy: cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index].clone(),
            state: cohorts[cohort_index].state.neurons()[neuron_index].clone(),
        };
        let coupled_articulatory_transport =
            |carrier_limit| {
                let transport = crate::complete_neuron::settle_efferent_terminal_transport(
                    &cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index],
                    &cohorts[cohort_index].state.neurons()[neuron_index],
                    carrier_limit,
                    interval_microseconds,
                )
                .map_err(|error| {
                    FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                        neuron_index,
                        error,
                    })
                })?;
                let Some((successor_neuron, outward_carriers, released_work)) = transport else {
                    return Ok(None);
                };
                let released_exact = ExactRational::new(
                    i128::try_from(released_work.numer().clone())
                        .map_err(|_| FormationError::ArithmeticOverflow)?,
                    u128::try_from(released_work.denom().clone())
                        .map_err(|_| FormationError::ArithmeticOverflow)?,
                )
                .map_err(|_| FormationError::ArithmeticOverflow)?;
                let successor_reservoir = crate::metabolic_feeding::deposit_passive_return_work(
                    cohorts[cohort_index]
                        .anatomy
                        .recovery_fluid_reservoir_anatomy(),
                    cohorts[cohort_index].state.recovery_fluid(),
                    released_exact,
                )
                .map_err(|_| FormationError::ArithmeticOverflow)?;
                Ok(successor_reservoir
                    .map(|reservoir| (successor_neuron, outward_carriers, reservoir)))
            };
        // Terminal release and reservoir heat acceptance are one coupled
        // physical settlement. If the requested whole-carrier discharge is
        // wider than the current thermal headroom, settle the largest exact
        // whole-carrier prefix that both boundaries accept instead of
        // discarding every otherwise-valid breath carrier. Monotonicity comes
        // from the unchanged terminal work law and fixed reservoir capacity;
        // binary search is bounded by the u128 carrier width.
        let mut refused_ceiling = discharge_limit;
        let mut accepted_floor = 0_u128;
        let mut accepted_transport = None;
        while accepted_floor < refused_ceiling {
            let span = refused_ceiling - accepted_floor;
            let candidate_limit = accepted_floor + span / 2 + span % 2;
            match coupled_articulatory_transport(candidate_limit)? {
                Some(transport) => {
                    accepted_floor = candidate_limit;
                    accepted_transport = Some(transport);
                }
                None => refused_ceiling = candidate_limit - 1,
            }
        }
        if let Some((successor_neuron, outward_carriers, successor_reservoir)) = accepted_transport
        {
            Arc::make_mut(&mut cohorts[cohort_index].state)
                .apply_local_membrane_transport(neuron_index, successor_neuron, successor_reservoir)
                .map_err(FormationError::PhysicalSettlementUnavailable)?;
            physically_transitioned_neuron_lineages.insert(articulatory_lineage);
            retain_first_transition_predecessor(&mut transition_predecessors, predecessor);
            co_recruited_articulatory_flats.push(articulatory_flat);
            articulatory_unit_recruitments.push(ArticulatoryUnitRecruitment {
                neuron_lineage: articulatory_lineage,
                topology_index: cohorts[cohort_index].anatomy.mounts()[neuron_index]
                    .place()
                    .topology_index(),
                outward_elementary_carriers: outward_carriers,
                preparation_transfers: completed_vocal_preparation_transfers,
                learned_work_preparations: Vec::new(),
            });
        }
    }
    let mut affective_balance_trajectories = Vec::new();
    for gradient in reached_layer_ten_gradient_settlements {
        let gradient_flat = topology_index.flat_for_lineage(gradient.neuron_lineage)?;
        let (gradient_cohort_index, gradient_neuron_index, _) = flat_locations[gradient_flat];
        let interval_successor_separated_elementary_charges =
            cohorts[gradient_cohort_index].state.neurons()[gradient_neuron_index]
                .separated_elementary_charges();
        let mut association_influences = Vec::new();
        let mut body_influences = Vec::new();
        for ((transition, bond), (left_flat, right_flat)) in settled
            .transitions
            .iter()
            .zip(compact_bonds.iter().copied())
            .zip(compact_edge_flat_endpoints.iter().copied())
        {
            let signed = transition.outward_elementary_charges_from_left;
            if signed == 0 {
                continue;
            }
            let (sender_flat, receiver_flat) = if signed > 0 {
                (left_flat, right_flat)
            } else {
                (right_flat, left_flat)
            };
            let (sender_cohort, sender_neuron, sender) = flat_locations[sender_flat];
            let (receiver_cohort, receiver_neuron, receiver) = flat_locations[receiver_flat];
            if sender != gradient.neuron_lineage && receiver != gradient.neuron_lineage {
                continue;
            }
            let adjacent_layer = if sender == gradient.neuron_lineage {
                cohorts[receiver_cohort].anatomy.mounts()[receiver_neuron]
                    .place()
                    .layer()
            } else {
                cohorts[sender_cohort].anatomy.mounts()[sender_neuron]
                    .place()
                    .layer()
            };
            let timed = TimedDirectedPhysicalTransferObservation {
                cognitive_ordinal,
                transfer: DirectedPhysicalTransferObservation {
                    sender,
                    receiver,
                    bond,
                    transferred_whole_carriers: signed.unsigned_abs(),
                },
            };
            match adjacent_layer {
                7 => association_influences.push(timed),
                8 => body_influences.push(timed),
                _ => {}
            }
        }
        association_influences.sort_unstable();
        body_influences.sort_unstable();
        let localized_plasticity_settlement = layer_ten_plasticity_settlements
            .iter()
            .find(|settlement| settlement.neuron_lineage == gradient.neuron_lineage)
            .map(|settlement| {
                let settlement_flat = topology_index.flat_for_lineage(settlement.neuron_lineage)?;
                let (settlement_cohort_index, settlement_neuron_index, _) =
                    flat_locations[settlement_flat];
                let successor_plastic_rest_length_nanometres =
                    cohorts[settlement_cohort_index].state.neurons()[settlement_neuron_index]
                        .plastic
                        .rest_length_nanometres();
                Ok(LocalAffectivePlasticitySettlementObservation {
                    cognitive_ordinal: settlement.cognitive_ordinal,
                    incident_catalyst_quanta: settlement.incident_catalyst_quanta,
                    reaction_extent: settlement.reaction_extent,
                    delivered_energy_zeptojoules: settlement.delivered_energy_zeptojoules,
                    predecessor_gate_work_residue_zeptojoules: settlement
                        .predecessor_gate_work_residue_zeptojoules
                        .clone(),
                    successor_gate_work_residue_zeptojoules: settlement
                        .successor_gate_work_residue_zeptojoules
                        .clone(),
                    predecessor_plastic_rest_length_nanometres: settlement
                        .predecessor_plastic_rest_length_nanometres,
                    successor_plastic_rest_length_nanometres,
                    predecessor_reservoir: settlement.predecessor_reservoir,
                    successor_reservoir: settlement.successor_reservoir,
                })
            })
            .transpose()?;
        affective_balance_trajectories.push(AffectiveBalanceTrajectoryObservation {
            neuron_lineage: gradient.neuron_lineage,
            neuron_place: gradient.neuron_place,
            association_influence: association_influences.first().copied(),
            body_influence: body_influences.first().copied(),
            localized_gradient_settlement: gradient.metabolic.changed().then_some(
                LocalAffectiveGradientSettlementObservation {
                    cognitive_ordinal,
                    predecessor_separated_elementary_charges: gradient
                        .predecessor_separated_elementary_charges,
                    post_gradient_separated_elementary_charges: gradient
                        .post_gradient_separated_elementary_charges,
                    interval_successor_separated_elementary_charges,
                    returned_elementary_charges: gradient.metabolic.returned_elementary_charges,
                    pumped_elementary_charges: gradient.metabolic.pumped_elementary_charges,
                    unreturned_elementary_charges: gradient.metabolic.unreturned_elementary_charges,
                    membrane_gradient_work_zeptojoules: gradient
                        .metabolic
                        .membrane_gradient_work_zeptojoules,
                    environment_energy_delivered_zeptojoules: gradient
                        .metabolic
                        .environment_energy_delivered_zeptojoules,
                    environment_heat_exported_zeptojoules: gradient
                        .metabolic
                        .environment_heat_exported_zeptojoules,
                },
            ),
            localized_plasticity_settlement,
        });
    }
    affective_balance_trajectories.sort_unstable_by_key(|entry| entry.neuron_lineage);
    localized_fluid_chemistry.sort_unstable_by_key(|entry| entry.neuron_lineage);
    if localized_fluid_chemistry.len() > 1 {
        let selected = localized_fluid_chemistry
            .iter()
            .find(|entry| {
                entry.unchanged_unreached_neuron_count != 0
                    || entry.unchanged_developmental_resting_neuron_count != 0
            })
            .or_else(|| localized_fluid_chemistry.first())
            .copied();
        localized_fluid_chemistry.clear();
        if let Some(selected) = selected {
            localized_fluid_chemistry.push(selected);
        }
    }
    let mut active_bonds = settled
        .transitions
        .iter()
        .zip(compact_bonds.iter().copied())
        .filter_map(|(transition, bond)| {
            (transition.outward_current_from_left_picoamperes.parts().0 != 0
                || transition.outward_elementary_charges_from_left != 0
                || transition.conductance_changed)
                .then_some(bond)
        })
        .collect::<Vec<_>>();
    active_bonds.sort_unstable();
    active_bonds.dedup();
    // Electrical settlement includes contacts among two immediate neighbours
    // so their exact local channel state remains physical.  Such a contact is
    // not, by that fact alone, evidence that the present causal frontier
    // reached it.  Only an active contact touching an explicit current seed
    // may authorize developmental growth or cognitive formation.
    let mut causal_active_bonds = settled
        .transitions
        .iter()
        .zip(compact_bonds.iter().copied())
        .zip(compact_edge_flat_endpoints.iter().copied())
        .filter_map(|((transition, bond), (left_flat, right_flat))| {
            (contact_touches_causal_seed(left_flat, right_flat, &causal_seed_flats)
                && (transition.outward_current_from_left_picoamperes.parts().0 != 0
                    || transition.outward_elementary_charges_from_left != 0
                    || transition.conductance_changed))
                .then_some(bond)
        })
        .collect::<Vec<_>>();
    causal_active_bonds.sort_unstable();
    causal_active_bonds.dedup();
    let mut frontier_routes = Vec::new();
    for ((transition, bond), (left_flat, right_flat)) in settled
        .transitions
        .iter()
        .zip(compact_bonds.iter().copied())
        .zip(compact_edge_flat_endpoints.iter().copied())
    {
        let left_seed = is_causal_seed(left_flat);
        let right_seed = is_causal_seed(right_flat);
        if left_seed == right_seed {
            continue;
        }
        let signed_from_left = transition.outward_elementary_charges_from_left;
        let current_from_left = transition.outward_current_from_left_picoamperes;
        let (
            seed_flat,
            adjacent_flat,
            outward_whole_carriers_from_seed,
            outward_current_from_seed_picoamperes,
        ) = if left_seed {
            (left_flat, right_flat, signed_from_left, current_from_left)
        } else {
            (
                right_flat,
                left_flat,
                signed_from_left
                    .checked_neg()
                    .ok_or(FormationError::ArithmeticOverflow)?,
                current_from_left
                    .checked_neg()
                    .map_err(|_| FormationError::ArithmeticOverflow)?,
            )
        };
        if !crosses_new_frontier_bond(seed_flat, bond) {
            continue;
        }
        let (seed_cohort, seed_neuron, seed_lineage) = flat_locations[seed_flat];
        let (adjacent_cohort, adjacent_neuron, adjacent_lineage) = flat_locations[adjacent_flat];
        frontier_routes.push(PhysicalFrontierRouteObservation {
            seed_lineage,
            seed_place: cohorts[seed_cohort].anatomy.mounts()[seed_neuron].place(),
            adjacent_lineage,
            adjacent_place: cohorts[adjacent_cohort].anatomy.mounts()[adjacent_neuron].place(),
            bond,
            outward_whole_carriers_from_seed,
            outward_current_from_seed_picoamperes,
        });
    }
    frontier_routes.sort_unstable_by_key(|route| {
        (
            route.seed_lineage,
            route.adjacent_lineage,
            route.bond.parallel_ordinal(),
        )
    });
    frontier_routes.dedup();
    // A nonzero whole-carrier transfer across the current causal boundary
    // changes both endpoint states, but only the previously unseeded endpoint
    // advances the one-contact causal wave. Preserve carrier direction and
    // advancing endpoint separately: current may physically flow into the
    // seed while the seed's changed potential causally reaches the supplying
    // neighbour. Carrying both endpoints would turn the already-reached
    // interior into a permanent seed and eventually poll the complete fabric.
    // Contacts with both or neither endpoint seeded do not advance this
    // cognitive boundary. Scheduled carrier crossings remain exact physical
    // settlement and wake changed endpoints' incident contacts below, but the
    // maintenance schedule has no authority to manufacture cognition, action,
    // learning, or a new causal frontier.
    // Candidate 93: preserve causal direction only on the exact learned
    // L11-to-L11 branch while real charge remains physically in flight. An
    // entry can arrive from the immediately preceding frontier or be founded
    // by work accepted by one vocal preparation in this interval. Distinct
    // bonds may fan out or converge through ordinary physics; two conflicting
    // orientations for the same exact bond are noncanonical and never resolved
    // by iteration order.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    struct VocalInFlightBranch {
        causal_source: [u8; 16],
        causal_destination: [u8; 16],
        external_ingress_cause: bool,
        accepts_reverse_transfer: bool,
    }
    let mut vocal_in_flight_branches =
        BTreeMap::<StablePhysicalBondReference, VocalInFlightBranch>::new();
    let mut admit_vocal_in_flight_branch = |bond: StablePhysicalBondReference,
                                            source: [u8; 16],
                                            destination: [u8; 16],
                                            external_ingress_cause: bool,
                                            accepts_reverse_transfer: bool|
     -> Result<(), FormationError> {
        let branch = VocalInFlightBranch {
            causal_source: source,
            causal_destination: destination,
            external_ingress_cause,
            accepts_reverse_transfer,
        };
        if let Some(existing) = vocal_in_flight_branches.insert(bond, branch) {
            if existing != branch {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            }
        }
        Ok(())
    };
    for entry in predecessor_frontier
        .iter()
        .copied()
        .filter(|entry| entry.is_in_flight())
    {
        let Some(cause) = entry.cause else {
            return Err(FormationError::NoncanonicalState);
        };
        let Some(source) = entry.sender() else {
            return Err(FormationError::NoncanonicalState);
        };
        let destination = entry.receiver();
        let matching = vocal_cognitive_action_continuation_routes_from_source(
            cohorts,
            topology_index,
            source,
        )?
        .into_iter()
        .filter(|route| {
            route.destination_ordering_lineage == destination
                && route.continuation_bond == cause.bond
        })
        .count();
        match matching {
            0 => continue,
            1 => admit_vocal_in_flight_branch(
                cause.bond,
                source,
                destination,
                entry.carries_external_ingress_cause(),
                false,
            )?,
            _ => return Err(FormationError::NeuronLineageAuthorityChanged),
        }
    }
    for entry in predecessor_frontier.iter().copied().filter(|entry| {
        entry
            .cause
            .is_some_and(|cause| cause.transferred_whole_carriers == 0)
            && entry.carries_external_ingress_cause()
    }) {
        let cause = entry.cause.ok_or(FormationError::NoncanonicalState)?;
        let association = entry.frontier_lineage();
        let Some(ordering) = vocal_action_preparation_from_association_founder(
            cohorts,
            topology_index,
            association,
            cause.bond,
        )?
        else {
            continue;
        };
        let sender = entry.sender().ok_or(FormationError::NoncanonicalState)?;
        if canonical_lineage_pair(sender, entry.receiver())
            != canonical_lineage_pair(association, ordering)
        {
            return Err(FormationError::NeuronLineageAuthorityChanged);
        }
        admit_vocal_in_flight_branch(cause.bond, association, ordering, true, true)?;
    }
    for ordering in permitted_vocal_ordering_work.iter().copied() {
        let preparation = vocal_action_preparation_for_ordering(cohorts, topology_index, ordering)?
            .ok_or(FormationError::NeuronLineageAuthorityChanged)?;
        for motor in preparation.motors {
            if !permitted_vocal_motor_bonds.contains(&motor.bond) {
                continue;
            }
            admit_vocal_in_flight_branch(
                motor.bond,
                ordering,
                motor.lineage,
                externally_permitted_vocal_motor_bonds.contains(&motor.bond),
                false,
            )?;
        }
    }
    if admit_learned_motor_work {
        for source in completed_vocal_orderings.iter().copied() {
            for route in vocal_cognitive_action_continuation_routes_from_source(
                cohorts,
                topology_index,
                source,
            )? {
                admit_vocal_in_flight_branch(
                    route.continuation_bond,
                    source,
                    route.destination_ordering_lineage,
                    false,
                    false,
                )?;
            }
        }
    }

    let mut next_active_frontier = Vec::new();
    for ((transition, bond), (left_flat, right_flat)) in settled
        .transitions
        .iter()
        .zip(&compact_bonds)
        .zip(compact_edge_flat_endpoints.iter().copied())
    {
        if let Some(branch) = vocal_in_flight_branches.get(bond).copied() {
            let source = branch.causal_source;
            let destination = branch.causal_destination;
            let left_lineage = flat_locations[left_flat].2;
            let right_lineage = flat_locations[right_flat].2;
            let source_is_left = if left_lineage == source && right_lineage == destination {
                true
            } else if left_lineage == destination && right_lineage == source {
                false
            } else {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            };
            let current_numerator = transition.outward_current_from_left_picoamperes.parts().0;
            let whole_from_source = if source_is_left {
                transition.outward_elementary_charges_from_left
            } else {
                transition
                    .outward_elementary_charges_from_left
                    .checked_neg()
                    .ok_or(FormationError::ArithmeticOverflow)?
            };
            let phase_numerator = transition.successor.carrier_phase().parts().0;
            let current_from_source = if source_is_left {
                current_numerator
            } else {
                current_numerator
                    .checked_neg()
                    .ok_or(FormationError::ArithmeticOverflow)?
            };
            let phase_from_source = if source_is_left {
                phase_numerator
            } else {
                phase_numerator
                    .checked_neg()
                    .ok_or(FormationError::ArithmeticOverflow)?
            };
            if branch.accepts_reverse_transfer {
                let signed_from_left = transition.outward_elementary_charges_from_left;
                let current_from_left = transition.outward_current_from_left_picoamperes.parts().0;
                let phase_from_left = transition.successor.carrier_phase().parts().0;
                let (physical_sender, physical_receiver) = if signed_from_left > 0
                    || (signed_from_left == 0 && current_from_left > 0)
                    || (signed_from_left == 0 && current_from_left == 0 && phase_from_left > 0)
                {
                    (left_lineage, right_lineage)
                } else {
                    (right_lineage, left_lineage)
                };
                if signed_from_left != 0 {
                    next_active_frontier.push(
                        ActiveElectricalFrontierEntry::caused_with_provenance(
                            physical_sender,
                            physical_receiver,
                            destination,
                            *bond,
                            signed_from_left.unsigned_abs(),
                            false,
                            branch.external_ingress_cause,
                        )?,
                    );
                } else if current_from_left != 0 && phase_from_left != 0 {
                    next_active_frontier.push(
                        ActiveElectricalFrontierEntry::causal_in_flight_with_provenance(
                            physical_sender,
                            physical_receiver,
                            destination,
                            *bond,
                            false,
                            branch.external_ingress_cause,
                        )?,
                    );
                }
            } else if whole_from_source > 0 {
                next_active_frontier.push(ActiveElectricalFrontierEntry::caused_with_provenance(
                    source,
                    destination,
                    destination,
                    *bond,
                    whole_from_source.unsigned_abs(),
                    false,
                    branch.external_ingress_cause,
                )?);
            } else if whole_from_source == 0 && current_from_source > 0 && phase_from_source > 0 {
                next_active_frontier.push(
                    ActiveElectricalFrontierEntry::causal_in_flight_with_provenance(
                        source,
                        destination,
                        source,
                        *bond,
                        false,
                        branch.external_ingress_cause,
                    )?,
                );
            }
            // Reverse current/crossing, zero current, or zero/reversed phase
            // expires this exact branch. Generic frontier logic must not
            // reinterpret that same physical contact after the refusal.
            continue;
        }
        let left_is_seed = is_causal_seed(left_flat);
        let right_is_seed = is_causal_seed(right_flat);
        let causal_crossing =
            causal_frontier_crossing(left_flat, right_flat, left_is_seed, right_is_seed);
        if transition.outward_elementary_charges_from_left == 0
            && admit_learned_motor_work
            && transition.outward_current_from_left_picoamperes.parts().0 != 0
            && transition.successor.carrier_phase().parts().0 != 0
        {
            if let Some((seed_flat, reached_flat)) = causal_crossing {
                if crosses_new_frontier_bond(seed_flat, *bond)
                    && !is_body_owned_acoustic_efference_seed(seed_flat)
                {
                    let current_from_left =
                        transition.outward_current_from_left_picoamperes.parts().0;
                    let (sender_flat, receiver_flat) = if current_from_left > 0 {
                        (left_flat, right_flat)
                    } else {
                        (right_flat, left_flat)
                    };
                    let candidate =
                        ActiveElectricalFrontierEntry::causal_in_flight_with_provenance(
                            flat_locations[sender_flat].2,
                            flat_locations[receiver_flat].2,
                            flat_locations[reached_flat].2,
                            *bond,
                            false,
                            is_external_ingress_seed(seed_flat),
                        )?;
                    if frontier_founds_vocal_action_preparation(cohorts, topology_index, candidate)?
                        .is_some()
                    {
                        next_active_frontier.push(candidate);
                    }
                }
            }
        }
        let Some(transfer) = directed_physical_transfer(
            transition.outward_elementary_charges_from_left,
            flat_locations[left_flat].2,
            flat_locations[right_flat].2,
            *bond,
        ) else {
            continue;
        };
        if let Some((seed_flat, reached_flat)) = causal_crossing {
            let frontier_lineage = flat_locations[reached_flat].2;
            // The incoming contact already delivered this causal wave. Its
            // continuing electrical current remains fully settled above, but
            // it cannot manufacture a new arrival by immediately sending the
            // same wave back across the same bond. A genuinely fresh external
            // or metabolic seed may lawfully use the bond again.
            if !crosses_new_frontier_bond(seed_flat, *bond) {
                continue;
            }
            let inherited_body_owned_acoustic_efference =
                is_body_owned_acoustic_efference_seed(seed_flat)
                    && fresh_seed_flats.binary_search(&seed_flat).is_err();
            let inherited_external_ingress = is_external_ingress_seed(seed_flat);
            let body_owned_acoustic_efference = !admit_learned_motor_work
                || (inherited_body_owned_acoustic_efference && !inherited_external_ingress);
            let external_ingress_cause = admit_learned_motor_work
                && inherited_external_ingress
                && !inherited_body_owned_acoustic_efference;
            next_active_frontier.push(ActiveElectricalFrontierEntry::caused_with_provenance(
                transfer.sender,
                transfer.receiver,
                frontier_lineage,
                *bond,
                transfer.transferred_whole_carriers,
                body_owned_acoustic_efference,
                external_ingress_cause,
            )?);
        }
    }
    next_active_frontier.extend(directed_continuation_work_frontiers);
    next_active_frontier.sort_unstable();
    next_active_frontier.dedup();
    // One shared full-field occurrence was evaluated for the entire reached
    // contact frontier, irrespective of how many neurons received their
    // coordinate-local perspectives.
    // Event bookkeeping for the next clocks, read from the fully applied
    // state: every settled contact is marked integrated at this clock and
    // rescheduled from its successor state under the settlement authority;
    // every reached neuron's membrane-recovery event is rescheduled from
    // its own settled anatomy. Untouched contacts and neurons keep their
    // standing schedules — nothing about them changed.
    {
        let interval =
            u32::try_from(interval_microseconds).map_err(|_| FormationError::ArithmeticOverflow)?;
        // One endpoint read per reached neuron, not per contact: the
        // applied post-settlement material of every selected flat, once.
        // Alongside it, the wake law's exact changed-endpoint set: every
        // selected neuron whose physical state this interval actually
        // changed — by pumping, passive recovery, membrane settlement,
        // external ingress, or contact transfer. An unchanged endpoint
        // wakes nothing.
        let mut endpoint_cache = BTreeMap::new();
        for flat in selected.iter().copied() {
            let (cohort_index, neuron_index, _) = flat_locations[flat];
            let state = &cohorts[cohort_index].state.neurons()[neuron_index];
            let capacitance =
                cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index].capacitance();
            let membrane = state.membrane_state();
            endpoint_cache.insert(
                flat,
                (
                    membrane
                        .potential_millivolts(capacitance)
                        .map_err(FormationError::InternalMembraneUnavailable)?,
                    membrane.separated_elementary_charges(),
                    capacitance,
                    state.carrier_reservoirs().intracellular(),
                ),
            );
        }
        // The wake law's changed-endpoint set is UNIVERSAL: every neuron
        // whose state at this interval's end differs from the entry view —
        // external ingress (a silent zero-work settlement included),
        // pumping, passive recovery, membrane settlement, or contact
        // transfer. A receptor changed by silence is still a changed
        // endpoint, even though silence originates no causal frontier.
        let mut change_candidates = selected.iter().copied().collect::<BTreeSet<_>>();
        for lineage in pre_source_membranes.keys().copied() {
            change_candidates.insert(topology_index.flat_for_lineage(lineage)?);
        }
        change_candidates.extend(passive_return_changed_flats.iter().copied());
        change_candidates.extend(co_recruited_articulatory_flats.iter().copied());
        let mut changed_flats = Vec::new();
        for flat in change_candidates {
            let (cohort_index, neuron_index, lineage) = flat_locations[flat];
            let state = &cohorts[cohort_index].state.neurons()[neuron_index];
            let source_changed = pre_source_membranes
                .get(&lineage)
                .map(|(held_membrane, held_intracellular, held_extracellular)| {
                    *held_membrane != state.membrane_state()
                        || *held_intracellular != state.carrier_reservoirs().intracellular()
                        || *held_extracellular != state.carrier_reservoirs().extracellular()
                })
                .unwrap_or(false);
            let selected_changed = selected_predecessor_neurons
                .get(&cohort_index)
                .and_then(|predecessors| {
                    predecessors
                        .binary_search_by_key(&neuron_index, |(candidate, _)| *candidate)
                        .ok()
                        .map(|position| &predecessors[position])
                })
                .is_some_and(|(_, predecessor)| predecessor != state);
            let passive_return_changed = passive_return_changed_flats.binary_search(&flat).is_ok();
            let articulatory_changed = co_recruited_articulatory_flats.contains(&flat);
            if source_changed || selected_changed || passive_return_changed || articulatory_changed
            {
                changed_flats.push(flat);
            }
        }
        for (position, contact_index) in compact_original_indices.iter().copied().enumerate() {
            events.contact_last_integrated[contact_index] = clock;
            let transition = &settled.transitions[position];
            let successor_state = &transition.successor;
            let (left_flat, right_flat) = compact_edge_flat_endpoints[position];
            let (left_potential, left_charges, left_capacitance, left_available) = endpoint_cache
                .get(&left_flat)
                .ok_or(FormationError::NoncanonicalState)?;
            let (right_potential, right_charges, right_capacitance, right_available) =
                endpoint_cache
                    .get(&right_flat)
                    .ok_or(FormationError::NoncanonicalState)?;
            // Two exact tiers. An ACTIVELY settled contact (whole carriers
            // moved or channels transitioned) reschedules from its raw
            // Ohmic drive without re-proving energy descent: if the pair
            // has in fact come to rest, its scheduled clock settles it
            // quiescently exactly once and THAT settlement pays the full
            // authority, unscheduling it for good. A QUIESCENTLY settled
            // contact pays the full settlement authority now — the only
            // path that may refuse forever, so the only one needing the
            // refusal proof. No polling loop can form: active -> at most
            // one quiescent settle -> authority decision.
            let actively_settled = transition.outward_elementary_charges_from_left != 0
                || transition.conductance_changed;
            let standing = if actively_settled {
                let difference = left_potential
                    .checked_sub(*right_potential)
                    .map_err(|_| FormationError::ArithmeticOverflow)?;
                let raw = compact_anatomy.contact_anatomies()[position]
                    .effective_conductance(successor_state)
                    .map_err(FormationError::ResidentElectricalUnavailable)?
                    .checked_mul(difference)
                    .map_err(|_| FormationError::ArithmeticOverflow)?
                    .checked_div_unsigned(1_000)
                    .map_err(|_| FormationError::ArithmeticOverflow)?;
                (raw.parts().0 != 0).then_some(raw)
            } else {
                crate::sparse_electrical_contact::standing_contact_current(
                    compact_anatomy.contact_anatomies()[position],
                    successor_state,
                    *left_potential,
                    *left_charges,
                    *left_capacitance,
                    *left_available,
                    *right_potential,
                    *right_charges,
                    *right_capacitance,
                    *right_available,
                )
                .map_err(FormationError::ResidentElectricalUnavailable)?
            };
            let due = match standing {
                Some(current) => {
                    crate::elementary_charge_transfer::next_whole_carrier_crossing_clocks(
                        successor_state.carrier_phase(),
                        current,
                        interval,
                    )
                    .map_err(|_| FormationError::ArithmeticOverflow)?
                    .map(|clocks_until| {
                        clock
                            .checked_add(clocks_until)
                            .ok_or(FormationError::ArithmeticOverflow)
                    })
                    .transpose()?
                }
                None => None,
            };
            events
                .contact_schedule
                .reschedule_from_clock(clock, contact_index, due);
        }
        // The wake law: a changed endpoint wakes EVERY contact incident to
        // it, now — adding it to a later frontier is insufficient. A
        // sleeping incident contact first catches up exactly through the
        // pre-change span (its drive was frozen at the pre-pump
        // predecessor values this interval still holds), then reschedules
        // from its caught-up phase under the settlement authority against
        // the changed successor endpoints.
        let mut woken_contacts = Vec::new();
        for flat in changed_flats.iter().copied() {
            woken_contacts.extend(
                topology_index
                    .incident_contacts_by_flat
                    .get(flat)
                    .ok_or(FormationError::NeuronLineageAuthorityAbsent)?
                    .iter()
                    .copied(),
            );
        }
        woken_contacts.sort_unstable();
        woken_contacts.dedup();
        for contact_index in woken_contacts {
            if compact_original_indices
                .binary_search(&contact_index)
                .is_ok()
            {
                continue;
            }
            let entry = topology_index.contacts[contact_index];
            let edge = materialize_resident_contact_edge(entry, cohorts, electrical_fabric)?;
            let mut sleeping_state = edge.state;
            let last = events.contact_last_integrated[contact_index];
            // The endpoint's change reaches this sleeping neighbour at the
            // NEXT clock (the one-clock arrival law), so the sleeping span
            // integrates THROUGH this clock at the held pre-change drive;
            // the new drive counts from here.
            let span_end = clock;
            if last < span_end {
                // Pre-change drive: each endpoint as it stood before this
                // interval — the predecessor clone when the endpoint was
                // selected, its untouched live state otherwise.
                let sleeping_endpoint = |flat: usize| -> Result<
                    (
                        crate::elementary_charge_membrane::ElementaryChargeMembraneState,
                        crate::elementary_charge_membrane::MembraneCapacitance,
                        u128,
                    ),
                    FormationError,
                > {
                    let (cohort_index, neuron_index, lineage) = flat_locations[flat];
                    let capacitance = cohorts[cohort_index].anatomy.neuron_anatomies()
                        [neuron_index]
                        .capacitance();
                    if let Some((membrane, available, _)) = pre_source_membranes.get(&lineage) {
                        return Ok((*membrane, capacitance, *available));
                    }
                    if let Ok(coordinate) = selected.binary_search(&flat) {
                        Ok((
                            pre_pump_membranes[coordinate]
                                .ok_or(FormationError::NoncanonicalState)?,
                            capacitance,
                            pre_pump_available[coordinate],
                        ))
                    } else {
                        let state = &cohorts[cohort_index].state.neurons()[neuron_index];
                        Ok((
                            state.membrane_state(),
                            capacitance,
                            state.carrier_reservoirs().intracellular(),
                        ))
                    }
                };
                let (left_membrane, left_capacitance, left_available) =
                    sleeping_endpoint(edge.left)?;
                let (right_membrane, right_capacitance, right_available) =
                    sleeping_endpoint(edge.right)?;
                let left_potential = left_membrane
                    .potential_millivolts(left_capacitance)
                    .map_err(FormationError::InternalMembraneUnavailable)?;
                let right_potential = right_membrane
                    .potential_millivolts(right_capacitance)
                    .map_err(FormationError::InternalMembraneUnavailable)?;
                let standing = crate::sparse_electrical_contact::standing_contact_current(
                    edge.anatomy,
                    &sleeping_state,
                    left_potential,
                    left_membrane.separated_elementary_charges(),
                    left_capacitance,
                    left_available,
                    right_potential,
                    right_membrane.separated_elementary_charges(),
                    right_capacitance,
                    right_available,
                )
                .map_err(FormationError::ResidentElectricalUnavailable)?;
                if let Some(standing_current) = standing {
                    let potential_difference = left_potential
                        .checked_sub(right_potential)
                        .map_err(|_| FormationError::ArithmeticOverflow)?;
                    let caught = crate::causal_event_scheduler::catch_up_sleeping_contact(
                        crate::causal_event_scheduler::ContactIntegrationClock {
                            last_integrated_clock: last,
                        },
                        span_end,
                        sleeping_state.carrier_phase(),
                        sleeping_state.transition_work_phase(),
                        standing_current,
                        potential_difference,
                        interval,
                    )
                    .map_err(|_| FormationError::ArithmeticOverflow)?;
                    assert_eq!(
                        caught.outward_elementary_charges,
                        0,
                        "a sleeping span crossed a whole carrier without its \
                         scheduled wake — the causal event schedule is unsound; \
                         contact={contact_index} last={last} span_end={span_end} \
                         clock={clock} rebuilt={needs_rebuild} \
                         endpoints=({}, {}) predecessor_phase={:?} current={:?} \
                         left_charges={} right_charges={} left_available={} \
                         right_available={}",
                        edge.left,
                        edge.right,
                        sleeping_state.carrier_phase().parts(),
                        standing_current.parts(),
                        left_membrane.separated_elementary_charges(),
                        right_membrane.separated_elementary_charges(),
                        left_available,
                        right_available,
                    );
                    sleeping_state =
                        sleeping_state.with_caught_up_carrier_phase(caught.successor_phase);
                    match edge.origin {
                        ResidentContactOrigin::Fabric { contact_index } => {
                            electrical_fabric
                                .replace_contact_states(vec![(
                                    contact_index,
                                    sleeping_state.clone(),
                                )])
                                .map_err(FormationError::ResidentElectricalUnavailable)?;
                        }
                        ResidentContactOrigin::Local {
                            cohort_index,
                            contact_index,
                            ..
                        } => {
                            Arc::make_mut(&mut cohorts[cohort_index].state)
                                .replace_electrical_contact_state(
                                    contact_index,
                                    sleeping_state.clone(),
                                )
                                .map_err(FormationError::ResidentElectricalUnavailable)?;
                        }
                    }
                }
            }
            events.contact_last_integrated[contact_index] = span_end;
            // New drive from the changed successor endpoints, full authority.
            let successor_endpoint = |flat: usize| -> Result<
                (
                    crate::exact_rational::ExactRational,
                    i128,
                    crate::elementary_charge_membrane::MembraneCapacitance,
                    u128,
                ),
                FormationError,
            > {
                if let Some(cached) = endpoint_cache.get(&flat) {
                    return Ok(cached.clone());
                }
                let (cohort_index, neuron_index, _) = flat_locations[flat];
                let state = &cohorts[cohort_index].state.neurons()[neuron_index];
                let capacitance =
                    cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index].capacitance();
                let membrane = state.membrane_state();
                Ok((
                    membrane
                        .potential_millivolts(capacitance)
                        .map_err(FormationError::InternalMembraneUnavailable)?,
                    membrane.separated_elementary_charges(),
                    capacitance,
                    state.carrier_reservoirs().intracellular(),
                ))
            };
            let (left_potential, left_charges, left_capacitance, left_available) =
                successor_endpoint(edge.left)?;
            let (right_potential, right_charges, right_capacitance, right_available) =
                successor_endpoint(edge.right)?;
            let standing = crate::sparse_electrical_contact::standing_contact_current(
                edge.anatomy,
                &sleeping_state,
                left_potential,
                left_charges,
                left_capacitance,
                left_available,
                right_potential,
                right_charges,
                right_capacitance,
                right_available,
            )
            .map_err(FormationError::ResidentElectricalUnavailable)?;
            let due = match standing {
                Some(current) => {
                    crate::elementary_charge_transfer::next_whole_carrier_crossing_clocks(
                        sleeping_state.carrier_phase(),
                        current,
                        interval,
                    )
                    .map_err(|_| FormationError::ArithmeticOverflow)?
                    .map(|clocks_until| {
                        clock
                            .checked_add(clocks_until)
                            .ok_or(FormationError::ArithmeticOverflow)
                    })
                    .transpose()?
                }
                None => None,
            };
            events
                .contact_schedule
                .reschedule_from_clock(clock, contact_index, due);
        }
        for flat in changed_flats.iter().copied() {
            let (cohort_index, neuron_index, lineage) = flat_locations[flat];
            // The neuron's displacement changed this clock, so its return
            // rate changed. Catch its return phase up through this clock
            // at the HELD pre-change rate first — the change reaches this
            // separate path at the next clock — then reschedule under the
            // new rate. A crossing inside the caught-up span cannot occur:
            // its due would have fired.
            let last = events.recovery_last_integrated[flat];
            let scheduled_return_due = events.recovery_schedule.due_clock(flat);
            if last < clock {
                // An unscheduled return means the descent law refused its
                // current for the whole span: zero flow, frozen phase.
                // Only a scheduled span integrates, at the exact held
                // state's current — membrane and compartments together.
                if scheduled_return_due.is_none() {
                    events.recovery_last_integrated[flat] = clock;
                } else if let Some((held_membrane, held_intracellular, held_extracellular)) =
                    pre_source_membranes.get(&lineage)
                {
                    let held_state = crate::complete_neuron::with_held_membrane_and_carriers(
                        &cohorts[cohort_index].state.neurons()[neuron_index],
                        *held_membrane,
                        *held_intracellular,
                        *held_extracellular,
                    );
                    let held_current = crate::complete_neuron::passive_membrane_return_current(
                        &cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index],
                        &held_state,
                    )
                    .map_err(|error| {
                        FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                            neuron_index,
                            error,
                        })
                    })?;
                    if let Some(current) = held_current {
                        let caught =
                            crate::elementary_charge_transfer::settle_elementary_charge_transfer_clocks(
                                events.recovery_phase[flat],
                                current,
                                interval,
                                clock - last,
                            )
                            .map_err(|_| FormationError::ArithmeticOverflow)?;
                        assert_eq!(
                            caught.outward_elementary_charges,
                            0,
                            "a sleeping membrane return crossed without its \
                             scheduled event — the return schedule is unsound; \
                             flat={flat} lineage={lineage:?} last={last} \
                             clock={clock} due={scheduled_return_due:?} \
                             phase={:?} current={:?} held_charges={} \
                             held_intracellular={} held_extracellular={}",
                            events.recovery_phase[flat].parts(),
                            current.parts(),
                            held_membrane.separated_elementary_charges(),
                            held_intracellular,
                            held_extracellular,
                        );
                        events.recovery_phase[flat] = caught.successor_phase;
                    }
                }
                events.recovery_last_integrated[flat] = clock;
            }
            let mount = &cohorts[cohort_index].anatomy.mounts()[neuron_index];
            let neuron = &cohorts[cohort_index].state.neurons()[neuron_index];
            let coordinated_vocal_preparation = mount.place().layer() == 11
                && vocal_action_preparation_for_ordering(cohorts, topology_index, lineage)?
                    .is_some();
            let mounted_terminal_ready = terminal_retains_prepared_action_charge(
                mount,
                neuron,
                coordinated_vocal_preparation,
            );
            let due = if mounted_terminal_ready {
                Some(
                    clock
                        .checked_add(1)
                        .ok_or(FormationError::ArithmeticOverflow)?,
                )
            } else {
                crate::complete_neuron::next_passive_membrane_return_crossing_clocks(
                    &cohorts[cohort_index].anatomy.neuron_anatomies()[neuron_index],
                    neuron,
                    events.recovery_phase[flat],
                    interval,
                )
                .map_err(|error| {
                    FormationError::PhysicalSettlementUnavailable(ReachedCohortError::Neuron {
                        neuron_index,
                        error,
                    })
                })?
                .map(|clocks_until| {
                    clock
                        .checked_add(clocks_until)
                        .ok_or(FormationError::ArithmeticOverflow)
                })
                .transpose()?
            };
            events
                .recovery_schedule
                .reschedule_from_clock(clock, flat, due);
        }
    }
    Ok(InternalContactSettlementObservation {
        dsf_delivery_count: 1,
        active_bonds,
        causal_active_bonds,
        causally_transitioned_lineages: causally_active_lineages.into_iter().collect(),
        changed_contact_channel_states,
        frontier_routes,
        next_active_frontier,
        settled_directed_transfers,
        metabolically_perturbed_body_receptor_lineages,
        affective_balance_trajectories,
        localized_fluid_chemistry,
        deferred_vocal_work_offers,
        learned_motor_work_preparations,
        motor_unit_recruitments,
        completed_vocal_orderings,
        root_yaw_unit_recruitments,
        root_translation_unit_recruitments,
        articulatory_unit_recruitments,
        emitted_neuron_fractals,
        passive_membrane_returned_neuron_lineages,
        transition_predecessors,
    })
}

fn exact_rational_binary64(value: ExactRational) -> Result<f64, FormationError> {
    let (numerator, denominator) = value.parts();
    let numerator = numerator
        .to_f64()
        .filter(|value| value.is_finite())
        .ok_or(FormationError::ArithmeticOverflow)?;
    let denominator = denominator
        .to_f64()
        .filter(|value| value.is_finite() && *value > 0.0)
        .ok_or(FormationError::ArithmeticOverflow)?;
    let value = numerator / denominator;
    value
        .is_finite()
        .then_some(value)
        .ok_or(FormationError::ArithmeticOverflow)
}

fn contact_components(neuron_count: usize, anatomy: &SparseElectricalAnatomy) -> Vec<Vec<usize>> {
    let mut visited = vec![false; neuron_count];
    // Build the exact sparse incidence surface once. The former traversal
    // rescanned every contact for every neuron reached by a component, making
    // one physical interval O(neurons * contacts). Contacts are appended to
    // each endpoint in canonical contact order, so the breadth-first member
    // order remains identical to the former contact-order scan.
    let mut neighbours = std::iter::repeat_with(Vec::new)
        .take(neuron_count)
        .collect::<Vec<Vec<usize>>>();
    for (left, right) in anatomy.contact_endpoints() {
        neighbours[left].push(right);
        neighbours[right].push(left);
    }
    let mut groups = Vec::new();
    for start in 0..neuron_count {
        if visited[start] {
            continue;
        }
        visited[start] = true;
        let mut group = vec![start];
        let mut cursor = 0usize;
        while cursor < group.len() {
            let member = group[cursor];
            for neighbour in neighbours[member].iter().copied() {
                if !visited[neighbour] {
                    visited[neighbour] = true;
                    group.push(neighbour);
                }
            }
            cursor += 1;
        }
        groups.push(group);
    }
    groups
}

fn encode_internal_contact_source(
    selected: &[usize],
    flat_locations: &[(usize, usize, [u8; 16])],
    predecessor_membranes: &[crate::elementary_charge_membrane::ElementaryChargeMembraneState],
    successor_membranes: &[crate::elementary_charge_membrane::ElementaryChargeMembraneState],
    capacitances: &[crate::elementary_charge_membrane::MembraneCapacitance],
    interval_microseconds: u32,
    electrical: &SparseElectricalAnatomy,
    electrical_state: &SparseElectricalState,
) -> Result<Vec<u8>, FormationError> {
    if electrical.contact_count() != electrical_state.contact_count() {
        return Err(FormationError::NoncanonicalState);
    }
    let mut encoded = Vec::new();
    encoded.extend_from_slice(b"GLINT02\0");
    encoded.extend_from_slice(&interval_microseconds.to_le_bytes());
    push_length(&mut encoded, selected.len())?;
    for (coordinate, flat) in selected.iter().copied().enumerate() {
        encoded.extend_from_slice(&flat_locations[flat].2);
        encoded.extend_from_slice(
            &predecessor_membranes[coordinate]
                .separated_elementary_charges()
                .to_le_bytes(),
        );
        encoded.extend_from_slice(
            &successor_membranes[coordinate]
                .separated_elementary_charges()
                .to_le_bytes(),
        );
        let (numerator, denominator) = capacitances[coordinate].picofarads().parts();
        encoded.extend_from_slice(&numerator.to_le_bytes());
        encoded.extend_from_slice(&denominator.to_le_bytes());
    }
    push_length(&mut encoded, electrical.contact_count())?;
    for (contact, state) in electrical
        .contact_anatomies()
        .iter()
        .zip(electrical_state.contact_states())
    {
        let (left, right) = contact.endpoints();
        push_length(&mut encoded, left)?;
        push_length(&mut encoded, right)?;
        let (numerator, denominator) = contact
            .effective_conductance(state)
            .map_err(FormationError::ResidentElectricalUnavailable)?
            .parts();
        encoded.extend_from_slice(&numerator.to_le_bytes());
        encoded.extend_from_slice(&denominator.to_le_bytes());
    }
    Ok(encoded)
}

fn resolve_dormant_lineage_for_port(
    dormant: &[DormantLineageSeed],
    port: &crate::joint_source_episode::JointSourcePortView,
) -> Result<Option<[u8; 16]>, FormationError> {
    let mut resolved = None;
    for seed in dormant {
        if seed.matches_port(port) {
            if resolved.is_some_and(|prior| prior != seed.neuron_lineage) {
                return Err(FormationError::NeuronLineageAuthorityChanged);
            }
            resolved = Some(seed.neuron_lineage);
        }
    }
    Ok(resolved)
}

fn validate_lineage_state(state: &ResidentCognitiveFormationState) -> Result<(), FormationError> {
    if state.next_lineage_ordinal == 0 {
        return Err(FormationError::NoncanonicalState);
    }
    let mut retained_sources = Vec::new();
    let mut reached_lineages = Vec::new();
    let mut reached_places = Vec::new();
    for cohort in &state.cohorts {
        for (mount, lineage) in cohort
            .anatomy
            .mounts()
            .iter()
            .zip(cohort.anatomy.neuron_lineages())
        {
            let place = mount.place();
            if lineage_ordinal(*lineage)? >= state.next_lineage_ordinal
                || reached_lineages.contains(lineage)
                || reached_places.contains(&place)
            {
                return Err(FormationError::NoncanonicalState);
            }
            reached_lineages.push(*lineage);
            reached_places.push(place);
            if let Some(site) = mount.source_site() {
                let seed = DormantLineageSeed::from_site(site, *lineage)?;
                if retained_sources.iter().any(|prior: &DormantLineageSeed| {
                    prior.same_source(&seed) || prior.neuron_lineage == seed.neuron_lineage
                }) {
                    return Err(FormationError::NoncanonicalState);
                }
                retained_sources.push(seed);
            }
        }
    }
    for (index, seed) in state.dormant_lineage_seeds.iter().enumerate() {
        seed.validate()?;
        if lineage_ordinal(seed.neuron_lineage)? >= state.next_lineage_ordinal
            || state.dormant_lineage_seeds[..index].iter().any(|prior| {
                prior >= seed
                    || prior.same_source(seed)
                    || prior.neuron_lineage == seed.neuron_lineage
            })
            || reached_lineages.contains(&seed.neuron_lineage)
            || retained_sources
                .iter()
                .any(|prior| prior.same_source(seed) || prior.neuron_lineage == seed.neuron_lineage)
        {
            return Err(FormationError::NoncanonicalState);
        }
        retained_sources.push(seed.clone());
    }
    if state
        .electrical_fabric
        .lineages()
        .iter()
        .any(|lineage| !reached_lineages.contains(lineage))
    {
        return Err(FormationError::NoncanonicalState);
    }
    let physical_bonds = organism_physical_bonds(&state.cohorts, &state.electrical_fabric)?;
    let invalid_frontier = |frontier: &[ActiveElectricalFrontierEntry]| {
        frontier.iter().enumerate().any(|(index, entry)| {
            let lineage = entry.receiver();
            let invalid_cause = entry.cause.is_some_and(|cause| {
                (cause.transferred_whole_carriers == 0 && !entry.is_zero_carrier_frontier())
                    || physical_bonds.binary_search(&cause.bond).is_err()
                    || entry.sender().is_none()
            });
            reached_lineages
                .iter()
                .position(|candidate| *candidate == lineage)
                .and_then(|position| reached_places.get(position))
                .is_none()
                || invalid_cause
                || (index > 0 && frontier[index - 1] >= *entry)
        })
    };
    if invalid_frontier(&state.older_active_electrical_frontier)
        || invalid_frontier(&state.preceding_active_electrical_frontier)
        || invalid_frontier(&state.active_electrical_frontier)
    {
        return Err(FormationError::NoncanonicalState);
    }
    if let Some(population) = &state.resting_population {
        if population.lineage_end_exclusive() > state.next_lineage_ordinal
            || reached_lineages
                .iter()
                .zip(reached_places.iter())
                .any(|(lineage, place)| {
                    let Ok(ordinal) = lineage_ordinal(*lineage) else {
                        return true;
                    };
                    if ordinal < population.lineage_start_ordinal()
                        || ordinal >= population.lineage_end_exclusive()
                    {
                        return false;
                    }
                    population.materialized_lineage_ordinal(*place) != Some(ordinal)
                })
        {
            return Err(FormationError::NoncanonicalState);
        }
    }
    Ok(())
}

fn encode_dormant_lineage_seed(seed: &DormantLineageSeed) -> Result<Vec<u8>, FormationError> {
    seed.validate()?;
    let mut output = Vec::new();
    output.extend_from_slice(DORMANT_LINEAGE_SEED_MAGIC);
    output.push(seed.sense);
    output.extend_from_slice(&seed.topology_index.to_le_bytes());
    push_seed_text(&mut output, &seed.sensor_id)?;
    push_seed_text(&mut output, &seed.substream_id)?;
    output.extend_from_slice(&seed.neuron_lineage);
    Ok(output)
}

fn decode_dormant_lineage_seed(encoded: &[u8]) -> Result<DormantLineageSeed, FormationError> {
    if encoded.get(..DORMANT_LINEAGE_SEED_MAGIC.len()) != Some(DORMANT_LINEAGE_SEED_MAGIC) {
        return Err(FormationError::NoncanonicalState);
    }
    let mut cursor = DORMANT_LINEAGE_SEED_MAGIC.len();
    let sense = *encoded
        .get(cursor)
        .ok_or(FormationError::NoncanonicalState)?;
    cursor += 1;
    let topology_end = cursor
        .checked_add(4)
        .ok_or(FormationError::ArithmeticOverflow)?;
    let topology_index = u32::from_le_bytes(
        encoded
            .get(cursor..topology_end)
            .ok_or(FormationError::NoncanonicalState)?
            .try_into()
            .map_err(|_| FormationError::NoncanonicalState)?,
    );
    cursor = topology_end;
    let sensor_id = take_seed_text(encoded, &mut cursor)?;
    let substream_id = take_seed_text(encoded, &mut cursor)?;
    let lineage_end = cursor
        .checked_add(16)
        .ok_or(FormationError::ArithmeticOverflow)?;
    let neuron_lineage = encoded
        .get(cursor..lineage_end)
        .ok_or(FormationError::NoncanonicalState)?
        .try_into()
        .map_err(|_| FormationError::NoncanonicalState)?;
    if lineage_end != encoded.len() {
        return Err(FormationError::NoncanonicalState);
    }
    DormantLineageSeed::new(
        sense,
        topology_index,
        &sensor_id,
        &substream_id,
        neuron_lineage,
    )
}

fn push_seed_text(output: &mut Vec<u8>, value: &str) -> Result<(), FormationError> {
    push_length(output, value.len())?;
    output.extend_from_slice(value.as_bytes());
    Ok(())
}

fn take_seed_text(encoded: &[u8], cursor: &mut usize) -> Result<String, FormationError> {
    let length = read_length(encoded, cursor)?;
    let end = cursor
        .checked_add(length)
        .ok_or(FormationError::ArithmeticOverflow)?;
    let value = std::str::from_utf8(
        encoded
            .get(*cursor..end)
            .ok_or(FormationError::NoncanonicalState)?,
    )
    .map_err(|_| FormationError::NoncanonicalState)?;
    *cursor = end;
    if value.is_empty() {
        return Err(FormationError::NoncanonicalState);
    }
    Ok(value.to_owned())
}

fn take_state_u64(encoded: &[u8], cursor: &mut usize) -> Result<u64, FormationError> {
    let end = cursor
        .checked_add(8)
        .ok_or(FormationError::ArithmeticOverflow)?;
    let value = u64::from_le_bytes(
        encoded
            .get(*cursor..end)
            .ok_or(FormationError::NoncanonicalState)?
            .try_into()
            .map_err(|_| FormationError::NoncanonicalState)?,
    );
    *cursor = end;
    Ok(value)
}

